insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِالْجِعْرَانَةِ بَعْدَ أَنْ رَجَعَ مِنَ الطَّائِفِ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي نَذَرْتُ فِي الْجَاهِلِيَّةِ أَنْ أَعْتَكِفَ يَوْمًا فِي الْمَسْجِدِ الْحَرَامِ، فَكَيْفَ تَرَى؟ قَالَ: "اذْهَبْ فَاعْتَكِفْ يَوْمًا". قَالَ: وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ أَعْطَاهُ جَارِيَةً مِنَ الْخُمُسِ، فَلَمَّا أَعْتَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبَايَا النَّاسِ سَمِعَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ أَصْوَاتَهُمْ يَقُولُونَ: أَعْتَقَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: مَا هَذَا؟ فَقَالُوا: أَعْتَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَبَايَا النَّاسِ. فَقَالَ عُمَرُ: يَا عَبْدَ اللَّهِ، اذْهَبْ إِلَى تِلْكَ الْجَارِيَةِ فَخَلِّ سَبِيلَهَا. (م)', 'ഇബ്നുഉമർ(റ): നബി(സ) ത്വാഇഫിൽനിന്ന് മടങ്ങവേ ജിഅ്റാൻ എന്ന ദേശത്തെത്തിയപ്പോൾ ഉമർ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, മസ്ജിദുൽ ഹറാമിൽ ഒരു ദിവസം ഭജനമിരിക്കാമെന്ന് ജാഹിലിയ്യാ കാലത്ത് ഞാൻ ഒരു നേർച്ച നേർന്നിരുന്നു. അങ്ങയുടെ അഭിപ്രായം എന്താണ്? തിരുമേനി(സ) പ്രതിവചിച്ചു: "പോകൂ, പോയി ഒരു ദിവസം ഭജനമിരിക്കൂ." ഇബ്നുഉമർ(റ) തുടർന്നു: നബി(സ) അഞ്ചിലൊന്ന് വിഹിതത്തിൽ നിന്ന് ഒരു അടിമസ്ത്രീയെ ഉമർ(റ)വിന് നൽകിയിരുന്നു. അങ്ങനെയിരിക്കെ ബന്ധനസ്ഥനായിരുന്ന അടിമകളെ നബി(സ) മോചിപ്പിച്ചു. ഞങ്ങളെ നബി തിരുമേനി(സ) മോചിപ്പിച്ചു എന്ന് അവർ ആഹ്ലാദചിത്തരായി വിളിച്ചുപറഞ്ഞുകൊണ്ടിരുന്നത് കേൾക്കാൻ ഇടയായ ഉമർ(റ) കാര്യം എന്താണെന്നന്വേഷിച്ചു. തിരുമേനി(സ) യുദ്ധത്തടവുകാരെയെല്ലാം സ്വതന്ത്രരാക്കി വിട്ടയച്ചുവെന്ന് ആളുകൾ മറുപടി നൽകി. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അബ്ദുല്ലാ, പോകൂ, ആ അടിമസ്ത്രീയെ മോചിപ്പിക്കൂ. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 569, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ ثَابِتِ بْنِ الضَّحَّاكِ رَضِيَ اللهُ عَنْهُ قَالَ: نَذَرَ رَجُلٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَنْحَرَ إِبِلًا بِبُوَانَةَ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي نَذَرْتُ أَنْ أَنْحَرَ إِبِلًا بِبُوَانَةَ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ كَانَ فِيهَا وَثَنٌ مِنْ أَوْثَانِ الْجَاهِلِيَّةِ يُعْبَدُ". قَالُوا: لَا، قَالَ: "هَلْ كَانَ فِيهَا عِيدٌ مِنْ أَعْيَادِهِمْ". قَالُوا: لَا، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَوْفِ بِنَذْرِكَ، فَإِنَّهُ لَا وَفَاءَ لِنَذْرٍ فِي مَعْصِيَةِ اللَّهِ، وَلَا فِيمَا لَا يَمْلِكُ ابْنُ آدَمَ". (د)', 'സാബിതുബ്നു ളഹ്ഹാക്(റ): റസൂൽ(സ)യുടെ കാലത്ത് ഒരാൾ ബുവാനാ എന്ന സ്ഥലത്ത് ഒരു ഒട്ടകത്തെ അറുക്കാമെന്ന് നേർച്ചനേർന്നിരുന്നു. നബി(സ)യെ സമീപിച്ച് അയാൾ പറഞ്ഞു: ബുവാനയിൽ വെച്ച് ഒരു ഒട്ടകത്തെ അറുക്കാമെന്ന് ഞാൻ നേർച്ചനേർന്നിരുന്നു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ജാഹിലിയ്യാ കാലത്ത് ആരാധിച്ചിരുന്ന ഏതെങ്കിലും ബിംബങ്ങൾ അവിടെ ഉണ്ടായിരുന്നോ?" ഇല്ല എന്ന് അവർ മറുപടി പറഞ്ഞു. നബി(സ) തുടർന്നു ചോദിച്ചു: "അവരുടെ ഏതെങ്കിലും ഉത്സവം അവിടെ നടന്നിരുന്നോ?" ഇല്ല എന്ന് അവർ മറുപടി പറഞ്ഞു. അന്നേരം അവിടുന്ന് പറഞ്ഞു: "നീ നിന്റെ നേർച്ച പൂർത്തിയാക്കൂ. അല്ലാഹുവിന് എതിരായ കാര്യത്തിലും മനുഷ്യന്റെ ഉടമസ്ഥതയിൽ ഇല്ലാത്ത വസ്തുവിലും ഉള്ള നേർച്ച പൂർത്തിയാക്കരുത്." (ദ)', 'ثَابِتِ بْنِ الضَّحَّاكِ', 'സാബിതുബ്നു ളഹ്ഹാക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 569, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ مَيْمُونَةَ بِنْتِ كَرْدَمٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْتُ مَعَ أَبِي فِي حِجَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَسَمِعْتُ النَّاسَ يَقُولُونَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلْتُ أُبِدُّهُ بَصَرِي، فَدَنَا إِلَيْهِ أَبِي وَهُوَ عَلَى نَاقَةٍ لَهُ، مَعَهُ دِرَّةٌ كَدِرَّةِ الْكُتَّابِ، فَسَمِعْتُ الْأَعْرَابَ وَالنَّاسَ يَقُولُونَ: الطَّبْطَبِيَّةَ الطَّبْطَبِيَّةَ، فَدَنَا إِلَيْهِ أَبِي، فَأَخَذَ بِقَدَمِهِ، قَالَتْ: فَأَقَرَّ لَهُ، وَوَقَفَ فَاسْتَمَعَ مِنْهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي نَذَرْتُ – إِنْ وُلِدَ لِي وَلَدٌ ذَكَرٌ – أَنْ أَنْحَرَ عَلَى رَأْسِ بُوَانَةَ فِي عَقَبَةٍ مِنَ الثَّنَايَا عِدَّةً مِنَ الْغَنَمِ؟ قَالَ: لَا أَعْلَمُ إِلَّا أَنَّهَا قَالَتْ خَمْسِينَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ بِهَا مِنَ الْأَوْثَانِ شَيْءٌ". قَالَ: لَا، قَالَ: "فَأَوْفِ بِمَا نَذَرْتَ بِهِ لِلَّهِ". قَالَتْ: فَجَمَعَهَا فَجَعَلَ يَذْبَحُهَا، فَانْفَلَتَتْ مِنْهَا شَاةٌ، فَطَلَبَهَا وَهُوَ يَقُولُ: اللَّهُمَّ أَوْفِ عَنِّي نَذْرِي، فَظَفِرَهَا، فَذَبَحَهَا. وَفِي رِوَايَةٍ قَالَ: "هَلْ بِهَا وَثَنٌ أَوْ عِيدٌ مِنْ أَعْيَادِ الْجَاهِلِيَّةِ". قَالَ: لَا. قُلْتُ: إِنَّ أُمِّي هَذِهِ عَلَيْهَا نَذْرٌ، وَمَشْيٌ، أَفَأَقْضِيهِ عَنْهَا؟ قَالَ: "نَعَمْ". (د,جه)', 'മൈമൂനത് ബിൻത് കർദം(റ): നബി(സ) നിർവ്വഹിച്ച ഹജ്ജിൽ എന്റെ പിതാവിനോടൊപ്പം ഞാനും സന്നിഹിതയായിരുന്നു. ഞാൻ നബി(സ)യെ കാണുകയും അല്ലാഹുവിന്റെ ദൂതർ എന്ന് ആളുകൾ പറയുന്നത് കേൾക്കുകയും ചെയ്തു. ഞാൻ തിരുമേനി(സ)യെ ഉറ്റുനോക്കിക്കൊണ്ടിരുന്നു. അപ്പോൾ എന്റെ പിതാവ് തിരുദൂതരെ സമീപിച്ചു. അവിടന്ന് തന്റെ ഒട്ടകപ്പുറത്തായിരുന്നു. തിരുമേനി(സ)യുടെ പക്കൽ പാഠശാലകളിൽ ഉപയോഗിക്കുന്ന തരത്തിലുള്ള ഒരു വടിയുണ്ടായിരുന്നു. ആളുകളും ഗ്രാമീണരും ''ത്വബ്ത്വബിയ'' ''ത്വബ്ത്വബിയ'' എന്ന് വിളിച്ചുപറയുന്നത് ഞാൻ കേട്ടു. നബി(സ)യെ സമീപിച്ച് എന്റെ പിതാവ് അവിടുത്തെ പാദങ്ങൾ പുണർന്നു. അപ്പോൾ നബിതിരുമേനി(സ) നിൽക്കുകയും എന്റെ പിതാവ് പറയുന്നത് ശ്രദ്ധാപൂർവ്വം കേൾക്കുകയും ചെയ്തു. പിതാവ് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എനിക്ക് ഒരാൺകുഞ്ഞ് ജനിക്കുകയാണെങ്കിൽ അഖബയിലെ ബുവാനയിൽ കുറേ ആടുകളെ ബലിയർപ്പിക്കാമെന്ന് ഞാനൊരു നേർച്ച നേർന്നിരുന്നു. അദ്ദേഹം (അബ്ദുല്ലാഹിബ്നു യസീദ് എന്നു പേരുള്ള ഈ ഹദീസ് ഉദ്ധരിണിയിലെ ഒരാൾ) പറഞ്ഞു: മൈമൂന(റ) അൻപത് ആടുകൾ എന്നാണോ പറഞ്ഞതെന്ന് വ്യക്തമായി ഞാൻ ഓർക്കുന്നില്ല. അപ്പോൾ നബി(സ) ചോദിച്ചു: "അവിടെ ഏതെങ്കിലും ബിംബങ്ങൾ ഉണ്ടായിരുന്നോ?" ഇല്ല, അദ്ദേഹം മറുപടി പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "എങ്കിൽ അല്ലാഹുവിനു വേണ്ടി താങ്കൾ നേർച്ച പൂർത്തിയാക്കുക." അപ്പോൾ പിതാവ് ആടുകളെ ശേഖരിച്ച് അറുത്തു. ആ കൂട്ടത്തിൽ നിന്ന് ഒരാട് ഓടിപ്പോയി. അതിനെ അന്വേഷിച്ച് നടക്കവെ എന്റെ പിതാവ് ഇങ്ങനെ പറയുന്നുണ്ടായിരുന്നു: അല്ലാഹുവേ, എന്റെ നേർച്ച നീ പൂർത്തീകരിച്ചുതരേണമേ. ഒടുവിൽ ഓടിപ്പോയ ആടിനെ കിട്ടി. അദ്ദേഹം അതിനെ അറുക്കുകയും ചെയ്തു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) ചോദിച്ചു: "അവിടെ ഏതെങ്കിലും പ്രതിമകൾ ഉണ്ടായിരുന്നോ? അല്ലെങ്കിൽ ജാഹിലിയ്യാ കാലത്തെ ഏതെങ്കിലും ഉത്സവങ്ങൾ അവിടെ ആഘോഷിക്കാറുണ്ടായിരുന്നോ?" ഇല്ല, എന്ന് അദ്ദേഹം മറുപടി പറഞ്ഞു. ഞാൻ ചോദിച്ചു: എന്റെ മാതാവ് ഒരു വഴിപാടും ഒരു നടത്തവും നേർന്നിരുന്നു. അവർക്ക് പകരം ഞാനത് ചെയ്തുവീട്ടണോ? നബി(സ) പറഞ്ഞു: "അതെ." (ദ,ജ)', 'مَيْمُونَةَ بِنْتِ كَرْدَمٍ', 'മൈമൂനത് ബിൻത് കർദം(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=3), 1, 'وَفِي رِوَايَةٍ قَالَ: "هَلْ بِهَا وَثَنٌ أَوْ عِيدٌ مِنْ أَعْيَادِ الْجَاهِلِيَّةِ". قَالَ: لَا. قُلْتُ: إِنَّ أُمِّي هَذِهِ عَلَيْهَا نَذْرٌ، وَمَشْيٌ، أَفَأَقْضِيهِ عَنْهَا؟ قَالَ: "نَعَمْ". (د,جه)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) ചോദിച്ചു: "അവിടെ ഏതെങ്കിലും പ്രതിമകൾ ഉണ്ടായിരുന്നോ? അല്ലെങ്കിൽ ജാഹിലിയ്യാ കാലത്തെ ഏതെങ്കിലും ഉത്സവങ്ങൾ അവിടെ ആഘോഷിക്കാറുണ്ടായിരുന്നോ?" ഇല്ല, എന്ന് അദ്ദേഹം മറുപടി പറഞ്ഞു. ഞാൻ ചോദിച്ചു: എന്റെ മാതാവ് ഒരു വഴിപാടും ഒരു നടത്തവും നേർന്നിരുന്നു. അവർക്ക് പകരം ഞാനത് ചെയ്തുവീട്ടണോ? നബി(സ) പറഞ്ഞു: "അതെ." (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ، يَذْكُرُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَيْرُكُمْ قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ". فَلَا أَدْرِي أَذَكَرَ مَرَّتَيْنِ بَعْدَهُ أَوْ ثَلَاثًا، ثُمَّ ذَكَرَ قَوْمًا: "يَخُونُونَ وَلَا يُؤْتَمَنُونَ، وَيَشْهَدُونَ وَلَا يُسْتَشْهَدُونَ، وَيُنْذِرُونَ وَلَا يُوفُونَ، وَيَظْهَرُ فِيهِمُ السِّمَنُ". (ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഏറ്റവും നല്ല കൂട്ടർ എന്റെ നൂറ്റാണ്ടിലുള്ളവരാണ്. പിന്നീട് അതിനു തൊട്ടുശേഷമുള്ളവർ. പിന്നീട് അതിനു ശേഷമുള്ളവർ. പിന്നീട് അതിനു ശേഷമുള്ളവർ." തിരുമേനി(സ) രണ്ടു തവണയാണോ മൂന്നു തവണയാണോ ഇപ്രകാരം പറഞ്ഞതെന്ന് ഞാൻ ഓർക്കുന്നില്ല. അനന്തരം ചിലയാളുകളെ പരാമർശിച്ച് നബി(സ) പറഞ്ഞു: "അവർ വഞ്ചിക്കുന്നവരാണ്, വിശ്വസ്തരല്ല. അവർ സാക്ഷ്യം പറയും, എന്നാൽ സാക്ഷ്യം വഹിക്കാൻ ഒട്ടും അർഹതയില്ലാത്തവരാണ്താനും. അവർ നേർച്ചനേരും, പക്ഷേ അതൊന്നും നിർവഹിക്കുന്നവരായിരിക്കില്ല. തടിച്ചുകൊഴുക്കുന്ന അവസ്ഥ അവരിൽ പ്രകടമാകും." (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 570, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي نَذَرْتُ أَنْ أَضْرِبَ عَلَى رَأْسِكَ بِالدُّفِّ، قَالَ: "أَوْفِي بِنَذْرِكِ". قَالَتْ: إِنِّي نَذَرْتُ أَنْ أَذْبَحَ بِمَكَانِ كَذَا وَكَذَا؟ مَكَانٌ كَانَ يَذْبَحُ فِيهِ أَهْلُ الْجَاهِلِيَّةِ، قَالَ: "لِصَنَمٍ". قَالَتْ: لَا، قَالَ: "لِوَثَنٍ". قَالَتْ: لَا، قَالَ: "أَوْفِي بِنَذْرِكِ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ)യെ സമീപിച്ച് ഒരു സ്ത്രീ പറഞ്ഞു: റസൂലേ, അങ്ങയുടെ സമീപം ദഫ് മുട്ടാമെന്ന് ഞാൻ നേർന്നിരുന്നു. നബി(സ) പറഞ്ഞു: "നീ നിന്റെ നേർച്ച പൂർത്തീകരിക്കുക." ആ സ്ത്രീ വീണ്ടും പറഞ്ഞു: ഇന്ന സ്ഥലത്തുവെച്ച് ബലിയറുക്കാമെന്നും ഞാൻ നേർന്നിട്ടുണ്ട്. ജാഹിലിയ്യാ കാലത്ത് അവിടെ അറുക്കാറുണ്ടായിരുന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "ബിംബങ്ങൾക്ക് വേണ്ടിയാണോ നീ അറുക്കുന്നത്? അല്ല, എന്ന് അവൾ മറുപടി പറഞ്ഞു. നബി(സ) വീണ്ടും ചോദിച്ചു: "ഏതെങ്കിലും മൂർത്തികൾക്കു വേണ്ടിയാണോ?" അവൾ പറഞ്ഞു: അല്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ നിന്റെ നേർച്ച പൂർത്തിയാക്കിക്കൊള്ളുക." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 571, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا حَلَفَ أَحَدُكُمْ عَلَى يَمِينٍ، فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا، فَلْيُكَفِّرْ عَنْ يَمِينِهِ وَلْيَنْظُرِ الَّذِي هُوَ خَيْرٌ فَلْيَأْتِهِ". وَفِي رِوَايَةٍ "إِذَا حَلَفْتَ عَلَي يَمِينٍ فَكَفِّرْ عَنْ يَمِينِكَ، ثُمَّ أْتِ الَّذِي هُوَ خَيْرٌ". وَفِي رِوَايَةٍ: "إِذَا حَلَفْتَ عَلَى يَمِينٍ، فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا، فَكَفِّرْ عَنْ يَمِينِكَ وَأْتِ الَّذِي هُوَ خَيْرٌ". (ن)', 'അബ്ദുർറഹ്മാനുബ്നു സമുറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു കാര്യം ചെയ്യുമെന്ന് സത്യം ചെയ്യുകയും തുടർന്ന് മറ്റൊന്നാണ് അതിനേക്കാൾ നല്ലതെന്ന് കാണുകയും ചെയ്താൽ, ആദ്യം സത്യം ചെയ്തതിന് പ്രായശ്ചിത്തം നൽകിക്കൊണ്ട് നല്ലതായിക്കണ്ട കാര്യം നിർവ്വഹിച്ചുകൊള്ളട്ടെ." മറ്റൊരു നിവേദനം: "ഒരു കാര്യം ചെയ്യണമെന്ന് നീ സത്യം ചെയ്താൽ, സത്യം ചെയ്തതിന് പ്രായശ്ചിത്തം നൽകി നല്ലതായ കാര്യം നീ നിർവ്വഹിക്കുക." മറ്റൊരു നിവേദനം: "നീ ഒരുകാര്യം ചെയ്യുമെന്ന് സത്യം ചെയ്യുകയും മറ്റൊന്നാണ് സത്യമെന്ന് കാണുകയും ചെയ്താൽ സത്യം ചെയ്തതിന് പ്രായശ്ചിത്തം നൽകി നല്ലത് നീ നിർവ്വഹിക്കുക." (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ', 'അബ്ദുർറഹ്മാനുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 571, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=6), 1, 'وَفِي رِوَايَةٍ "إِذَا حَلَفْتَ عَلَي يَمِينٍ فَكَفِّرْ عَنْ يَمِينِكَ، ثُمَّ أْتِ الَّذِي هُوَ خَيْرٌ".', 'മറ്റൊരു നിവേദനം: "ഒരു കാര്യം ചെയ്യണമെന്ന് നീ സത്യം ചെയ്താൽ, സത്യം ചെയ്തതിന് പ്രായശ്ചിത്തം നൽകി നല്ലതായ കാര്യം നീ നിർവ്വഹിക്കുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=6), 2, 'وَفِي رِوَايَةٍ: "إِذَا حَلَفْتَ عَلَى يَمِينٍ، فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا، فَكَفِّرْ عَنْ يَمِينِكَ وَأْتِ الَّذِي هُوَ خَيْرٌ". (ن)', 'മറ്റൊരു നിവേദനം: "നീ ഒരുകാര്യം ചെയ്യുമെന്ന് സത്യം ചെയ്യുകയും മറ്റൊന്നാണ് സത്യമെന്ന് കാണുകയും ചെയ്താൽ സത്യം ചെയ്തതിന് പ്രായശ്ചിത്തം നൽകി നല്ലത് നീ നിർവ്വഹിക്കുക." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنِّي – وَاللَّهِ إِنْ شَاءَ اللَّهُ – لَا أَحْلِفُ عَلَى يَمِينٍ، فَأَرَى غَيْرَهَا خَيْرًا مِنْهَا، إِلَّا كَفَّرْتُ عَنْ يَمِينِي وَأَتَيْتُ الَّذِي هُوَ خَيْرٌ". أَوْ قَالَ: "إِلَّا أَتَيْتُ الَّذِي هُوَ خَيْرٌ، وَكَفَّرْتُ يَمِينِي". (ق,د,ن,جه)', 'അബൂമൂസാ(റ): നബി(സ) അരുളി: "ഇൻഷാ അല്ലാഹ്, അല്ലാഹുവാണ് സത്യം, ഞാൻ ഒരു സത്യം ചെയ്യുകയും അതിനേക്കാൾ ഉത്തമമായ മറ്റൊന്ന് കാണുകയും ചെയ്താൽ ചെയ്ത സത്യലംഘനത്തിന് പ്രായശ്ചിത്തം നൽകുകയും ഉത്തമമായിക്കണ്ട കാര്യം ഞാൻ നിർവ്വഹിക്കുകയും ചെയ്യുന്നതാണ്." അല്ലെങ്കിൽ നബി(സ) ഇപ്രകാരമാണ് പറഞ്ഞിട്ടുള്ളത്: "ഞാൻ ഉത്തമമായത് ചെയ്തിട്ട് സത്യലംഘനത്തിന് പ്രായശ്ചിത്തം ചെയ്യും." (ബു,മു,ദ,ന,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 571, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا عَبْدَ الرَّحْمَنِ بْنَ سَمُرَةَ، إِذَا حَلَفْتَ عَلَى يَمِينٍ، فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا، فَأْتِ الَّذِي هُوَ خَيْرٌ وَكَفِّرْ يَمِينَكَ". وَفِي رِوَايَةٍ: قَالَ: "فَكَفِّرْ عَنْ يَمِينِكَ، ثُمَّ ائْتِ الَّذِي هُوَ خَيْرٌ". (ق,د,ت,ن)', 'അബ്ദുറഹ്മാനുബ്നു സമുറ(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "അബ്ദുറഹ്മാനുബ്നു സമുറ, നീ ഒരു കാര്യം ചെയ്യാൻ സത്യം ചെയ്തു. പക്ഷേ, അതിനേക്കാൾ ഉത്തമമായത് മറ്റൊന്നാണ് എന്ന് കാണുകയും ചെയ്തു. എങ്കിൽ നീ ഉത്തമമായ കാര്യം നിർവ്വഹിക്കുകയും സത്യലംഘനത്തിന് പ്രായശ്ചിത്തം ചെയ്യുകയും ചെയ്യുക." മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "നീ സത്യംചെയ്തതിന് പ്രായശ്ചിത്തം ചെയ്തിട്ട് ഉത്തമമായത് നിർവ്വഹിക്കുക." (ബു,മു,ദ,തു,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ', 'അബ്ദുറഹ്മാനുബ്നു സമുറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=8), 1, 'وَفِي رِوَايَةٍ: قَالَ: "فَكَفِّرْ عَنْ يَمِينِكَ، ثُمَّ ائْتِ الَّذِي هُوَ خَيْرٌ". (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "നീ സത്യംചെയ്തതിന് പ്രായശ്ചിത്തം ചെയ്തിട്ട് ഉത്തമമായത് നിർവ്വഹിക്കുക." (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَلَفَ عَلَى يَمِينٍ، فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا، فَلْيُكَفِّرْ عَنْ يَمِينِهِ وَلْيَفْعَلْ". (م,ت)', 'അബൂഹുറൈറ(റ): തിരുമേനി(സ) അരുളി: "ആരെങ്കിലും ഒരു സത്യം ചെയ്യുകയും അതിനേക്കാൾ മെച്ചപ്പെട്ടത് മറ്റൊന്നാണ് എന്ന് മനസ്സിലാവുകയും ചെയ്താൽ സത്യം ചെയ്തതിന് പ്രായശ്ചിത്തം നൽകുക. തുടർന്ന് ഉത്തമമായി കണ്ട കാര്യം നിർവ്വഹിക്കുക." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ عَلَى يَمِينٍ، فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا، فَلْيَأْتِ الَّذِي هُوَ خَيْرٌ وَلْيُكَفِّرْعَنْ يَمِينِهِ". وَفِي رِوَايَةٍ: "فَلْيَدَعْ يَمِينَهُ وَلْيَأْتِ الَّذِي هُوَ خَيْرٌ، وَلْيُكَفِّرْهَا". وَفِي رِوَايَةٍ: "وَلْيَتْرُكْ يَمِينَهُ". (ن)', 'അദിയ്യുബ്നു ഹാതിം(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു കാര്യം ചെയ്യാമെന്ന് സത്യം ചെയ്യുകയും പിന്നീട് അതിനേക്കാൾ ഗുണകരമായ മറ്റൊന്ന് കാണുകയും ചെയ്താൽ അയാൾ ഉത്തമമായിക്കണ്ട കാര്യം നിർവ്വഹിക്കുകയും സത്യലംഘനത്തിന് പ്രായശ്ചിത്തം നൽകുകയും ചെയ്തു കൊള്ളട്ടെ." മറ്റൊരു നിവേദനം: "തന്റെ സത്യം ഉപേക്ഷിച്ച് ആ നല്ലകാര്യം ചെയ്യുകയും (സത്യ ലംഘനത്തിന്റെ) പ്രായശ്ചിത്തം നൽകുകയും ചെയ്യട്ടെ." മറ്റൊരു നിവേദനം: "താൻ ചെയ്ത സത്യം അവൻ ഒഴിവാക്കിക്കൊള്ളട്ടെ." (ന)', 'عَدِيِّ بْنِ حَاتِمٍ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=10), 1, 'وَفِي رِوَايَةٍ: "فَلْيَدَعْ يَمِينَهُ وَلْيَأْتِ الَّذِي هُوَ خَيْرٌ، وَلْيُكَفِّرْهَا".', 'മറ്റൊരു നിവേദനം: "തന്റെ സത്യം ഉപേക്ഷിച്ച് ആ നല്ലകാര്യം ചെയ്യുകയും (സത്യ ലംഘനത്തിന്റെ) പ്രായശ്ചിത്തം നൽകുകയും ചെയ്യട്ടെ."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=10), 2, 'وَفِي رِوَايَةٍ: "وَلْيَتْرُكْ يَمِينَهُ". (ن)', 'മറ്റൊരു നിവേദനം: "താൻ ചെയ്ത സത്യം അവൻ ഒഴിവാക്കിക്കൊള്ളട്ടെ." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ مَالِكِ بْنِ نَضْلَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ ابْنَ عَمٍّ لِي، أَتَيْتُهُ أَسْأَلُهُ فَلَا يُعْطِينِي وَلَا يَصِلُنِي، ثُمَّ يَحْتَاجُ إِلَيَّ فَيَأْتِينِي فَيَسْأَلُنِي، وَقَدْ حَلَفْتُ أَنْ لَا أُعْطِيَهُ وَلَا أَصِلَهُ. فَأَمَرَنِي أَنْ آتِيَ الَّذِي هُوَ خَيْرٌ، وَأُكَفِّرَ عَنْ يَمِينِي. (ن)', 'മാലികുബ്നു നള്ല(റ): ഞാൻ പറഞ്ഞു: തിരുദൂതരേ, എന്റെ സഹോദരപുത്രനെക്കുറിച്ച് പറഞ്ഞുതരിക, സഹായം അഭ്യർത്ഥിച്ചുകൊണ്ട് ഞാൻ അവനെ സമീപിക്കാറുണ്ട്. പക്ഷേ, അദ്ദേഹം ഞാനുമായുള്ള കുടുംബബന്ധം നിലനിർത്തുകയോ എനിക്കെന്തെങ്കിലും സഹായം നൽകുകയോ ചെയ്യുകയുണ്ടായിട്ടില്ല. പിന്നീട് അദ്ദേഹത്തിന് എന്തെങ്കിലും ആവശ്യം നേരിടുമ്പോൾ എന്നെ സമീപിച്ച് സഹായാഭ്യർത്ഥന നടത്തും. അദ്ദേഹവുമായി കുടുംബബന്ധം ചേർക്കുകയോ അദ്ദേഹത്തിന് വല്ലതും നൽകുകയോ ചെയ്യില്ലെന്ന് ഞാൻ സത്യം ചെയ്തിട്ടുണ്ട്. ഇതു കേട്ടപ്പോൾ നബി(സ) നല്ല കാര്യം ചെയ്യുവാനും ഞാൻ ചെയ്ത സത്യത്തിന്റെ ലംഘനത്തിന് പ്രായശ്ചിത്തം നൽകുവാനും എന്നോടു കൽപിച്ചു. (ന)', 'مَالِكِ بْنِ نَضْلَةَ', 'മാലികുബ്നു നള്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 572, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا آلَيْتَ – وَفِي رِوَايَةٍ: حَلَفْتَ – عَلَى يَمِينٍ، فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا، فَأْتِ الَّذِي هُوَ خَيْرٌ – مِنْهَا – وَكَفِّرْ عَنْ يَمِينِكَ". (ن)', 'അബ്ദുർറഹ്മാനുബ്നു സമുറ(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "നീ ഒരു കാര്യം ചെയ്യാമെന്ന് സത്യം ചെയ്യുകയും മറ്റൊന്നാണ് അതിനേക്കാൾ ഉത്തമമെന്ന് കാണുകയും ചെയ്താൽ നല്ലതായി കണ്ട ആ കാര്യം നിർവ്വഹിക്കുക. സത്യലംഘനത്തിന് നീ പ്രായശ്ചിത്തം നൽകുകയും ചെയ്യുക." (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ', 'അബ്ദുർറഹ്മാനുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=12), 1, 'وَفِي رِوَايَةٍ: حَلَفْتَ – عَلَى يَمِينٍ، فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا، فَأْتِ الَّذِي هُوَ خَيْرٌ – مِنْهَا – وَكَفِّرْ عَنْ يَمِينِكَ". (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا نَذْرَ فِي مَعْصِيَةِ اللهِ، وَلَا فِيمَا لَا يَمْلِكُ ابْنُ آدَمَ". (ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): നബി(സ) അരുളി: "അല്ലാഹുവിന് എതിരായ കാര്യം ചെയ്യുന്നതിൽ നേർച്ചയില്ല. മനുഷ്യന്റെ ഉടമസ്ഥതയിൽ ഇല്ലാത്തതിലും നേർച്ചയില്ല." (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ يَقُودُ رَجُلًا فِي قَرَنٍ، فَتَنَاوَلَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَطَعَهُ، قَالَ: إِنَّهُ نَذْرٌ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു വ്യക്തിയെ മൂക്കുകയറിട്ട് വലിച്ച് കൊണ്ട്പോകുന്ന ഒരാളുടെ അടുത്ത്കൂടെ നബി(സ) നടന്നുപോയി. നബി(സ) അയാളെ സമീപിച്ച് അത് പൊട്ടിച്ചുകളഞ്ഞു. അത് നേർച്ചയായിരുന്നെന്ന് അയാൾ പറഞ്ഞു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِرَجُلٍ وَهُوَ يَطُوفُ بِالْكَعْبَةِ، يَقُودُهُ إِنْسَانٌ بِخِزَامَةٍ فِي أَنْفِهِ، فَقَطَعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ، ثُمَّ أَمَرَهُ أَنْ يَقُودَهُ بِيَدِهِ. وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِهِ وَهُوَ يَطُوفُ بِالْكَعْبَةِ، وَإِنْسَانٌ قَدْ رَبَطَ يَدَهُ بِإِنْسَانٍ آخَرَ بِسَيْرٍ أَوْ خَيْطٍ أَوْ بِشَيْءٍ غَيْرِ ذَلِكَ، فَقَطَعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ ثُمَّ قَالَ: "قُدْهُ بِيَدِكَ". (خ,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): കഅ്ബ ത്വവാഫ് ചെയ്യുന്ന ഒരാൾക്കരികിലൂടെ നബി(സ) നടക്കാനിടയായി. മറ്റൊരാൾ മൂക്കുവളയിട്ട് അയാളെ നയിക്കുകയായിരുന്നു. തിരുമേനി(സ) സ്വകരങ്ങൾ കൊണ്ട് അതു പൊട്ടിച്ചുകളഞ്ഞു. കൈപിടിച്ചു നടത്താൻ ആജ്ഞാപിക്കുകയും ചെയ്തു. മറ്റൊരു റിപ്പോർട്ടിൽ ഇങ്ങനെ: നബി(സ) കഅ്ബയെ ത്വവാഫ് ചെയ്യുമ്പോൾ അയാൾക്കരികിലൂടെ നടന്നു. അപ്പോൾ ഒരാൾ തന്റെ കൈ മറ്റൊരാളുടെ കൈയുമായി ഒരു കയറോ നൂലോ മറ്റെന്തോ ഉപയോഗിച്ച് കെട്ടിയിരിക്കുന്നു. ഉടനെ സ്വന്തം കൈ കൊണ്ട് നബി(സ) അത് ഛേദിക്കുകയും "അയാളെ താങ്കൾ കൈപിടിച്ച് നടത്തൂ" എന്ന് പറയുകയും ചെയ്തു. (ബു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=15), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِهِ وَهُوَ يَطُوفُ بِالْكَعْبَةِ، وَإِنْسَانٌ قَدْ رَبَطَ يَدَهُ بِإِنْسَانٍ آخَرَ بِسَيْرٍ أَوْ خَيْطٍ أَوْ بِشَيْءٍ غَيْرِ ذَلِكَ، فَقَطَعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ ثُمَّ قَالَ: "قُدْهُ بِيَدِكَ". (خ,د,ن)', 'മറ്റൊരു നിവേദനിൽ ഇങ്ങനെ: നബി(സ) കഅ്ബയെ ത്വവാഫ് ചെയ്യുമ്പോൾ അയാൾക്കരികിലൂടെ നടന്നു. അപ്പോൾ ഒരാൾ തന്റെ കൈ മറ്റൊരാളുടെ കൈയുമായി ഒരു കയറോ നൂലോ മറ്റെന്തോ ഉപയോഗിച്ച് കെട്ടിയിരിക്കുന്നു. ഉടനെ സ്വന്തം കൈ കൊണ്ട് നബി(സ) അത് ഛേദിക്കുകയും "അയാളെ താങ്കൾ കൈപിടിച്ച് നടത്തൂ" എന്ന് പറയുകയും ചെയ്തു. (ബു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا – وَفِي رِوَايَةٍ: مَرَّ بِشَيْخٍ – يُهَادَى بَيْنَ رَجُلَيْنِ، وَفِي رِوَايَةٍ: بَيْنَ ابْنَيْنِ. فَقَالَ: "مَا بَالُ هَذَا". قَالُوا: نَذَرَ أَنْ يَمْشِيَ إِلَى بَيْتِ اللَّهِ، قَالَ: "إِنَّ اللَّهَ غَنِيٌّ عَنْ تَعْذِيبِ هَذَا نَفْسَهُ، مُرْهُ فَلْيَرْكَبْ". فَأَمَرَهُ أَنْ يَرْكَبَ. وَفِي رِوَايَةٍ: أَتَي رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ يُهَادَى بَيْنَ ابْنَيْهِ، فَقَالَ: "مَا شَأْنُ هَذَا". فَقِيلَ: نَذَرَ أَنْ يَمْشِيَ إِلَى الكَعْبَةِ. فَقَالَ: "إِنَّ اللهَ لَا يَصْنَعُ بِتَعْذِيبِ هَذَا نَفْسَهُ شَيْئًا". فَأَمَرَهُ أَنْ يَرْكَبَ. (ق,د,ت,ن)', 'അനസ്(റ): രണ്ടു പുരുഷന്മാർക്കിടയിൽ - മറ്റൊരു നിവേദനം: രണ്ടാളുകൾക്കിടയിൽ - അവരെ പിടിച്ചുനടക്കുന്ന ഒരു മനുഷ്യനെ - മറ്റൊരു നിവേദന പ്രകാരം ഒരു വൃദ്ധനെ - നബി(സ) കാണാനിടവന്നു. അവിടുന്ന് ചോദിച്ചു: "എന്താണിത്?" അല്ലാഹുവിന്റെ ഭവനത്തിലേക്ക് നടന്നുപോകുമെന്ന് അയാൾക്കൊരു നേർച്ചയുണ്ട്. അവർ പ്രത്യുത്തരം നൽകി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാളിങ്ങനെ സ്വയം ശിക്ഷിക്കണമെന്ന് അല്ലാഹുവിന് യാതൊരു ആവശ്യവുമില്ല. അയാളോട് വാഹനത്തിൽ പോകാൻ പറയൂ." മറ്റൊരു നിവേദനത്തിൽ: തന്റെ രണ്ട് ആൺമക്കൾക്കിടയിൽക്കൂടി വിഷമിച്ചു നടക്കുന്ന ഒരാളുടെ അടുത്ത് നബി(സ) എത്തി. അവിടുന്ന് ചോദിച്ചു: "എന്താണിയാൾക്ക്?" കഅ്ബയിലേക്ക് നടക്കാമെന്ന് അയാൾ നേർന്നിട്ടുണ്ടെന്നറിയിക്കപ്പെട്ടു. തിരുമേനി(സ) അരുളി: "അയാളിങ്ങനെ സ്വയം ശിക്ഷിക്കണമെന്ന് അല്ലാഹുവിന് ഒരു നിർബന്ധവുമില്ല." വാഹനത്തിൽ പോകാൻ തിരുമേനി(സ) അയാളോട് കൽപിച്ചു. (ബു,മു,ദ,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 573, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=16), 1, 'وَفِي رِوَايَةٍ: مَرَّ بِشَيْخٍ – يُهَادَى بَيْنَ رَجُلَيْنِ،', 'മറ്റൊരു നിവേദനം: രണ്ടാളുകൾക്കിടയിൽ - അവരെ പിടിച്ചുനടക്കുന്ന ഒരു മനുഷ്യനെ -');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=16), 2, 'وَفِي رِوَايَةٍ: بَيْنَ ابْنَيْنِ. فَقَالَ: "مَا بَالُ هَذَا". قَالُوا: نَذَرَ أَنْ يَمْشِيَ إِلَى بَيْتِ اللَّهِ، قَالَ: "إِنَّ اللَّهَ غَنِيٌّ عَنْ تَعْذِيبِ هَذَا نَفْسَهُ، مُرْهُ فَلْيَرْكَبْ". فَأَمَرَهُ أَنْ يَرْكَبَ.', 'മറ്റൊരു നിവേദന പ്രകാരം ഒരു വൃദ്ധനെ - നബി(സ) കാണാനിടവന്നു. അവിടുന്ന് ചോദിച്ചു: "എന്താണിത്?" അല്ലാഹുവിന്റെ ഭവനത്തിലേക്ക് നടന്നുപോകുമെന്ന് അയാൾക്കൊരു നേർച്ചയുണ്ട്. അവർ പ്രത്യുത്തരം നൽകി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാളിങ്ങനെ സ്വയം ശിക്ഷിക്കണമെന്ന് അല്ലാഹുവിന് യാതൊരു ആവശ്യവുമില്ല. അയാളോട് വാഹനത്തിൽ പോകാൻ പറയൂ."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=16), 3, 'وَفِي رِوَايَةٍ: أَتَي رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ يُهَادَى بَيْنَ ابْنَيْهِ، فَقَالَ: "مَا شَأْنُ هَذَا". فَقِيلَ: نَذَرَ أَنْ يَمْشِيَ إِلَى الكَعْبَةِ. فَقَالَ: "إِنَّ اللهَ لَا يَصْنَعُ بِتَعْذِيبِ هَذَا نَفْسَهُ شَيْئًا". فَأَمَرَهُ أَنْ يَرْكَبَ. (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: തന്റെ രണ്ട് ആൺമക്കൾക്കിടയിൽക്കൂടി വിഷമിച്ചു നടക്കുന്ന ഒരാളുടെ അടുത്ത് നബി(സ) എത്തി. അവിടുന്ന് ചോദിച്ചു: "എന്താണിയാൾക്ക്?" കഅ്ബയിലേക്ക് നടക്കാമെന്ന് അയാൾ നേർന്നിട്ടുണ്ടെന്നറിയിക്കപ്പെട്ടു. തിരുമേനി(സ) അരുളി: "അയാളിങ്ങനെ സ്വയം ശിക്ഷിക്കണമെന്ന് അല്ലാഹുവിന് ഒരു നിർബന്ധവുമില്ല." വാഹനത്തിൽ പോകാൻ തിരുമേനി(സ) അയാളോട് കൽപിച്ചു. (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَذَرَتِ امْرَأَةٌ أَنْ تَمْشِيَ إِلَى بَيْتِ اللَّهِ، فَسُئِلَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ؟ فَقَالَ: "إِنَّ اللَّهَ لَغَنِيٌّ عَنْ مَشْيِهَا، مُرُوهَا فَلْتَرْكَبْ". (ت)', 'അനസ്(റ): കഅബയിലേക്ക് നടന്നു പൊയ്ക്കൊള്ളാമെന്ന് ഒരു സ്ത്രീ നേർച്ചയാക്കി. അതിനെപ്പറ്റി നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അവർ നടക്കണമെന്ന ആവശ്യം അല്ലാഹുവിന്നില്ല. വാഹനത്തിൽ പോകാൻ അവരോട് പറയുക." (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ ثَابِتِ بْنِ الضَّحَّاكِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ عَلَى العَبْدِ نَذْرٌ فِيمَا لَا يَمْلِكُ". (د,ت)', 'സാബിതുബ്നു ളഹ്ഹാക്ക്(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ ഉടമസ്ഥതയിലില്ലാത്തത് നേർച്ചയാക്കൽ ആർക്കും അനുവദനീയമല്ല." (ദ,തു)', 'ثَابِتِ بْنِ الضَّحَّاكِ', 'സാബിതുബ്നു ളഹ്ഹാക്ക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتِ الْعَضْبَاءُ لِرَجُلٍ مِنْ بَنِي عُقَيْلٍ، وَكَانَتْ مِنْ سَوَابِقِ الْحَاجِّ، قَالَ: فَأُسِرَ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي وَثَاقٍ، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى حِمَارٍ عَلَيْهِ قَطِيفَةٌ، فَقَالَ: يَا مُحَمَّدُ، عَلَامَ تَأْخُذُنِي وَتَأْخُذُ سَابِقَةَ الْحَاجِّ؟ قَالَ: "نَأْخُذُكَ بِجَرِيرَةِ حُلَفَائِكَ ثَقِيفَ". قَالَ: وَكَانَ ثَقِيفُ قَدْ أَسَرُوا رَجُلَيْنِ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: وَقَدْ قَالَ فِيمَا قَالَ: وَأَنَا مُسْلِمٌ، أَوْ قَالَ: وَقَدْ أَسْلَمْتُ، فَلَمَّا مَضَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَادَاهُ: يَا مُحَمَّدُ، يَا مُحَمَّدُ قَالَ: وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَحِيمًا رَفِيقًا، فَرَجَعَ إِلَيْهِ فَقَالَ: "مَا شَأْنُكَ". قَالَ: إِنِّي مُسْلِمٌ، قَالَ: "لَوْ قُلْتَهَا وَأَنْتَ تَمْلِكُ أَمْرَكَ أَفْلَحْتَ كُلَّ الْفَلَاحِ". قَالَ: يَا مُحَمَّدُ، إِنِّي جَائِعٌ فَأَطْعِمْنِي، إِنِّي ظَمْآنٌ فَاسْقِنِي. قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَذِهِ حَاجَتُكَ". أَوْ قَالَ: "هَذِهِ حَاجَتُهُ". فَفُودِيَ الرَّجُلُ بَعْدُ بِالرَّجُلَيْنِ، قَالَ: وَحَبَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعَضْبَاءَ لِرَحْلِهِ، قَالَ: فَأَغَارَ الْمُشْرِكُونَ عَلَى سَرْحِ الْمَدِينَةِ فَذَهَبُوا بِالْعَضْبَاءِ، قَالَ: فَلَمَّا ذَهَبُوا بِهَا وَأَسَرُوا امْرَأَةً مِنَ الْمُسْلِمِينَ، قَالَ: فَكَانُوا إِذَا كَانَ اللَّيْلُ يُرِيحُونَ إِبِلَهُمْ فِي أَفْنِيَتِهِمْ، قَالَ: فَنُوِّمُوا لَيْلَةً، وَقَامَتِ الْمَرْأَةُ فَجَعَلَتْ لَا تَضَعُ يَدَهَا عَلَى بَعِيرٍ إِلَّا رَغَا، حَتَّى أَتَتْ عَلَى الْعَضْبَاءِ، قَالَ: فَأَتَتْ عَلَى نَاقَةٍ ذَلُولٍ مُجَرَّسَةٍ، قَالَ: فَرَكِبَتْهَا، ثُمَّ جَعَلَتْ لِلَّهِ عَلَيْهَا: إِنْ نَجَّاهَا اللَّهُ لَتَنْحَرَنَّهَا. قَالَ: فَلَمَّا قَدِمَتِ الْمَدِينَةَ عُرِفَتِ النَّاقَةُ نَاقَةُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأُخْبِرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ، فَأَرْسَلَ إِلَيْهَا فَجِيءَ بِهَا، وَأُخْبِرَ بِنَذْرِهَا، فَقَالَ: "بِئْسَ مَا جَزَيْتِيهَا – أَوْ: جَزَتْهَا – إِنِ اللَّهُ أَنْجَاهَا عَلَيْهَا لَتَنْحَرَنَّهَا، لَا وَفَاءَ لِنَذْرٍ فِي مَعْصِيَةِ اللَّهِ، وَلَا فِيمَا لَا يَمْلِكُ ابْنُ آدَمَ". (م,د,ت,ن,جه)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): ബനൂഉഖൈലിൽപ്പെട്ട ഒരാളുടേതായിരുന്നു ''അള്ബാഅ്'' എന്ന ഒട്ടകം. ഹജ്ജ് കാലത്ത് ഉപയോഗിച്ചിരുന്ന വേഗതയേറിയ കൂട്ടത്തിൽപ്പെട്ട ഒന്നായിരുന്നു അത്. ഒരിക്കൽ അയാളെ ബന്ധനസ്ഥനാക്കി നബി(സ)യ്ക്ക് മുമ്പാകെ ഹാജരാക്കി. വെൽവെറ്റ് വിരിച്ചിരുന്ന ഒരു കഴുതപ്പുറത്തായിരുന്നു അപ്പോൾ നബി(സ). അയാൾ ചോദിച്ചു: ഓ മുഹമ്മദ്, താങ്കൾ എന്തിനാണ് എന്നേയും ഹജ്ജിന് വേഗത്തിൽ പോകുന്ന ഈ ഒട്ടകത്തെയും പിടിച്ചുവെച്ചിരിക്കുന്നത്? നബി(സ) പ്രതിവചിച്ചു: "നിന്റെ കൂട്ടരായ സഖീഫ് ഗോത്രക്കാർ ചെയ്ത ക്രൂരത കാരണത്താലാണ് ഞങ്ങൾ നിന്നെ തടഞ്ഞുവച്ചിരിക്കുന്നത്." നിവേദകൻ പറഞ്ഞു: നബി(സ)യുടെ സഹാബാക്കളിൽ രണ്ടുപേരെ സഖീഫ് ഗോത്രക്കാർ മുമ്പ് ബന്ധനസ്ഥരാക്കിയിരുന്നു. നിവേദകൻ തുടർന്നു: അപ്പോൾ അയാൾ താൻ മുസ്ലിം ആണെന്നോ ഇസ്ലാം മതം വിശ്വസിച്ചിരിക്കുന്നുവെന്നോ പറഞ്ഞു. നബി(സ) നടന്നകപ്പോൾ അയാൾ വിളിച്ചു: ഏ മുഹമ്മദ്, അല്ലയോ മുഹമ്മദ്. നബി(സ) ആർദ്രമനസ്കനും പരമ ദയാലുവുമായിരുന്നു. തിരുമേനി(സ) മടങ്ങിവന്ന് അയാളോടു ചോദിച്ചു: "നിനക്കെന്താണ് വേണ്ടത്?" അയാൾ പറഞ്ഞു: ഞാൻ മുസ്ലിമാണ്. നബി(സ) പറഞ്ഞു: "നിന്റെ കാര്യം നിന്റെ അധീനതയിൽ ആയിരുന്നപ്പോഴാണ് നീയതു പറഞ്ഞിരുന്നതെങ്കിൽ നീ പൂർണമായും വിജയിക്കുമായിരുന്നു. അപ്പോൾ ആ മനുഷ്യൻ പറഞ്ഞു: മുഹമ്മദ്, എനിക്കു വിശക്കുന്നു, ഭക്ഷണം തരിക. ഞാൻ ദാഹിച്ചുവലഞ്ഞിരിക്കുന്നു. കുടിക്കാൻ എന്തെങ്കിലും തരിക. നബി(സ) പറഞ്ഞു: "അപ്പോൾ ഇതാണ് നിന്റെ ആവശ്യം." അല്ലെങ്കിൽ: "ഇതാണ് അവന്റെ ആവശ്യം." തുടർന്ന് രണ്ടാൾ ജാമ്യത്തിൽ അവൻ വിട്ടയക്കപ്പെട്ടു. റിപ്പോർട്ടർ തുടരുന്നു: നബി(സ) അള്ബാഅ് എന്ന ഒട്ടകത്തെ തന്റെ യാത്രക്കായി തടഞ്ഞുവച്ചു. ആയിടയ്ക്ക് മുശ്രിക്കുകൾ മദീനയുടെ പ്രാന്തപ്രദേശങ്ങൾ കൊള്ളയടിച്ചിട്ട് അള്ബാഇനെ കവർച്ചചെയ്തു. പോകുന്ന പോക്കിൽ ഒരു മുസ്ലിം വനിതയെയും ബന്ധനസ്ഥയാക്കി കൊണ്ടുപോയി. രാത്രിനേരങ്ങളിൽ മുശ്രിക്കുകൾ തങ്ങളുടെ ഒട്ടകങ്ങളെ തങ്ങളുടെ സ്വന്തം പാർപ്പിടങ്ങൾക്കരികെ അഴിച്ചുവിടാറുണ്ടായിരുന്നു. അവരെല്ലാം ഗാഢമായ നിദ്രയിലാണ്ട ഒരു രാത്രിയിൽ ആ സ്ത്രീ പതിയെ എഴുന്നേറ്റ് ഒട്ടകങ്ങളെ സമീപിച്ചു. ഏതൊട്ടകത്തെ തൊട്ടാലും അത് ബഹളം വയ്ക്കുമായിരുന്നു. ഒടുവിൽ അവർ അള്ബാഇന്റെ അടുത്തെത്തി. നിവേദകൻ പറയുന്നു: അവർ പരിശീലനം സിദ്ധിച്ച മണിവെച്ചിട്ടുള്ള ഒരു ഒട്ടകത്തിന്റെ (അള്ബാഇന്റെ) അടുത്താണെത്തിയത്. അവർ ഒട്ടകപ്പുറത്ത് കയറി. അല്ലാഹു തന്നെ രക്ഷിച്ചാൽ ഈ ഒട്ടകത്തെ അറുക്കാം എന്നൊരു നേർച്ചയും അവർ നേർന്നു. അവർ മദീനയിലെത്തിയപ്പോഴാണ് ഒട്ടകം തിരുമേനി(സ)യുടേതാണെന്നറിയുന്നത്. ഈ വിവരമറിഞ്ഞ തിരുമേനി(സ) ആ സ്ത്രിയെ ആളയച്ചുവരുത്തി. തന്റെ നേർച്ചയെപ്പറ്റി അവർ റസൂൽ(സ)യോടു പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നീ നിശ്ചയിച്ച പ്രതിഫലം വളരെ മോശമായിപ്പോയി. അല്ലെങ്കിൽ: അവൾ നൽകിയ പ്രതിഫലം എത്ര മോശം! ആ ഒട്ടകപ്പുറത്ത് അല്ലാഹു അവരെ രക്ഷപ്പെടുത്തിയാൽ അതിനെ അറുക്കുമെന്നോ? അല്ലാഹുവിന് എതിരായ കാര്യത്തിലും മനുഷ്യന്റെ അധീനതയിലില്ലാത്തതിലുമുള്ള ഒരു നേർച്ചയും പാലിക്കേണ്ടതില്ല." (മു,ദ,തു,ന,ജ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 574, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا نَذْرَ فِي مَعْصِيَةِ اللهِ، وَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ". (د,ت)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് എതിരായ കാര്യങ്ങളിൽ നേർച്ചയില്ല. അതിന്റെ പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തമാണ്." (ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 575, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: نَذَرَتْ أُخْتِي أَنْ تَمْشِيَ إِلَى بَيْتِ اللَّهِ، فَأَمَرَتْنِي أَنْ أَسْتَفْتِيَ لَهَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَفْتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لِتَمْشِ وَلْتَرْكَبْ". (ق,د,ن)', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനിയ്യ്(റ): അല്ലാഹുവിന്റെ തിരുഗേഹത്തിലേക്ക് നടന്നു പൊയ്ക്കൊള്ളാമെന്ന് എന്റെ സഹോദരി നേർന്നിരുന്നു. നബി(സ)യോട് അതിനെ സംബന്ധിച്ചുള്ള വിധി ആരായാൻ എന്നെ അവർ ചുമതലപ്പെടുത്തി. ഞാൻ വിധി ചോദിച്ചപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അവർ നടന്നും വാഹനത്തിൽ കയറിയും പോയിക്കൊള്ളട്ടെ." (ബു,മു,ദ,ന)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിറുൽ ജുഹനിയ്യ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 575, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَيْنَمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ إِذَا هُوَ بِرَجُلٍ قَائِمٍ فِي الشَّمْسِ، فَسَأَلَ عَنْهُ؟ قَالُوا: هَذَا أَبُو إِسْرَائِيلَ، نَذَرَ أَنْ يَقُومَ وَلَا يَقْعُدَ، وَلَا يَسْتَظِلَّ، وَلَا يَتَكَلَّمَ، وَيَصُومَ. قَالَ: "مُرُوهُ فَلْيَتَكَلَّمْ وَلْيَسْتَظِلَّ وَلْيَقْعُدْ، وَلْيُتِمَّ صَوْمَهُ". (خ,د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പ്രസംഗിച്ചുകൊണ്ടിരിക്കുമ്പോൾ ഒരാൾ വെയിലത്തുതന്നെ നിൽക്കുന്നതു കണ്ടു. അതിനെപ്പറ്റി നബി(സ) അന്വേഷിച്ചപ്പോൾ ആളുകൾ പറഞ്ഞു: അബൂഇസ്റാഈൽ എന്ന ഈ മനുഷ്യൻ ഇരിക്കുകയില്ലെന്നും നിൽക്കുകയേ ചെയ്യൂവെന്നും തണൽ കൊള്ളുകയില്ലെന്നും ഒന്നും ഉരിയാടുകയില്ലെന്നും നോമ്പനുഷ്ഠിക്കുമെന്നും നേർച്ചയാക്കിയിട്ടുണ്ട്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "സംസാരിക്കാനും, തണലത്തു നിൽക്കാനും, ഇരിക്കാനും, നോമ്പ് പൂർത്തിയാക്കാനും നിങ്ങൾ അയാളോട് പറയുക." (ബു,ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يُهَادَى بَيْنَ ابْنَيْهِ، فَسَأَلَ عَنْهُ، فَقَالُوا: نَذَرَ أَنْ يَمْشِيَ، فَقَالَ: "إِنَّ اللَّهَ لَغَنِيٌّ عَنْ تَعْذِيبِ هَذَا نَفْسَهُ". وَأَمَرَهُ أَنْ يَرْكَبَ. (ق,ت,ن)', 'അനസുബ്നു മാലിക്(റ): ഒരു മനുഷ്യൻ തന്റെ രണ്ടു പുത്രന്മാരെ തനിക്കിരുവശത്തുമാക്കി അവരെ പിടിച്ച് നടക്കുന്നത് നബി(സ) കാണാനിടയായി. അവിടുന്ന് അയാളെക്കുറിച്ച് ആരാഞ്ഞു. അയാൾ നടന്നുകൊള്ളാമെന്ന് നേർച്ചയാക്കിയിരിക്കുകയാണെന്ന് ആളുകൾ ഉത്തരം നൽകി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാളിങ്ങനെ സ്വയം ശിക്ഷയനുഭവിക്കണമെന്ന് യാതൊരു നിർബന്ധവും അല്ലാഹുവിനില്ല." തുടർന്ന് ആ മനുഷ്യനോട് വാഹനത്തിൽ കയറിപ്പോകാൻ നബി(സ) ആജ്ഞാപിക്കുകയുണ്ടായി. (ബു,മു,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أُخْتَ عُقْبَةَ بْنِ عَامِرٍ نَذَرَتْ أَنْ تَحُجَّ مَاشِيَةً، وَأَنَّهَا لَا تُطِيقُ ذَلِكَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ لَغَنِيٌّ عَنْ مَشْيِ أُخْتِكَ، فَلْتَرْكَبْ، وَلْتُهْدِ بَدَنَةً". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നടന്നുപോയി ഹജ്ജ് ചെയ്തു കൊള്ളാമെന്ന് ഉഖ്ബതുബ്നു ആമിർ(റ)വിന്റെ സഹോദരി നേർച്ചയാക്കിയിരുന്നു. എന്നാൽ അവർക്ക് അതിന് കഴിയുകയുമില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിന്റെ സഹോദരി നടന്നുതന്നെ പോകണമെന്ന് അല്ലാഹുവിന് നിർബ്ബന്ധമില്ല. അവർ വാഹനത്തിൽ കയറിക്കൊള്ളട്ടെ. അവർ ഒരൊട്ടകത്തെ ദാനം നൽകുകയും ചെയ്യട്ടെ." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أُخْتٍ لَهُ نَذَرَتْ: أَنْ تَحُجَّ حَافِيَةً غَيْرَ مُخْتَمِرَةٍ؟ فَقَالَ: "مُرُوهَا فَلْتَخْتَمِرْ وَلْتَرْكَبْ، وَلْتَصُمْ ثَلَاثَةَ أَيَّامٍ". (د,ت,ن,جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): തലമറക്കാതെ നഗ്നപാദയായി ഹജ്ജ് ചെയ്യാമെന്ന് നേർച്ചയാക്കിയ തന്റെ സഹോദരിയെപ്പറ്റി അദ്ദേഹം നബി(സ) യോട് ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "അവർ തലമറച്ച് വാഹനത്തിൽ കയറിപ്പോയിക്കൊള്ളട്ടെ. മൂന്നുനാൾ നോമ്പുനുഷ്ഠിക്കുകയും ചെയ്യട്ടെ." (ദ,തു,ന,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ أُخْتِي نَذَرَتْ – يَعْنِي أَنْ تَحُجَّ مَاشِيَةً – فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ لَا يَصْنَعُ بِشَقَاءِ أُخْتِكَ شَيْئًا، فَلْتَحُجَّ رَاكِبَةً، وَلْتُكَفِّرْ عَنْ يَمِينِهَا". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ നബിതിരുമേനി(സ)യുടെ അടുത്തുവന്ന് ചോദിച്ചു: റസൂലേ, എന്റെ സഹോദരി കാൽനടയായിച്ചെന്ന് ഹജ്ജ്കർമം അനുഷ്ഠിച്ചുകൊള്ളാമെന്ന് നേർന്നിട്ടുണ്ട് അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിന്റെ സഹോദരിക്കു കഷ്ടപ്പാടുണ്ടാക്കുന്ന ഒന്നും തന്നെ അല്ലാഹു ചെയ്യുകയില്ല. വാഹനത്തിൽ കയറി അവർ ഹജ്ജ് ചെയ്തുകൊള്ളട്ടെ. സത്യലംഘനത്തിനുള്ള പ്രായശ്ചിത്തവും ചെയ്യട്ടെ." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 576, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أُخْتَ عُقْبَةَ بْنِ عَامِرٍ نَذَرَتْ أَنْ تَمْشِيَ إِلَى البَيْتِ، فَأَمَرَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَرْكَبَ وَتُهْدِيَ هَدْيًا. وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا بَلَغَهُ أَنَّ أُخْتَ عُقْبَةَ بْنِ عَامِرٍ نَذَرَتْ أَنْ تَحُجَّ مَاشِيَةً، قَالَ: "إِنَّ اللَّهَ لَغَنِيٌّ عَنْ نَذْرِهَا، مُرْهَا فَلْتَرْكَبْ". وَفِي رِوَايَةٍ: "مُرْ أُخْتَكَ فَلْتَرْكَبْ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉഖ്ബതുബ്നു ആമിർ(റ)വിന്റെ സഹോദരി കഅ്ബയിലേക്ക് നടന്നു ചെല്ലാമെന്ന് നേർന്നിരുന്നു. വാഹനം കയറിപ്പോകാനും പ്രായശ്ചിത്തമായി ഹദ്യ നൽകാനും നബി(സ) അവരോട് കൽപിച്ചു. മറ്റൊരു നിവേദനത്തിൽ: നടന്നു പോയി ഹജ്ജനുഷ്ഠിക്കാമെന്ന് ഉഖ്ബതുബ്നു ആമിർ(റ)വിന്റെ സഹോദരി നേർച്ചയാക്കിയ വിവരം അറിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "അവരുടെ ഈ നേർച്ച അല്ലാഹുവിന് ആവശ്യമില്ല. വാഹനത്തിലേറിപ്പോകാൻ അവരോട് പറയൂ." മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെയാണുള്ളത്: "താങ്കളുടെ സഹോദരിയോട് പറയൂ, വാഹനത്തിൽ കയറിപ്പോകാൻ." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=27), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا بَلَغَهُ أَنَّ أُخْتَ عُقْبَةَ بْنِ عَامِرٍ نَذَرَتْ أَنْ تَحُجَّ مَاشِيَةً، قَالَ: "إِنَّ اللَّهَ لَغَنِيٌّ عَنْ نَذْرِهَا، مُرْهَا فَلْتَرْكَبْ".', 'മറ്റൊരു നിവേദനത്തിൽ: നടന്നു പോയി ഹജ്ജനുഷ്ഠിക്കാമെന്ന് ഉഖ്ബതുബ്നു ആമിർ(റ)വിന്റെ സഹോദരി നേർച്ചയാക്കിയ വിവരം അറിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "അവരുടെ ഈ നേർച്ച അല്ലാഹുവിന് ആവശ്യമില്ല. വാഹനത്തിലേറിപ്പോകാൻ അവരോട് പറയൂ."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=27), 2, 'وَفِي رِوَايَةٍ: "مُرْ أُخْتَكَ فَلْتَرْكَبْ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെയാണുള്ളത്: "താങ്കളുടെ സഹോദരിയോട് പറയൂ, വാഹനത്തിൽ കയറിപ്പോകാൻ." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الجُهَنِيِّ رَضِيَ اللهُ عَنْهُ، أَنَّهُ قَالَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أُخْتِي نَذَرَتْ أَنْ تَمْشِيَ إِلَى البَيْتِ، فَقَالَ: "إِنَّ اللهَ لَا يَصْنَعُ بِمَشْيِ أُخْتِكَ إِلَى البَيْتِ شَيْئًا". (د)', 'ഉഖ്ബതുബ്നു ആമിൽ ജുഹനിയ്യ്(റ): അദ്ദേഹം നബി(സ)യോട് പറഞ്ഞു: എന്റെ സഹോദരി കാൽനടയായി കഅ്ബയിൽ ചെല്ലാമെന്ന് നേർന്നിട്ടുണ്ട്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിന്റെ സഹോദരി കഅ്ബയിലേക്ക് നടന്നുപോകുന്നതുകൊണ്ട് അല്ലാഹുവിന് യാതൊരു നേട്ടവും ഇല്ല." (ദ)', 'عُقْبَةَ بْنِ عَامِرٍ الجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിൽ ജുഹനിയ്യ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أُمَيَّةَ بْنِ خَالِدٍ قَالَ: لَمَّا وَلِّي خَالِدٌ القَسْرِي أَضْعَفَ الصَّاعَ، فَصَارَ الصَّاعُ سِتَّةَ عَشَرَ رِطْلًا. (د)', 'ഉമയ്യത്തുബ്നു ഖാലിദ്(റ): ഖാലിദുൽ ഖസ്രീ അധികാരമേറ്റപ്പോൾ സ്വാഇന്റെ അളവ് ഇരട്ടിയാക്കി. അങ്ങനെ ഒരു സ്വാഅ് പതിനാറു റാത്തലായി. (ദ)', 'أُمَيَّةَ بْنِ خَالِدٍ قَالَ', 'ഉമയ്യത്തുബ്നു ഖാലിദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا نَذْرَ فِي مَعْصِيَةٍ، وَكَفَّارَتُهُ – وَكَفَّارَتُهَا – كَفَّارَةُ يَمِينٍ". وَفِي رِوَايَةٍ: لَا نَذْرَ فِي غَضَبٍ، وَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ". (ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് എതിരായ കാര്യങ്ങളിൽ നേർച്ചയില്ല. അതിന്റെ (ലംഘിച്ചാലുള്ള) പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം തന്നെയാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "കോപം ഉണ്ടാക്കുന്ന കാര്യത്തിൽ നേർച്ച അരുത്. അതിന്റെ പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം തന്നെയാണ്." (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=30), 1, 'وَفِي رِوَايَةٍ: لَا نَذْرَ فِي غَضَبٍ، وَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ". (ن)', 'മറ്റൊരു നിവേദനിൽ: "കോപം ഉണ്ടാക്കുന്ന കാര്യത്തിൽ നേർച്ച അരുത്. അതിന്റെ പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം തന്നെയാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "النَّذْرُ نَذْرَانِ: فَمَا كَانَ مِنْ نَذْرٍ فِي طَاعَةِ اللَّهِ فَذَلِكَ لِلَّهِ، وَفِيهِ الْوَفَاءُ. وَمَا كَانَ مِنْ نَذْرٍ فِي مَعْصِيَةِ اللَّهِ فَذَلِكَ لِلشَّيْطَانِ، وَلَا وَفَاءَ فِيهِ، وَيُكَفِّرُهُ مَا يُكَفِّرُ الْيَمِينَ". (ن)', 'ഇംറാനുബ്നു ഹൂസൈൻ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നേർച്ച രണ്ടു വിധമാണ്: അല്ലാഹുവിന് വഴിപ്പെട്ടുകൊണ്ടുള്ള നേർച്ച, അത് അല്ലഹുവിനുള്ളത് തന്നെയാണ്. അത് പൂർത്തിയാക്കണം. അല്ലാഹുവിന് എതിരായുള്ള നേർച്ച, അത് പിശാചിനുള്ളതത്രേ. അത് പാലിക്കേണ്ടതില്ല. അതിന്റെ പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം തന്നെയാണ്." (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹൂസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا، سُئِلَ عَنْ رَجُلٍ نَذَرَ نَذْرًا: لَا يَشْهَدُ الصَّلَاةَ فِي مَسْجِدِ قَوْمِهِ؟ فَقَالَ عِمْرَانُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا نَذْرَ فِي غَضَبٍ – وَفِي رِوَايَةٍ: فِي مَعْصِيَةٍ وَلَا غَضَبٍ – وَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ". (ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): തന്റെ സമൂഹം നമസ്കരിക്കാറുള്ള പള്ളിയിൽ പോയി നമസ്കരിക്കാൻ കൂട്ടാക്കാത്ത ഒരാളുടെ നേർച്ചയെപ്പറ്റി ചോദിക്കപ്പെട്ടപ്പോൾ ഇംറാൻ(റ) പറഞ്ഞു: റസൂലുല്ലാഹി(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടു: "കോപമുള്ള കാര്യത്തിൽ നേർച്ചയില്ല." മറ്റൊരു റിപ്പോർട്ടിൽ ഇപ്രകാരമാണ്: "അല്ലാഹുവിന് എതിരായതിലോ കോപമുളവാക്കുന്നതിലോ നേർച്ചയില്ല. അതിന്റെ പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം തന്നെയാണ്." (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=32), 1, 'وَفِي رِوَايَةٍ: فِي مَعْصِيَةٍ وَلَا غَضَبٍ – وَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ". (ن)', 'മറ്റൊരു നിവേദനിൽ ഇപ്രകാരമാണ്: "അല്ലാഹുവിന് എതിരായതിലോ കോപമുളവാക്കുന്നതിലോ നേർച്ചയില്ല. അതിന്റെ പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം തന്നെയാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَفَّارَةُ النَّذْرِ – إِذَا لَمْ يُسَمَّ – كَفَّارَةُ يَمِينٍ". (م,د,ت,ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ഇന്നതെന്ന് വ്യക്തമാക്കാത്ത നേർച്ചയുടെ പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം തന്നെയാണ്." (മു,ദ,തു,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ قَالَ: وَهَبَتْ لَنَا أُمُّ حَبِيبٍ صَاعًا، حَدَّثَتْنَا عَنِ ابْنِ أَخِي صَفِيَّةَ عَنْ صَفِيَّةَ بِنْتِ حُيَيٍّ رَضِيَ اللهُ عَنْهَا: أَنَّهُ صَاعُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ أَنَسُ بْنُ عِيَاضٍ: فَجَرَّبْتُهُ – أَوْ قَالَ: فَحَزَرْتُهُ – فَوَجَدْتُهُ مُدَّيْنِ وَنِصْفًا بِمُدِّ هِشَامٍ. (د)', 'അബ്ദുറഹ്മാനുബ്നു ഹർമലത്(റ): ഒരിക്കൽ ഉമ്മുഹബീബ്(റ) ഞങ്ങൾക്ക് ഒരു സ്വാഅ് നൽകി. സ്വഫിയാ ബിൻത് ഹുയയ്യ്(റ)വിൽ നിന്ന് അവരുടെ സഹോദരപുത്രൻ ഇപ്രകാരം നിവേദനം ചെയ്തിട്ടുണ്ടെന്ന് ഉമ്മുഹബീബ്(റ) പറഞ്ഞു: ഇത് നബി തിരുമേനി(സ)യുടെ സ്വാഅ് ആണ്. അനസുബ്നു ഇയാദ്(റ) പറഞ്ഞു: ഞാനത് പരിശോധിച്ചു നോക്കി (അളന്നു നോക്കി). ഹിശാമിന്റെ മുദ്ദനുസരിച്ചുള്ള രണ്ടര മുദ്ദാണ് അതെന്നു മനസ്സിലായി. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ قَالَ', 'അബ്ദുറഹ്മാനുബ്നു ഹർമലത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ مُحَمَّدِ بْنِ مُحَمَّدِ بْنِ خَلَّادٍ قَالَ: كَانَ عِنْدَنَا مَكُّوكٌ يُقَالُ لَهُ: مَكُّوكُ خَالِدٍ، وَكَانَ كَيْلَجَتَيْنِ بِكَيْلَجَةِ هَارُونَ، قَالَ مُحَمَّدٌ: صَاعُ خَالِدٍ صَاعُ هِشَامٍ، يَعْنِي ابْنَ عَبْدِ المَلِكِ. (د)', 'മുഹമ്മദുബ്നു മുഹമ്മദുബ്നു ഖല്ലാദ്(റ): മകൂകുഖാലിദ് (ഖാലിദിന്റെ അളവുപാത്രം) എന്ന് വിളിക്കപ്പെട്ടിരുന്ന ഒരു അളവുപാത്രം ഞങ്ങളുടെ കൈവശമുണ്ടായിരുന്നു. അത് കൈലജത് ഹാറൂൺ (അളവ്) കൊണ്ടുള്ള രണ്ട് കൈലജത് അളവായിരുന്നു. സ്വാഉ ഖാലിദ് (ഖാലിദിന്റെ സ്വാഅ്) എന്നാൽ സ്വാഉഹിശാം (ഹിശാമിന്റെ സ്വാഅ്) തന്നെ. അതായത് ഹിശാമുബ്നു അബ്ദുൽ മലിക്കിന്റേത്. (ദ)', 'مُحَمَّدِ بْنِ مُحَمَّدِ بْنِ خَلَّادٍ قَالَ', 'മുഹമ്മദുബ്നു മുഹമ്മദുബ്നു ഖല്ലാദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ نَذَرَ أَنْ يُطِيعَ اللَّهَ فَلْيُطِعْهُ، وَمَنْ نَذَرَ أَنْ يَعْصِيَ اللَّهَ فَلَا يَعْصِهِ". (خ,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിനെ അനുസരിക്കാമെന്ന് നേർച്ചയാക്കിയാൽ അല്ലാഹുവിനെ അനുസരിച്ചുകൊള്ളട്ടെ. അല്ലാഹുവിന് എതിരുചെയ്യാനാണ് നേർന്നതെങ്കിൽ എതിരു ചെയ്യരുത്." (ബു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 578, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ سَعْدَ بْنَ عُبَادَةَ اسْتَفْتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ أُمِّي مَاتَتْ وَعَلَيْهَا نَذْرٌ لَمْ تَقْضِهِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْضِهِ عَنْهَا". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): സഅ്ദുബ്നു ഉബാദത്(റ) നബി(സ)യോട് പറഞ്ഞു: എന്റെ ഉമ്മ മരണമടഞ്ഞുപോയി. അവർക്ക് നിറവേറ്റാനാകാതെ പോയ ഒരു നേർച്ചയുണ്ട്. അപ്പോൾ തിരുമേനി(സ) പ്രതിവചിച്ചു: "അവർക്കു വേണ്ടി താങ്കൾ അത് വീട്ടുക." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً رَكِبَتِ الْبَحْرَ، فَنَذَرَتْ إِنْ نَجَّاهَا اللَّهُ أَنْ تَصُومَ شَهْرًا. فَنَجَّاهَا اللَّهُ، فَلَمْ تَصُمْ حَتَّى مَاتَتْ، فَجَاءَتِ ابْنَتُهَا أَوْ أُخْتُهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَهَا أَنْ تَصُومَ عَنْهَا. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരിക്കൽ ഒരു സ്ത്രീ കടൽയാത്ര ചെയ്തു. അല്ലാഹു തന്നെ രക്ഷപ്പെടുത്തിയാൽ ഒരു മാസം നോമ്പനുഷ്ഠിക്കാമെന്ന് അവൾ നേർച്ചയാക്കി. അല്ലാഹു അവളെ രക്ഷപ്പെടുത്തി. മരിക്കും വരെ അവൾ നോമ്പനുഷ്ഠിച്ചില്ല. അങ്ങനെ അവളുടെ മകളോ സഹോദരിയോ നബി(സ)യുടെ സന്നിധിയിലെത്തി. അവൾക്ക് വേണ്ടി നോമ്പനുഷ്ഠിക്കാൻ വന്നവളോട് നബി(സ) കൽപിച്ചു. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً أَتَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: كُنْتُ تَصَدَّقْتُ عَلَى أُمِّي بِوَلِيدَةٍ، وَإِنَّهَا مَاتَتْ وَتَرَكَتْ تِلْكَ الْوَلِيدَةَ؟ قَالَ: "قَدْ وَجَبَ أَجْرُكِ، وَرَجَعَتْ إِلَيْكِ فِي الْمِيرَاثِ". قَالَتْ: وَإِنَّهَا مَاتَتْ وَعَلَيْهَا صَوْمُ شَهْرٍ. فَذَكَرَ نَحْوَ الحَدِيثِ. (م,د,ت,جه)', 'ബുറൈദ(റ): നബി(സ)യുടെ അരികെ വന്ന് ഒരു സ്ത്രീ പറഞ്ഞു: ഞാനെന്റെ മാതാവിന് ഒരു അടിമസ്ത്രീയെ ദാനമായി നൽകിയിരുന്നു. മാതാവ് മരണപ്പെട്ടു പോവുകയും ആ അടിമസ്ത്രീയെ അവശേഷിപ്പിക്കുകയും ചെയ്തിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "നിശ്ചയമായും നിനക്ക് പ്രതിഫലം കിട്ടും. ആ അടിമസ്ത്രീ അനന്തരാവകാശമായി നിന്നിലേക്ക് മടങ്ങുകയും ചെയ്യും." ആ സ്ത്രീ പറഞ്ഞു: ഒരു മാസത്തെ നോമ്പനുഷ്ഠിക്കാൻ ഉണ്ടായിരിക്കെയാണ് അവർ മരണപ്പെട്ടത്. തുടർന്ന് മുകളിൽ ഉദ്ധരിക്കപ്പെട്ടതുപോലുള്ള ഹദീസ് അദ്ദേഹം നിവേദനം ചെയ്തു. (മു,ദ,തു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً جَاءَتْ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنَّهُ كَانَ عَلَى أُمِّهَا صَوْمُ شَهْرٍ، أَفَأَقْضِيهِ عَنْهَا؟ فَقَالَ: "لَوْ كَانَ عَلَى أُمِّكِ دَيْنٌ، أَكُنْتِ قَاضِيَتَهُ". قَالَتْ: نَعَمْ، قَالَ: "فَدَيْنُ اللَّهِ أَحَقُّ أَنْ يُقْضَى". (ق,د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു സ്ത്രീ നബി(സ)യുടെ സന്നിധിയിൽ വന്നിട്ട് പറഞ്ഞു: എന്റെ ഉമ്മാക്ക് ഒരു മാസത്തെ നോമ്പനുഷ്ഠിക്കാനുണ്ട്. ഞാനത് വീട്ടണോ? നബി(സ) പ്രതിവചിച്ചു: "നിന്റെ ഉമ്മാക്ക് കടം വീട്ടാനുണ്ടെങ്കിൽ നീയത് വീട്ടുമോ? അവൾ ഉത്തരം നൽകി: അതെ. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അങ്ങനെയെങ്കിൽ വീട്ടുവാൻ ഏറ്റവും ബാദ്ധ്യസ്ഥമായത് അല്ലാഹുവിനുള്ള കടമാകുന്നു." (ബു,മു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ مَاتَ وَعَلَيْهِ صِيَامٌ صَامَ عَنْهُ وَلِيُّهُ". (ق,د,ن)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "നോമ്പനുഷ്ഠിച്ചു വീട്ടാനുള്ള ഒരാൾ മരണമടഞ്ഞാൽ അയാളുടെ അവകാശി അവന് പകരം അത് അനുഷ്ഠിച്ചു വീട്ടേണ്ടതാണ്." (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 579, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ قَالَ: اسْتَفْتَى سَعْدُ بْنُ عُبَادَةَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَذْرٍ كَانَ عَلَى أُمِّهِ، تُوُفِّيَتْ قَبْلَ أَنْ تَقْضِيَهُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَاقْضِهِ عَنْهَا". (م)', 'ഇബ്നുഅബ്ബാസ്(റ): തന്റെ മാതാവ് വീട്ടാനുണ്ടായിരുന്ന ഒരു നേർച്ചയെപ്പറ്റി സഅ്ദുബ്നു ഉബാദ(റ) റസൂലുല്ലാഹി(സ)യോട് ചോദിച്ചു. അദ്ദേഹത്തിന്റെ മാതാവ് നേർച്ചവീട്ടും മുമ്പ് മരണമടഞ്ഞിരുന്നു. തിരുമേനി(സ) ഉത്തരം നൽകി: "അവർക്ക് പകരം താങ്കൾ അത് വീട്ടുക." (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ اسْتَفْتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَذْرٍ كَانَ عَلَى أُمِّهِ، فَتُوُفِّيَتْ قَبْلَ أَنْ تَقْضِيَهُ، فَأَفْتَاهُ أَنْ يَقْضِيَهُ عَنْهَا. (خ)', 'സഅ്ദുബ്നു ഉബാദ(റ): നേർച്ച വീട്ടുംമുമ്പ് മരിച്ചുപോയ തന്റെ മാതാവിന്റെ നേർച്ചയെപ്പറ്റി തിരുമേനി(സ)യോട് ചോദിച്ചപ്പോൾ അവർക്ക് വേണ്ടി അത് വീട്ടാൻ തിരുമേനി(സ) കൽപിച്ചു. (ബു)', 'سَعْدِ بْنِ عُبَادَةَ', 'സഅ്ദുബ്നു ഉബാദ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ وَغَيْرِهِ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيُّمَا امْرِئٍ مُسْلِمٍ أَعْتَقَ امْرَأً مُسْلِمًا كَانَ فَكَاكَهُ مِنَ النَّارِ، يُجْزِي كُلُّ عُضْوٍ مِنْهُ عُضْوًا مِنْهُ. وَأَيُّمَا امْرِئٍ مُسْلِمٍ أَعْتَقَ امْرَأَتَيْنِ مُسْلِمَتَيْنِ كَانَتَا فَكَاكَهُ مِنَ النَّارِ. يُجْزِي كُلُّ عُضْوٍ مِنْهُمَا عُضْوًا مِنْهُ. وَأَيُّمَا امْرَأَةٍ مُسْلِمَةٍ أَعْتَقَتِ امْرَأَةً مُسْلِمَةً كَانَتْ فَكَاكَهَا مِنَ النَّارِ، يُجْزِي كُلُّ عُضْوٍ مِنْهَا عُضْوًا مِنْهَا". (ت)', 'അബൂഉമാമ(റ)വിൽ നിന്നും തിരുമേനി(സ)യുടെ സഹാബാക്കളിൽ മറ്റു ചിലരിൽ നിന്നുമുള്ള നിവേദനം: നബി(സ) പറഞ്ഞു: "മുസ്ലിമായ ഒരടിമയെ മോചിപ്പിക്കുന്ന ഏതു മുസ്ലിമിനും ആ മോചിപ്പിക്കപ്പെട്ടവൻ നരകമോചനത്തിന് കാരണമായി മാറുന്നതാണ്. അയാളുടെ ഓരോ അംഗവും മറ്റേ വ്യക്തിയുടെ ഓരോ അംഗത്തിനും പ്രതിഫലമായി നൽകപ്പെടുന്നു. മുസ്ലിംകളായ രണ്ടു സ്ത്രീകളെ മോചിപ്പിക്കുന്ന ഏതു മുസ്ലിമിനും ആ മോചിപ്പിക്കപ്പെട്ടവൻ നരകമോചനത്തിന് കാരണമായി മാറുന്നതാണ്. അവരുടെ ഓരോ അംഗത്തിനും പകരമായി അയാളുടെ ഓരോ അംഗവും പ്രതിഫലം നൽകപ്പെടുന്നു. ഏതൊരു മുസ്ലിം സ്ത്രീയാണോ മറ്റൊരു മുസ്ലിം സ്ത്രീക്ക് മോചനം നൽകുന്നത് അവൾ ആ മോചനം നൽകിയവൾക്ക് നരകമോചന ഹേതുവാകുന്നതാണ്. അവളുടെ അംഗത്തിന് പകരമായി ഇവളുടെ ഓരോ അംഗത്തിനും പ്രതിഫലം നൽകപ്പെടുന്നു." (തു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَعْتَقَ رَقَبَةً مُؤْمِنَةً أَعْتَقَ اللَّهُ مِنْهُ بِكُلِّ عُضْوٍ مِنْهُ عُضْوًا مِنَ النَّارِ، حَتَّى يَعْتِقَ فَرْجَهُ بِفَرْجِهِ". (ق,ت)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "വിശ്വാസിനിയായ ഒരടിമസ്ത്രീയെ ആരെങ്കിലും മോചിപ്പിച്ചാൽ, അല്ലാഹു അവന്റെ ഒരോ അവയവത്തെയും ആ അടിമയുടെ ഒരോ അവയവത്തിനും പകരമായി നരകത്തിൽ നിന്ന് മോചിപ്പിക്കുന്നതാണ്. അവന്റെ ഗുഹ്യഭാഗത്തെപ്പോലും മറ്റേയാളുടെ ഗുഹ്യഭാഗത്തിന് പകരമായി." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ النَّذْرَ لَا يُقَرِّبُ مِنِ ابْنِ آدَمَ شَيْئًا لَمْ يَكُنِ اللَّهُ قَدَّرَهُ لَهُ، وَلَكِنِ النَّذْرُ يُوَافِقُ الْقَدَرَ، فَيُخْرَجُ بِذَلِكَ مِنَ الْبَخِيلِ مَا لَمْ يَكُنِ الْبَخِيلُ يُرِيدُ أَنْ يُخْرِجَ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു നിശ്ചയിച്ചിട്ടില്ലാത്ത ഒന്നിനെയും നേർച്ച മനുഷ്യപുത്രനോട് അടുപ്പിക്കുന്നില്ല. പക്ഷേ, നേർച്ച വിധിയോട് യോജിക്കുന്നു. തന്നിമിത്തം താൻ ചെലവാക്കാൻ ഉദ്ദേശിക്കാത്തത് പിശുക്കനിൽ നിന്ന് ചെലവാക്കപ്പെടുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ النَّذْرِ، وَيَقُولُ: "لَا يَرُدُّ شَيْئًا، وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنَ الْبَخِيلِ". وَفِي رِوَايَةٍ: "النَّذْرُ لَا يَرُدُّ شَيْئًا". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) നേർച്ചനേരുന്നതിനെ നിരോധിക്കാൻ ആരംഭിച്ചു. അവിടുന്ന് പറഞ്ഞു: "അത് ഒന്നും തന്നെ തട്ടിയകറ്റുകയില്ല. മറിച്ച് ലുബ്ധന്റെ ധനം ചെലവഴിക്കുകയേ ചെയ്യുന്നുള്ളൂ." മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെയാണുള്ളത്: "നേർച്ച ഒന്നും തട്ടിമാറ്റുന്നില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=47), 1, 'وَفِي رِوَايَةٍ: "النَّذْرُ لَا يَرُدُّ شَيْئًا". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെയാണുള്ളത്: "നേർച്ച ഒന്നും തട്ടിമാറ്റുന്നില്ല." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَأْتِي ابْنَ آدَمَ النَّذْرُ الْقَدَرَ بِشَيْءٍ لَمْ أَكُنْ قَدَّرْتُهُ لَهُ، وَلَكِنْ يُلْقِيهِ النَّذْرُ الْقَدَرَ قَدَّرْتُهُ، يُسْتَخْرَجُ مِنَ الْبَخِيلِ، يُؤْتِي عَلَيْهِ مَا لَمْ يَكُنْ يُؤْتِي مِنْ قَبْلُ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ഞാൻ (അല്ലാഹു) നിശ്ചയിച്ചിട്ടില്ലാത്ത ഒന്നും തന്നെ നേർച്ച മനുഷ്യന് നൽകുകയില്ല. നേരെ മറിച്ച് ഞാൻ നിശ്ചയിച്ചിട്ടുള്ള വിധിയെ മാത്രമേ അതവന് നൽകുന്നുള്ളൂ. ലുബ്ധനിൽനിന്ന് അത് ചെലവാക്കുന്നു. മുമ്പ് അയാൾ നൽകാതിരുന്നത് ഇപ്പോൾ അയാൾ ചെലവാക്കുന്നു." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ النَّذْرِ وَقَالَ: "إِنَّهُ لَا يَأْتِي بِخَيْرٍ، وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنَ البَخِيلِ". وَفِي رِوَايَةٍ: "إِنَّهُ لَا يَرُدُّ شَيْئًا، إِنَّمَا يُسْتَخْرَجُ بِهِ مِنَ الشَّحِيحِ". (م,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂലുല്ലാഹി(സ) നേർച്ച നിരോധിച്ചു. എന്നിട്ട് പറഞ്ഞു: "അത് യാതൊരു നന്മയും കൊണ്ടുവരുന്നില്ല. മറിച്ച് ലുബ്ധനിൽ നിന്ന് ചെലവഴിപ്പിക്കുന്നു." മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെ: "അത് ഒന്നിനെയും തട്ടിനീക്കുന്നില്ല. നേരെമറിച്ച് അതുമൂലം ലുബ്ധനിൽനിന്ന് ചെലവാക്കപ്പെടുന്നു." (മു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=49), 1, 'وَفِي رِوَايَةٍ: "إِنَّهُ لَا يَرُدُّ شَيْئًا، إِنَّمَا يُسْتَخْرَجُ بِهِ مِنَ الشَّحِيحِ". (م,ن)', 'മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെ: "അത് ഒന്നിനെയും തട്ടിനീക്കുന്നില്ല. നേരെമറിച്ച് അതുമൂലം ലുബ്ധനിൽനിന്ന് ചെലവാക്കപ്പെടുന്നു." (മു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "النَّذْرُ لَا يُقَدِّمُ شَيْئًا وَلَا يُؤَخِّرُهُ، إِنَّمَا هُوَ شَيْءٌ يُسْتَخْرَجُ بِهِ مِنَ الشَّحِيحِ". (ن)', 'ഇബ്നുഉമർ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "നേർച്ച ഒന്നിനെയും മുന്തിപ്പിക്കുകയോ പിന്തിപ്പിക്കുകയോ ചെയ്യുന്നില്ല. മറിച്ച് അത് ലുബ്ധനിൽ നിന്ന് ചെലവഴിപ്പിക്കുന്ന കാര്യമാണ്." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَأْتِي النَّذْرُ عَلَى ابْنِ آدَمَ شَيْئًا لَمْ أُقَدِّرْهُ عَلَيْهِ، وَلَكِنَّهُ شَيْءٌ أُسْتُخْرِجَ بِهِ مِنَ الْبَخِيلِ". (ن)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ തിരുദൂതർ(സ) പറഞ്ഞു: "ഞാൻ (അല്ലാഹു) നിശ്ചിക്കാത്ത ഒന്നിനെയും നേർച്ച ആദമിന്റെ മകന് നൽകുന്നില്ല. പക്ഷേ അത് ലുബ്ധന്റെ ധനത്തിൽ നിന്ന് ചെലവഴിപ്പിക്കുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَنْذِرُوا فَإِنَّ النَّذْرَ لَا يُغْنِي مِنَ الْقَدَرِ شَيْئًا، وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنَ الْبَخِيلِ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നേർച്ചയാക്കരുത്. കാരണം നേർച്ച വിധിയെ മാറ്റിമറിക്കുന്നില്ല. അത് ലുബ്ധന്റെ ധനം ചെലവാക്കുന്നതേയുള്ളൂ." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 581, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ أَبُو لُبَابَةَ، أَوْ مَنْ شَاءَ اللَّهُ: إِنَّ مِنْ تَوْبَتِي أَنْ أَهْجُرَ دَارَ قَوْمِي الَّتِي أَصَبْتُ فِيهَا الذَّنْبَ، وَأَنْ أَنْخَلِعَ مِنْ مَالِي كُلِّهِ صَدَقَةً. قَالَ: "يُجْزِئُ عَنْكَ الثُّلُثُ". (د)', 'കഅ്ബുബ്നു മാലിക്(റ) അല്ലെങ്കിൽ അബുലുബാബ(റ) അതുമല്ലെങ്കിൽ അല്ലാഹു ഉദ്ദേശിച്ച മറ്റൊരാൾ നബി(സ)യോട് ഇങ്ങനെ പറയുകയുണ്ടായി: കുറ്റം ചെയ്ത എന്റെ കൂട്ടുകാരുടെ ദേശത്തെ ഉപേക്ഷിക്കുമെന്നും എന്റെ സ്വത്തുമുഴുക്കെ ദാനമായി നൽകുമെന്നുമാണ് പശ്ചാത്താപ വേളയിലുള്ള എന്റെ നേർച്ച. അപ്പോൾ നബി(സ) പറഞ്ഞു: "താങ്കളുടെ ധനത്തിലെ മൂന്നിലൊന്ന് മാത്രം നൽകിയാൽ മതിയാകുന്നതാണ്." (ദ)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: يُحَدِّثُ حَدِيثَهُ حِينَ تَخَلَّفَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ، قَالَ: فَلَمَّا جَلَسْتُ بَيْنَ يَدَيْهِ قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ اللهَ عَزَّوَجَلَّ إِنَّمَا نَجَّانِي بِالصِّدْقِ، وَإِنَّ مِنْ تَوْبَتِي أَنْ أَنْخَلِعَ مِنْ مَالِي صَدَقَةً إِلَى اللَّهِ وَإِلَى رَسُولِهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمْسِكْ عَلَيْكَ بَعْضَ مَالِكَ فَهُوَ خَيْرٌ لَكَ". قُلْتُ: فَإِنِّي أُمْسِكُ سَهْمِيَ الَّذِي بِخَيْبَرَ. (ق,د,ن)', 'തബൂക്ക് യുദ്ധത്തിൽ പങ്കെടുക്കാതെ താൻ മാറി നിന്ന സംഭവത്തെപ്പറ്റി കഅ്ബുബ്നു മാലിക്(റ) ഇങ്ങനെ പറയുന്നു: തിരുദൂതർ(സ)യുടെ മുന്നിൽ ഇരിക്കവേ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, സത്യസന്ധതമൂലമാണ് അല്ലാഹു എന്നെ രക്ഷിച്ചത്. അല്ലാഹുവിനും റസൂലിനുമായി എന്റെ സമ്പാദ്യം നീക്കിവയ്ക്കുക എന്നതാണ് എന്റെ പശ്ചാത്താപം. അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ധനത്തിൽ നിന്ന് അൽപം നീ മാറ്റിവെക്കുക. നിനക്ക് അത് നല്ലതാണ്." അപ്പോൾ ഞാൻ പറഞ്ഞു: എന്നാൽ ഖൈബറിൽ നിന്ന് ലഭിച്ച ഓഹിരി ഞാൻ മാറ്റിവക്കാം. (ബു,മു,ദ,ന)', 'كَعْبِ بْنِ مَالِكٍ', 'തബൂക്ക് യുദ്ധത്തിൽ പങ്കെടുക്കാതെ താൻ മാറി നിന്ന സംഭവത്തെപ്പറ്റി കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ ابْنِ كَعْبِ بْنِ مَالِكٍ قَالَ: كَانَ أَبُو لُبَابَةَ، فَذَكَرَ مَعْنَاهُ، وَالقِصَّةُ لِأَبِي لُبَابَةَ. (د)', 'ഇബ്നു കഅ്ബുബ്നു മാലിക്(റ): അദ്ദേഹം ഈ സംഭവം (മേലുദ്ധരിച്ച ഹദീസ്) അബൂലുബാബ(റ)വുമായി ബന്ധപ്പെടുത്തിയാണ് പറഞ്ഞിട്ടുള്ളത്. (ദ)', 'ابْنِ كَعْبِ بْنِ مَالِكٍ قَالَ', 'ഇബ്നു കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ كَعْبٍ رَضِيَ اللهُ عَنْهُ – فِي قِصَّتِهِ – قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ مِنْ تَوْبَتِي إِلَى اللَّهِ أَنْ أَخْرُجَ مِنْ مَالِي كُلِّهِ إِلَى اللَّهِ وَإِلَى رَسُولِهِ صَدَقَةً؟ قَالَ: "لَا". قُلْتُ: فَنِصْفُهُ؟ قَالَ: "لَا". قُلْتُ: فَثُلُثُهُ؟ قَالَ: "نَعَمْ". قُلْتُ: فَإِنِّي سَأُمْسِكُ سَهْمِي مِنْ خَيْبَرَ. (د)', 'കഅ്ബ്നു മാലിക്(റ): ഞാൻ നബി(സ)യോട് ഇങ്ങനെ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അല്ലാഹുവിനോടുള്ള എന്റെ പശ്ചാത്താപം, അല്ലാഹുവിന്റെയും റസൂലിന്റെയും മാർഗ്ഗത്തിൽ എന്റെ സമ്പാദ്യമൊക്കെയും ദാനമായി നൽകുമെന്നതാണ്. നബി(സ) പറഞ്ഞു: "വേണ്ട." ഞാൻ ചോദിച്ചു: അതിന്റെ പകുതി? നബി(സ) പറഞ്ഞു: "വേണ്ട." ഞാൻ ചോദിച്ചു: അതിന്റെ മൂന്നിലൊന്ന്? നബി(സ) പറഞ്ഞു: "ശരി." ഞാൻ പറഞ്ഞു: ഖൈബറിൽ നിന്ന് കിട്ടിയ ഓഹരി ഞാൻ എനിക്കുവേണ്ടി നീക്കിവെക്കുന്നു. (ദ)', 'كَعْبٍ', 'കഅ്ബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلًا قَامَ يَوْمَ الْفَتْحِ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي نَذَرْتُ لِلَّهِ: إِنْ فَتَحَ اللَّهُ عَلَيْكَ مَكَّةَ أَنْ أُصَلِّيَ فِي بَيْتِ الْمَقْدِسِ رَكْعَتَيْنِ؟ قَالَ: "صَلِّ هَاهُنَا". ثُمَّ أَعَادَ عَلَيْهِ، فَقَالَ: "صَلِّ هَاهُنَا". ثُمَّ أَعَادَ عَلَيْهِ، فَقَالَ: "شَأْنُكَ إِذَنْ". وَفِي رِوَايَةٍ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي بَعَثَ مُحَمَّدًا بِالْحَقِّ، لَوْ صَلَّيْتَ هَاهُنَا لَأَجْزَأَ عَنْكَ صَلَاةً فِي بَيْتِ الْمَقْدِسِ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഒരാൾ നബി(സ)യോട് പറഞ്ഞു: തിരുദൂതരേ, അല്ലാഹു താങ്കൾക്ക് മക്കാവിജയം സാദ്ധ്യമാക്കിയാൽ ബൈത്തുൽ മുഖദ്ദസിൽ പോയി ഞാൻ രണ്ടു റക്അത്ത് നമസ്ക്കരിക്കാമെന്ന് നേർച്ച നേർന്നിട്ടുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇവിടെ നമസ്ക്കരിച്ചുകൊള്ളൂ." വീണ്ടും അയാൾ ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇവിടെ നമസ്ക്കരിക്കൂ." അയാൾ ചോദ്യം ആവർത്തിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്നാൽ നിന്റെ ഇഷ്ടം പോലെ ചെയ്യുക." മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെ: നബി(സ) പറഞ്ഞു: "സത്യവുമായി മുഹമ്മദിനെ നിയോഗിച്ചവൻ തന്നെ സത്യം, നീ ഇവിടെ നമസ്ക്കരിച്ചാൽ ബൈത്തുൽ മുഖദ്ദസിൽച്ചെന്ന് നമസ്ക്കരിക്കുന്നതിന് പകരം ആകുന്നതാണ്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=57), 1, 'وَفِي رِوَايَةٍ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي بَعَثَ مُحَمَّدًا بِالْحَقِّ، لَوْ صَلَّيْتَ هَاهُنَا لَأَجْزَأَ عَنْكَ صَلَاةً فِي بَيْتِ الْمَقْدِسِ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെ: നബി(സ) പറഞ്ഞു: "സത്യവുമായി മുഹമ്മദിനെ നിയോഗിച്ചവൻ തന്നെ സത്യം, നീ ഇവിടെ നമസ്ക്കരിച്ചാൽ ബൈത്തുൽ മുഖദ്ദസിൽച്ചെന്ന് നമസ്ക്കരിക്കുന്നതിന് പകരം ആകുന്നതാണ്." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ نَذَرَ نَذْرًا لَمْ يُسَمِّهِ فَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ، وَمَنْ نَذَرَ نَذْرًا فِي مَعْصِيَةٍ فَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ، وَمَنْ نَذَرَ نَذْرًا لَا يُطِيقُهُ فَكَفَّارَتُهُ كَفَّارَةُ يَمِينٍ، وَمَنْ نَذَرَ نَذْرًا أَطَاقَهُ فَلْيَفِ بِهِ". (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): തിരൂദൂതർ(സ) പറഞ്ഞു: "ഒരാൾ ഇന്നത് എന്ന് വ്യക്തമാക്കാത്ത നേർച്ച നേർന്നാൽ അതിന്റെ പ്രായശ്ചിത്തമായി സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം ചെയ്യണം. അല്ലാഹുവിന് എതിരായ കാര്യം ചെയ്യാൻ നേർന്നാൽ അതിന്റെ പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം തന്നെയാണ്. തനിക്ക് ചെയ്യാൻ സാധിക്കാത്ത നേർച്ച ഒരാൾ നേർന്നാൽ അതിന്റെ പ്രായശ്ചിത്തം സത്യലംഘനത്തിന്റെ പ്രായശ്ചിത്തം തന്നെ. തനിക്ക് സാധിക്കുന്ന നേർച്ച ഒരാൾ നേർന്നാൽ അത് അവൻ പൂർത്തിയാക്കേണ്ടതാണ്." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنِ ابْنِ عُمَرَ، عَنْ عُمَرَ – رَضِيَ اللهُ عَنْهُمَا – أَنَّهُ قَالَ: يَا رَسُولَ اللَّهِ، إِنِّي نَذَرْتُ فِي الْجَاهِلِيَّةِ أَنْ أَعْتَكِفَ فِي الْمَسْجِدِ الْحَرَامِ لَيْلَةً؟ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَوْفِ بِنَذْرِكَ". (ق,د,ت,ن)', 'ഇബ്നുഉമർ(റ): ഉമർ(റ) ചോദിച്ചു: തിരുദൂതരേ, മസ്ജിദുൽ ഹറാമിൽ ഒരു രാത്രി ഭജനമിരിക്കാമെന്ന് ജാഹിലിയ്യാ കാലത്ത് ഞാനെരു നേർച്ചചെയ്തിരുന്നു. അപ്പോൾ നബി(സ) മറുപടിയേകി: "താങ്കൾ താങ്കളുടെ നേർച്ച പൂർത്തിയാക്കിക്കൊള്ളുക." (ബു,മു,ദ,തു,ന)', 'ابْنِ عُمَرَ، عَنْ عُمَرَ –', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ عَلَى عُمَرَ نَذْرٌ فِي اعْتِكَافِ لَيْلَةٍ فِي الْمَسْجِدِ الْحَرَامِ، فَسَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ فَأَمَرَهُ أَنْ يَعْتَكِفَ. وَفِي رِوَايَةٍ: أَنَّ عُمَرَ كَانَ جَعَلَ عَلَيْهِ يَوْمًا يَعْتَكِفُهُ فِي الْجَاهِلِيَّةِ، فَسَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَأَمَرَهُ أَنْ يَعْتَكِفَهُ. (ن)', 'ഇബ്നുഉമർ(റ): മസ്ജിദുൽ ഹറാമിൽ ഒരു രാത്രി ഭജനമിരിക്കാമെന്ന് ഉമർ(റ)വിന് നേർച്ചയുണ്ടായിരുന്നു. അതിനെക്കുറിച്ച് റസൂൽ(സ)യോട് ചോദിച്ചപ്പോൾ ഭജനമിരിക്കാൻ അവിടുന്ന് കൽപിച്ചു. മറ്റൊരു നിവേദനം: ജാഹിലിയ്യാ കാലത്ത്, ഒരു ദിവസം ഭജനമിരിക്കാമെന്ന് ഉമർ(റ) നിശ്ചയിച്ചിരുന്നു. തദ്സംബന്ധമായി അല്ലാഹുവിന്റെ റസൂൽ(സ)യോട് ആരാഞ്ഞപ്പോൾ ഭജനമിക്കാൻ തിരുദൂതർ(സ) കൽപിക്കുകയുണ്ടായി. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 584, 584, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=60), 1, 'وَفِي رِوَايَةٍ: أَنَّ عُمَرَ كَانَ جَعَلَ عَلَيْهِ يَوْمًا يَعْتَكِفُهُ فِي الْجَاهِلِيَّةِ، فَسَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَأَمَرَهُ أَنْ يَعْتَكِفَهُ. (ن)', 'മറ്റൊരു നിവേദനം: ജാഹിലിയ്യാ കാലത്ത്, ഒരു ദിവസം ഭജനമിരിക്കാമെന്ന് ഉമർ(റ) നിശ്ചയിച്ചിരുന്നു. തദ്സംബന്ധമായി അല്ലാഹുവിന്റെ റസൂൽ(സ)യോട് ആരാഞ്ഞപ്പോൾ ഭജനമിക്കാൻ തിരുദൂതർ(സ) കൽപിക്കുകയുണ്ടായി. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: سَمِعَ رَجُلًا يَقُولُ: لَا وَالكَعْبَةِ. فَقَالَ ابْنُ عُمَرَ: لَا يُحْلَفُ بِغَيْرِ اللهِ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ حَلَفَ بِغَيْرِ اللهِ فَقَدْ كَفَرَ. أَوْ: أَشْرَكَ". حسن. (د,ت)', 'ഇബ്നുഉമർ(റ): ഇല്ല, കഅ്ബയെക്കൊണ്ട് തന്നെ സത്യം എന്ന് ഒരാൾ ആണയിടുന്നത് അദ്ദേഹം കേൾക്കാൻ ഇടയായി. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹു അല്ലാത്ത ഒന്നിനെക്കൊണ്ടും സത്യം ചെയ്യാവതല്ല. അല്ലാഹുവിന്റെ റസൂൽ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേൾക്കുകയുണ്ടായിട്ടുണ്ട്: "അല്ലാഹു അല്ലാത്തതിനെക്കൊണ്ട് ആരെങ്കിലും സത്യം ചെയ്താൽ അവൻ ദൈവനിഷേധിയായിപ്പോകുന്നതാണ്. അല്ലെങ്കിൽ ബഹുദൈവാരാധകനായിത്തീരും." (ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 584, 584, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَحْلِفُوا بِالطَّوَاغِي وَلَا بِآبَائِكُمْ". (م,ن)', 'അബുദുറഹ്മാനുബ്നു സമുറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "നിങ്ങളുടെ പിതാക്കളെക്കൊണ്ടും പരദൈവങ്ങളെക്കൊണ്ടും നിങ്ങൾ സത്യം ചെയ്യരുത്." (മു,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ', 'അബുദുറഹ്മാനുബ്നു സമുറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 584, 584, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَحْلِفُوا بِآبَائِكُمْ وَلَا بِأُمَّهَاتِكُمْ وَلَا بِالْأَنْدَادِ، وَلَا تَحْلِفُوا إِلَّا بِاللَّهِ، وَلَا تَحْلِفُوا بِاللَّهِ إِلَّا وَأَنْتُمْ صَادِقُونَ". (د,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ പിതാക്കളെക്കൊണ്ടോ മാതാക്കളെക്കൊണ്ടോ പരദൈവങ്ങളെക്കൊണ്ടോ നിങ്ങൾ സത്യം ചെയ്യരുത്. അല്ലഹുവിനെക്കൊണ്ടല്ലാതെ നിങ്ങൾ സത്യം ചെയ്യാൻ പാടില്ല. സത്യസന്ധരായല്ലാതെ നിങ്ങൾ അല്ലാഹുവിനെക്കൊണ്ട് സത്യം ചെയ്യുകയും അരുത്." (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 584, 584, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عُمَرَ، عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَدْرَكَهُ وَهُوَ فِي رَكْبٍ وَهُوَ يَحْلِفُ بِأَبِيهِ، فَقَالَ: "إِنَّ اللَّهَ يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ، فَمَنْ كَانَ حَالِفًا فَلْيَحْلِفْ بِاللَّهِ أَوْ لِيَسْكُتْ". وَفِي رِوَايَةٍ قَالَ: سَمِعَنِي... قَالَ عُمَرُ: فَوَاللَّهِ مَا حَلَفْتُ بِهَذَا ذَاكِرًا وَلَا آثِرًا. (ق,د,ت,ن,جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)വിൽനിന്ന് ഇബ്നുഉമർ(റ): ഒരു യാത്രാ സംഘത്തിലായിരിക്കെ ഉമർ(റ) തന്റെ പിതാവിനെക്കൊണ്ട് സത്യം ചെയ്യുന്നത് നബി(സ) അറിഞ്ഞു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "തങ്ങളുടെ പിതാക്കളെക്കൊണ്ട് സത്യം ചെയ്യുന്നത് അല്ലാഹു നിങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നു. ആരെങ്കിലും സത്യം ചെയ്യുന്നുവെങ്കിൽ അല്ലാഹുവിനെക്കൊണ്ട് സത്യം ചെയ്യട്ടെ. അല്ലെങ്കിൽ അവൻ മൗനം പാലിക്കട്ടെ." മറ്റൊരു നിവേദനം: (ഞാൻ അപ്രകാരം സത്യം ചെയ്യുന്നത്) റസൂൽ(സ) കേട്ടു. ഉമർ(റ) പറഞ്ഞു: അതിനു ശേഷം അറിഞ്ഞോ സ്വഭീഷ്ടപ്രകാരമോ ഞാനപ്രകാരം സത്യം ചെയ്തിട്ടില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ، عَنْ عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 584, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=64), 1, 'وَفِي رِوَايَةٍ قَالَ: سَمِعَنِي... قَالَ عُمَرُ: فَوَاللَّهِ مَا حَلَفْتُ بِهَذَا ذَاكِرًا وَلَا آثِرًا. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: (ഞാൻ അപ്രകാരം സത്യം ചെയ്യുന്നത്) റസൂൽ(സ) കേട്ടു. ഉമർ(റ) പറഞ്ഞു: അതിനു ശേഷം അറിഞ്ഞോ സ്വഭീഷ്ടപ്രകാരമോ ഞാനപ്രകാരം സത്യം ചെയ്തിട്ടില്ല. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ، يَعْنِي فِي حَدِيثِ قِصَّةِ الْأَعْرَابِيِّ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفْلَحَ وَأَبِيهِ إِنْ صَدَقَ، دَخَلَ الْجَنَّةَ وَأَبِيهِ إِنْ صَدَقَ". (د)', 'ത്വൽഹതുബ്നു ഉബൈദില്ലാ(റ): അഅ്റാബിയുടെ കഥ വിവരിക്കുന്ന ഹദീസിൽ നബി(സ) പറഞ്ഞു: "അവന്റെ പിതാവാണ് സത്യം, അയാൾ പറഞ്ഞത് സത്യമാണെങ്കിൽ അയാൾ വിജയിച്ചു. അയാളുടെ പിതാവാണ് സത്യം, അയാൾ പറഞ്ഞത് സത്യമാണെങ്കിൽ അയാൾ സ്വർഗ്ഗം പൂകിയിരിക്കുന്നു." (ദ)', 'طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ', 'ത്വൽഹതുബ്നു ഉബൈദില്ലാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 585, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَ حَالِفًا فَلَا يَحْلِفْ إِلَّا بِاللَّهِ". وَكَانَتْ قُرَيْشٌ تَحْلِفُ بِآبَائِهَا، فَقَالَ: "لَا تَحْلِفُوا بِآبَائِكُمْ". وَفِي رِوَايَةٍ: "إِنَّ اللَّهَ يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ". (م,ن)', 'ഇബ്നുഉമർ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "ആരെങ്കിലും സത്യം ചെയ്യുന്നുവെങ്കിൽ അയാൾ അല്ലാഹുവിനെക്കൊണ്ടല്ലാതെ സത്യം ചെയ്യരുത്." ഖുറൈഷികൾ തങ്ങളുടെ പിതാക്കളെക്കൊണ്ട് സത്യം ചെയ്തിരുന്നു. നബി(സ) അരുളി: "നിങ്ങളുടെ പിതാക്കളെക്കൊണ്ട് നിങ്ങൾ സത്യം ചെയ്യരുത്." മറ്റൊരു നിവേദനം: "നിങ്ങളുടെ പിതാക്കളെക്കൊണ്ട് സത്യം ചെയ്യുന്നതിൽ നിന്ന് നിങ്ങളെ അല്ലാഹു വിലക്കുന്നു." (മു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 585, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=66), 1, 'وَفِي رِوَايَةٍ: "إِنَّ اللَّهَ يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ". (م,ن)', 'മറ്റൊരു നിവേദനം: "നിങ്ങളുടെ പിതാക്കളെക്കൊണ്ട് സത്യം ചെയ്യുന്നതിൽ നിന്ന് നിങ്ങളെ അല്ലാഹു വിലക്കുന്നു." (മു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ مِنْكُمْ فَقَالَ فِي حَلْفِهِ: بِاللَّاتِ فَلْيَقُلْ: لَا إِلَهَ إِلَّا اللَّهُ، وَمَنْ قَالَ لِصَاحِبِهِ: تَعَالَ أُقَامِرْكَ، فَلْيَتَصَدَّقْ". وَفِي رِوَايَةٍ: "مَنْ حَلَفَ بِاللَّاتِ وَالْعُزَّى". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരെങ്കിലും സത്യം ചെയ്യുന്ന വേളയിൽ ലാത്തയെക്കൊണ്ട് സത്യം എന്നു പറഞ്ഞാൽ അവൻ ലാഇലാഹ ഇല്ലല്ലാഹു എന്ന് പറഞ്ഞു കൊള്ളട്ടെ. ആരെങ്കിലും തന്റെ കൂട്ടുകാരനോട് വരൂ നമുക്ക് ചൂതാടാം എന്നു പറഞ്ഞാൽ പ്രായശ്ചിത്തമായി അവൻ ധർമ്മം ചെയ്യേണ്ടതാണ്." മറ്റൊരു നിവേദനത്തിൽ: "ലാത്തയെക്കൊണ്ടും ഉസ്സയെക്കൊണ്ടും സത്യം ചെയ്താൽ" എന്നാണ്. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 585, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=67), 1, 'وَفِي رِوَايَةٍ: "مَنْ حَلَفَ بِاللَّاتِ وَالْعُزَّى". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "ലാത്തയെക്കൊണ്ടും ഉസ്സയെക്കൊണ്ടും സത്യം ചെയ്താൽ" എന്നാണ്. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَذْكُرُ بَعْضَ الْأَمْرِ وَأَنَا حَدِيثُ عَهْدٍ بِالْجَاهِلِيَّةِ، فَحَلَفْتُ بِاللَّاتِ وَالْعُزَّى، فَقَالَ لِي أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بِئْسَ مَا قُلْتَ، ائْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبِرْهُ، فَإِنَّا لَا نَرَاكَ إِلَّا قَدْ كَفَرْتَ. فَأَتَيْتُهُ فَأَخْبَرْتُهُ، فَقَالَ لِي: "قُلْ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، ثَلَاثَ مَرَّاتٍ. وَتَعَوَّذْ بِاللَّهِ مِنَ الشَّيْطَانِ، ثَلَاثَ مَرَّاتٍ. وَاتْفُلْ عَنْ يَسَارِكَ، ثَلَاثَ مَرَّاتٍ، وَلَا تَعُدْ لَهُ". وَفِي رِوَايَةٍ قَالَ: حَلَفْتُ بِاللَّاتِ وَالْعُزَّى، فَقَالَ لِي أَصْحَابِي: بِئْسَ مَا قُلْتَ، قُلْتَ هُجْرًا. فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: "قُلْ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. وَانْفُثْ عَنْ يَسَارِكَ ثَلَاثًا، وَتَعَوَّذْ بِاللَّهِ مِنَ الشَّيْطَانِ، ثُمَّ لَا تَعُدْ". (ن)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): ഞങ്ങളൊരിക്കൽ വർത്തമാനം പറഞ്ഞുകൊണ്ടിരിക്കുകയായിരുന്നു. ഞാൻ എന്റെ ജാഹിലിയ്യാ കാലഘട്ടം ഉപേക്ഷിച്ചിട്ട് അധികനാൾ കഴിഞ്ഞിരുന്നില്ല. സംസാരമദ്ധ്യേ ലാത്തയെക്കൊണ്ടും ഉസ്സയെക്കൊണ്ടും ഞാൻ സത്യം ചെയ്തു. ഇതുകേട്ട് റസൂൽ(സ)യുടെ അനുചരർ പറഞ്ഞു: നീ പറഞ്ഞത് അങ്ങേയറ്റം മോശമായി, നീ പോയി റസൂൽ(സ)യെ വിവരം അറിയിക്കുക. ഞങ്ങളെ സംബന്ധിച്ചിടത്തോളം നീ അവിശ്വാസിയായിത്തീർന്നിരിക്കുന്നു. അങ്ങനെ ഞാൻ തിരുമേനി(സ)യെ സമീപിച്ച് വിവരം പറഞ്ഞു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ വേറൊരാരാദ്ധ്യൻ ഇല്ല, അവൻ ഏകനാണ്, അവന് പങ്കുകാരില്ല എന്നും പിശാചിന്റെ ഉപദ്രവത്തിൽ നിന്ന് ഞാൻ അല്ലാഹുവിങ്കൽ അഭയം തേടുന്നു എന്നും നീ മൂന്നുതവണ ചൊല്ലുകയും, നിന്റെ ഇടതു വശത്തേക്ക് മൂന്നു തവണ തുപ്പുകയും ചെയ്യുക. ഇനി നീ അപ്രകാരം ചെയ്യരുത്." മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: ലാത്തയെയും ഉസ്സയെയും കൊണ്ട് ഞാൻ സത്യം ചെയ്തു. അപ്പോൾ എന്റെ സുഹൃത്തുക്കൾ എന്നോടു പറഞ്ഞു: നീ പറഞ്ഞത് അങ്ങേയറ്റം മ്ലേച്ഛമായിപ്പോയി. അസഭ്യമാണ് നീ പറഞ്ഞത്. ഉടനെ ഞാൻ തിരുദൂതർ(സ)യെ സമീപിച്ച് കാര്യം ഉണർത്തിച്ചു. അവിടുന്ന് പറഞ്ഞു: "ലാ ഇലാഹ ഇല്ലല്ലാഹു വഹ്ദഹൂ ലാ ഷരീക്കലഹു ലഹുൽ മുൽകു വലഹുൽ ഹംദു വഹുവ അലാ കുല്ലിഷയ്ഇൻ ഖദീർ (അല്ലാഹുവല്ലാതെ ആരാധ്യൻ ഇല്ല, അവൻ ഏകനാണ്, അവന് പങ്കുകാരനില്ല, സർവ്വ സ്തുതിയും അധികാരവും അവന്നാണ്, അവൻ സർവ്വത്തിനും കഴിവുള്ളവനാണ്) എന്ന് നീ പറയുക. എന്നിട്ട് നീ നിന്റെ ഇടതു പാർശത്തേക്ക് മൂന്നു തവണ തുപ്പുക, പിശാചിന്റെ ഉപദ്രവത്തിൽ നിന്ന് അല്ലാഹുവിങ്കൽ ശരണം തേടുക. മേലിൽ ആ രൂപത്തിലുള്ള സത്യം ചെയ്യൽ ആവർത്തിക്കാതിരിക്കുക." (ന)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 585, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=68), 1, 'وَفِي رِوَايَةٍ قَالَ: حَلَفْتُ بِاللَّاتِ وَالْعُزَّى، فَقَالَ لِي أَصْحَابِي: بِئْسَ مَا قُلْتَ، قُلْتَ هُجْرًا. فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: "قُلْ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. وَانْفُثْ عَنْ يَسَارِكَ ثَلَاثًا، وَتَعَوَّذْ بِاللَّهِ مِنَ الشَّيْطَانِ، ثُمَّ لَا تَعُدْ". (ن)', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: ലാത്തയെയും ഉസ്സയെയും കൊണ്ട് ഞാൻ സത്യം ചെയ്തു. അപ്പോൾ എന്റെ സുഹൃത്തുക്കൾ എന്നോടു പറഞ്ഞു: നീ പറഞ്ഞത് അങ്ങേയറ്റം മ്ലേച്ഛമായിപ്പോയി. അസഭ്യമാണ് നീ പറഞ്ഞത്. ഉടനെ ഞാൻ തിരുദൂതർ(സ)യെ സമീപിച്ച് കാര്യം ഉണർത്തിച്ചു. അവിടുന്ന് പറഞ്ഞു: "ലാ ഇലാഹ ഇല്ലല്ലാഹു വഹ്ദഹൂ ലാ ഷരീക്കലഹു ലഹുൽ മുൽകു വലഹുൽ ഹംദു വഹുവ അലാ കുല്ലിഷയ്ഇൻ ഖദീർ (അല്ലാഹുവല്ലാതെ ആരാധ്യൻ ഇല്ല, അവൻ ഏകനാണ്, അവന് പങ്കുകാരനില്ല, സർവ്വ സ്തുതിയും അധികാരവും അവന്നാണ്, അവൻ സർവ്വത്തിനും കഴിവുള്ളവനാണ്) എന്ന് നീ പറയുക. എന്നിട്ട് നീ നിന്റെ ഇടതു പാർശത്തേക്ക് മൂന്നു തവണ തുപ്പുക, പിശാചിന്റെ ഉപദ്രവത്തിൽ നിന്ന് അല്ലാഹുവിങ്കൽ ശരണം തേടുക. മേലിൽ ആ രൂപത്തിലുള്ള സത്യം ചെയ്യൽ ആവർത്തിക്കാതിരിക്കുക." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَمَّا خَلَقَ اللهُ الْجَنَّةَ وَالنَّارَ أَرْسَلَ جِبْرِيلَ عَلَيْهِ السَّلَامُ إِلَى الْجَنَّةِ فَقَالَ: انْظُرْ إِلَيْهَا وَإِلَى مَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا. فَنَظَرَ إِلَيْهَا فَرَجَعَ فَقَالَ: وَعِزَّتِكَ، لَا يَسْمَعُ بِهَا أَحَدٌ إِلَّا دَخَلَهَا. فَأَمَرَ بِهَا فَحُفَّتْ بِالْمَكَارِهِ، فَقَالَ: اذْهَبْ إِلَيْهَا فَانْظُرْ إِلَيْهَا وَإِلَى مَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا. فَنَظَرَ إِلَيْهَا فَإِذَا هِيَ قَدْ حُفَّتْ بِالْمَكَارِهِ، فَقَالَ: وَعِزَّتِكَ، لَقَدْ خَشِيتُ أَنْ لَا يَدْخُلَهَا أَحَدٌ. قَالَ: اذْهَبْ فَانْظُرْ إِلَى النَّارِ وَإِلَى مَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا. فَنَظَرَ إِلَيْهَا فَإِذَا هِيَ يَرْكَبُ بَعْضُهَا بَعْضًا، فَرَجَعَ فَقَالَ: وَعِزَّتِكَ، لَا يَدْخُلُهَا أَحَدٌ. فَأَمَرَ بِهَا فَحُفَّتْ بِالشَّهَوَاتِ، فَقَالَ: ارْجِعْ فَانْظُرْ إِلَيْهَا. فَنَظَرَ إِلَيْهَا فَإِذَا هِيَ قَدْ حُفَّتْ بِالشَّهَوَاتِ، فَرَجَعَ وَقَالَ: وَعِزَّتِكَ لَقَدْ خَشِيتُ أَنْ لَا يَنْجُوَ مِنْهَا أَحَدٌ إِلَّا دَخَلَهَا". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു സ്വർഗ്ഗ നരകങ്ങളെ സൃഷ്ടിച്ചപ്പോൾ ജീബ്രീൽ(അ)നെ സ്വർഗ്ഗത്തിലേക്ക് പറഞ്ഞയച്ചു കൊണ്ട് പറഞ്ഞു: സ്വർഗ്ഗത്തിലേക്കും അതിന്റെ അവകാശികൾക്കായി ഞാൻ ഒരുക്കിയതിലേക്കും നീ പോയി നോക്കുക. ജിബ്രീൽ(അ) നോക്കി മടങ്ങി വന്നു പറഞ്ഞു: നിന്റെ മഹത്വം തന്നെ സത്യം! സ്വർഗ്ഗത്തെപ്പറ്റി കേൾക്കാൻ ഇടവരുന്ന ആരും അതിൽ പ്രവേശിച്ചു പോകും. അപ്പോൾ പ്രയാസങ്ങളാൽ സ്വർഗത്തെ വലയം ചെയ്യപ്പെടാൻ അല്ലാഹു കൽപ്പിച്ചു. അപ്രകാരം സ്വർഗ്ഗത്തെ പ്രയാസങ്ങളാൽ ചുറ്റപ്പെട്ടു. പിന്നെ അല്ലാഹു പറഞ്ഞു: നീ സ്വർഗ്ഗത്തിൽ പോയി അവിടെ സ്വർഗ്ഗവാസികൾക്കായി നാമൊരുക്കിയത് നോക്കുക. ജിബ്രീൽ(അ) അതിലേക്ക് നോക്കി. അപ്പോൾ സ്വർഗ്ഗം പ്രയാസങ്ങളാൽ ചുറ്റപ്പെട്ടതായിക്കണ്ടു. ജിബ്രീൽ(അ) പറഞ്ഞു: നിന്റെ മഹത്വം തന്നെ സത്യം! ആരും തന്നെ സ്വർഗത്തിൽ പ്രവേശിക്കുകയില്ലെന്നു ഞാൻ ഭയപ്പെടുന്നു. അല്ലാഹു പറഞ്ഞു: നരകത്തിൽ പോയി അതിലേക്കും നരകവാസികൾക്കായി നാമൊരുക്കിയതിലേക്കും നോക്കുക. ജിബ്രീൽ(അ) അതിലേക്ക് നോക്കി. ഒന്നിനു മുകളിൽ മറ്റൊന്നായി അത് ഇളകിമറിയുന്നതായിക്കണ്ടു. മടങ്ങി വന്നു പറഞ്ഞു: നിന്റെ മഹത്വം തന്നെ സത്യം! ആരും അതിൽ പ്രവേശിക്കുകയില്ല. അപ്പോൾ ദേഹേച്ഛകളാൾ നരകം വലയം ചെയ്യപ്പെടാൻ അല്ലാഹു കൽപ്പിച്ചു. അപ്രകാരം ദേഹേച്ഛകളാൽ നരകം വലയം ചെയ്യപ്പെട്ടു. അപ്പോൾ അല്ലാഹു പറഞ്ഞു: നീ മടങ്ങിച്ചെല്ലുക. എന്നിട്ട് അതിലേക്ക് നോക്കൂക. അപ്പോൾ ജിബ്രീൽ(അ) മടങ്ങിച്ചെന്ന് അതിലേക്ക് നോക്കുകയും ഇച്ഛകളാൽ അത് ചുറ്റപ്പെട്ടതായി കാണുകയും ചെയ്തു. പിന്നീട് മടങ്ങിച്ചെന്ന് പറഞ്ഞു: നിന്റെ മഹത്വം തന്നെ സത്യം! അതിനെ സമീപിക്കുന്ന ഒരാളും അതിൽപ്പെടാതിരിക്കില്ല എന്ന് ഞാൻ ഭയപ്പെടുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 586, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي رَهْطٍ مِنَ الْأَشْعَرِيِّينَ نَسْتَحْمِلُهُ، فَقَالَ: "وَاللهِ لَا أَحْمِلُكُمْ، وَمَا عِنْدِي مَا أَحْمِلُكُمْ عَلَيْهِ". قَالَ: فَلَبِثْنَا مَا شَاءَ اللهُ، ثُمَّ أُتِيَ بِإِبِلٍ فَأَمَرَ لَنَا بِثَلَاثِ ذَوْدٍ غُرِّ الذُّرَى، فَلَمَّا انْطَلَقْنَا، قُلْنَا – أَوْ: قَالَ بَعْضُنَا لِبَعْضٍ – لَا يُبَارِكُ اللهُ لَنَا، أَتَيْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَسْتَحْمِلُهُ، فَحَلَفَ أَنْ لَا يَحْمِلَنَا، ثُمَّ حَمَلَنَا. فَأَتَوْهُ فَأَخْبَرُوهُ، فَقَالَ: "مَا أَنَا حَمَلْتُكُمْ وَلَكِنَّ اللهَ حَمَلَكُمْ، وَإِنِّي – وَاللهِ، إِنْ شَاءَ اللهُ – لَا أَحْلِفُ عَلَى يَمِينٍ ثُمَّ أَرَى خَيْرًا مِنْهَا، إِلَّا كَفَّرْتُ [عَنْ] يَمِينِي وَأَتَيْتُ الَّذِي هُوَ خَيْرٌ". (م,ن)', 'അബൂമൂസൽ അശ്അരി(റ): അശ്അരീ ഗോത്രത്തിലെ ഒരു സംഘം ആളുകളോടൊപ്പം ഞാൻ തിരുദൂതർ(സ)യെ സമീപിച്ചു. യാത്രാവശ്യാർത്ഥം ഒരുപറ്റം ഒട്ടകങ്ങളെക്കിട്ടുക എന്നതായിരുന്നു ഞങ്ങളുടെ ഉദ്ദേശ്യം. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹു തന്നെ സത്യം, നിങ്ങൾക്ക് ഒട്ടകങ്ങൾ തരാൻ എനിക്ക് സാധിക്കില്ല. യാത്രയ്ക്കായി തരാവുന്ന ഒട്ടകങ്ങൾ എന്റെ പക്കൽ ഇല്ല." ഞങ്ങൾ അൽപനേരം അവിടെത്തന്നെ ഇരുന്നു. ശേഷം കുറേയേറെ ഒട്ടകങ്ങൾ അവിടെ എത്തിച്ചേർന്നു. പൂഞ്ഞ വെളുത്ത മൂന്ന് ദൗദ ഒട്ടകങ്ങൾ ഞങ്ങൾക്ക് നൽകാൻ തിരുമേനി(സ) കൽപ്പിച്ചു. ഞങ്ങളുടെ യാത്രാസംഘം നീങ്ങിത്തുടങ്ങവേ ഞങ്ങൾ പരസ്പരം പറഞ്ഞു: ദൈവാനുഗ്രഹം നമ്മുടെ മേൽ വർഷിക്കാതിരിക്കട്ടെ. ഒട്ടകങ്ങളെ തരികയില്ലെന്ന് തിരുദൂതർ(സ) നമ്മോടു സത്യം ചെയ്തു. പക്ഷേ പിന്നീട് തരികയും ചെയ്തു. (ഇത് സത്യലംഘനമാവില്ലേ?) ഞങ്ങളുടനെ മടങ്ങിച്ചെന്ന് നബി(സ)യോട് സംശയം ഉന്നയിച്ചു. തിരുമേനി(സ) പറഞ്ഞു: "ഞാനല്ലല്ലോ നിങ്ങൾക്ക് വാഹനങ്ങൾ നൽകിയത്. അല്ലാഹുവാകുന്നു യാത്രയ്ക്കുള്ള വാഹനങ്ങൾ നിങ്ങൾക്കേകിയത്. ഇൻഷാഅല്ലാഹ്, അല്ലാഹുവാണ് സത്യം! ഞാൻ ഒരു സത്യം ചെയ്യുകയും തുടർന്ന് അതിനേക്കാൾ മെച്ചമാർന്ന മറ്റൊന്ന് കാണുകയും ചെയ്താൽ ഞാൻ സത്യലംഘനത്തിന് പ്രായശ്ചിത്തം നൽകുകയും നല്ലതായി കണ്ട കാര്യം പ്രവർത്തിക്കുകയും ചെയ്യും." (മു,ന)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], 'عَنْ', null, 587, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَعْتَمَ رَجُلٌ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ رَجَعَ إِلَى أَهْلِهِ فَوَجَدَ الصِّبْيَةَ قَدْ نَامُوا، فَأَتَاهُ أَهْلُهُ بِطَعَامِهِ، فَحَلَفَ لَا يَأْكُلُ مِنْ أَجْلِ صِبْيَتِهِ، ثُمَّ بَدَا لَهُ فَأَكَلَ، فَأَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ عَلَى يَمِينٍ، فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا، فَلْيَأْتِهَا وَلْيُكَفِّرْ عَنْ يَمِينِهِ". (م)', 'അബൂഹുറൈറ(റ): രാത്രിയേറെ വൈകുംവരെ ഒരാൾ നബി(സ)യുടെ സന്നിധിയിൽ ചെലവഴിച്ചു. പിന്നീട് വീട്ടിലേക്ക് മടങ്ങി. കുഞ്ഞുങ്ങൾ എല്ലാം ഉറങ്ങിയിരുന്നു. ഭാര്യ അദ്ദേഹത്തിന് ഭക്ഷണം വിളമ്പി. കുട്ടികൾ ഉറങ്ങിയതിനാൽ ഭക്ഷണം കഴിക്കുന്നില്ലെന്ന് അദ്ദേഹം സത്യം ചെയ്തു. പിന്നീട് ഭക്ഷണം കഴിക്കാൻ തോന്നുകയും കഴിക്കുകയും ചെയ്തു. അതിനു ശേഷം അദ്ദേഹം നബി(സ)യെ സമീപിച്ച് വിവരം പറഞ്ഞു. തിരുമേനി(സ) അരുളി: "ഒരാൾ സത്യം ചെയ്യുകയും പിന്നീട് അതിനേക്കാൾ നല്ലത് മറ്റൊന്നാണ് എന്ന് കാണുകയും ചെയ്താൽ അയാൾ നല്ലകാര്യം ചെയ്യുകയും സത്യലംഘനത്തിന് പ്രായശ്ചിത്തം നൽകുകയും ചെയ്യട്ടെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 587, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا عَلَى الْأَرْضِ يَمِينٌ أَحْلِفُ عَلَيْهَا، فَأَرَى غَيْرَهَا خَيْرًا مِنْهَا، إِلَّا أَتَيْتُهُ". (م)', 'അബൂമൂസാ(റ): നബി(സ) പറഞ്ഞു: "ഭൂലോകത്തുള്ള ഏതൊരു വസ്തുവിനെപ്പറ്റിയും ഞാൻ സത്യം ചെയ്യുകയും മറ്റൊന്നാണ് അതിനേക്കാൾ മെച്ചമെന്ന് മനസ്സിലാക്കുകയും ചെയ്താൽ മെച്ചമായ കാര്യമാണ് ഞാൻ നിറവേറ്റുക." (മു)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 588, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَبْدَ الرَّحْمَنِ، لَا تَسْأَلِ الْإِمَارَةَ، فَإِنَّكَ إِنْ أَتَتْكَ عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا، وَإِنْ أَتَتْكَ عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا. وَإِذَا حَلَفْتَ عَلَى يَمِينٍ: فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا، فَأْتِ الَّذِي هُوَ خَيْرٌ، وَلْتُكَفِّرْ عَنْ يَمِينِكَ". (ق,د,ت,جه)', 'അബ്ദുറഹ്മാൻ ഇബ്നു സമുറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അബ്ദുറഹ്മാനേ, നീ ഒരിക്കലും അധികാരം ചോദിച്ചുവാങ്ങരുത്. ആവശ്യപ്പെട്ടതുകൊണ്ടാണ് നിനക്ക് അധികാരം കിട്ടുന്നതെങ്കിൽ നിന്നിൽ അതിന്റെ സർവ്വഭാരവും ഏൽപ്പിക്കപ്പെടും. ചോദിക്കാതെ തന്നെ നിനക്കത് ലഭ്യമാവുകയാണെങ്കിൽ അതിന്റെ കാര്യത്തിൽ നീ സഹായിക്കപ്പെടും. ഒരു കാര്യം ചെയ്യുമെന്ന് നീ സത്യം ചെയ്യുകയും അതിനേക്കാൾ മെച്ചപ്പെട്ടത് മറ്റൊന്നാണെന്ന് നിനക്ക് ബോധ്യം വരികയും ചെയ്താൽ നല്ലതായിക്കണ്ട ആ കാര്യം നീ നിർവ്വഹിക്കുക. സത്യലംഘനത്തിന് പ്രായശ്ചിത്തം നൽകുകയും ചെയ്യുക." (ബു,മു,ദ,തു,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ', 'അബ്ദുറഹ്മാൻ ഇബ്നു സമുറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 588, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ فَقَالَ: إِنْ شَاءَ اللهُ، فَقَدِ اسْتَثْنَى". وَفِي رِوَايَةٍ: "مَنْ حَلَفَ عَلَى يَمِينٍ فَقَالَ: إِنْ شَاءَ اللهُ، فَهُوَ بِالْخِيَارِ: إِنْ شَاءَ أَمْضَى وَإِنْ شَاءَ تَرَكَ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): തിരുദൂതർ(സ) അരുളി: "സത്യം ചെയ്യുന്നയാൾ അതോടൊപ്പം ഇൻഷാഅല്ലാഹ് എന്നു പറയുകയാണെങ്കിൽ അയാൾ സത്യലംഘനത്തിൽ നിന്ന് ഒഴിവാകുന്നതാണ്." മറ്റൊരു നിവേദനപ്രകാരം: "ഒരാൾ ഒരു കാര്യം നിർവ്വഹിക്കുമെന്ന് സത്യം ചെയ്യുമ്പോൾ അതോടൊപ്പം ഇൻഷാഅല്ലാഹ് എന്നു പറഞ്ഞാൽ അയാൾക്ക് അയാളുടെ യുക്തം പോലെ ചെയ്യാം. വേണമെങ്കിൽ സത്യം നിറവേറ്റാം, അല്ലെങ്കിൽ ഉപേക്ഷിക്കാം." (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 588, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=74), 1, 'وَفِي رِوَايَةٍ: "مَنْ حَلَفَ عَلَى يَمِينٍ فَقَالَ: إِنْ شَاءَ اللهُ، فَهُوَ بِالْخِيَارِ: إِنْ شَاءَ أَمْضَى وَإِنْ شَاءَ تَرَكَ". (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനപ്രകാരം: "ഒരാൾ ഒരു കാര്യം നിർവ്വഹിക്കുമെന്ന് സത്യം ചെയ്യുമ്പോൾ അതോടൊപ്പം ഇൻഷാഅല്ലാഹ് എന്നു പറഞ്ഞാൽ അയാൾക്ക് അയാളുടെ യുക്തം പോലെ ചെയ്യാം. വേണമെങ്കിൽ സത്യം നിറവേറ്റാം, അല്ലെങ്കിൽ ഉപേക്ഷിക്കാം." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ فَاسْتَثْنَى: فَإِنْ شَاءَ رَجَعَ، وَإِنْ شَاءَ تَرَكَ غَيْرَ حَنِثٍ". (د,ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "സത്യം ചെയ്യുമ്പോൾ ഒരാൾ ഇൻഷാ അല്ലാഹ് എന്ന് പറഞ്ഞ് ഒഴിവായാൽ അയാൾക്ക് വേണമെങ്കിൽ ആ സത്യത്തിലേക്ക് തന്നെ മടങ്ങാം, അല്ലെങ്കിൽ സത്യലംഘനത്തിന്റെ കുറ്റമില്ലാതെ തന്നെ അതുപേക്ഷിക്കാം." (ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 588, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَلَفَ عَلَى يَمِينٍ فَقَالَ: إِنْ شَاءَ اللهُ، فَقَدِ اسْتَثْنَى، فَلَا حِنْثَ عَلَيْهِ". حَسَنٌ. (د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "സത്യം ചെയ്ത് പറയുന്ന ആൾ ഇൻഷാഅല്ലാഹ് എന്ന് ഉരിയാടിയാൽ അയാൾ സത്യലംഘനത്തിൽനിന്ന് ഒഴിവാകുന്നതാണ്, സത്യം ലംഘിക്കുക എന്ന പ്രശ്നം അവന്നില്ല." (ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 589, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَلَفَ فَقَالَ: إِنْ شَاءَ اللهُ، لَمْ يَحْنَثْ". (ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "സത്യം ചെയ്യുന്ന വേളയിൽ ആരെങ്കിലും ഇൻഷാഅല്ലാഹ് എന്ന് പറഞ്ഞാൽ അയാൾ സത്യലംഘനം ചെയ്ത ആളായിത്തീരില്ല." (തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 589, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَالَ سُلَيْمَانُ بْنُ دَاوُدَ: لَأَطُوفَنَّ اللَّيْلَةَ عَلَى تِسْعِينَ امْرَأَةً، كُلُّهُنَّ يَأْتِي بِفَارِسٍ يُجَاهِدُ فِي سَبِيلِ اللهِ عَزَّ وَجَلَّ، فَقَالَ لَهُ صَاحِبُهُ: إِنْ شَاءَ اللهُ، فَلَمْ يَقُلْ: إِنْ شَاءَ اللهُ، فَطَافَ عَلَيْهِنَّ جَمِيعًا، فَلَمْ تَحْمِلْ مِنْهُنَّ إِلَّا امْرَأَةٌ وَاحِدَةٌ، جَاءَتْ بِشِقِّ رَجُلٍ. وَأَيْمُ الَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوْ قَالَ: إِنْ شَاءَ اللهُ، لَجَاهَدُوا فِي سَبِيلِ اللهِ فُرْسَانًا أَجْمَعِينَ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ദവൂദ് നബി(അ)ന്റെ മകൻ സുലൈമാൻ നബി(അ) പറഞ്ഞു: ഈ രാത്രിയിൽ നിശ്ചയമായും ഞാൻ തൊണ്ണൂറ് പത്നിമാരേയും സന്ദർശിക്കും, അവർ ഓരോരുത്തരും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്ന ഓരോ കുതിരപ്പടയാളിയെ പ്രസവിക്കും. അപ്പോൾ അവിടുത്തെ കൂട്ടുകാരൻ അവിടുത്തോട് ഇൻഷാഅല്ലാഹ് എന്നു പറഞ്ഞു. പക്ഷേ, സുലൈമാൻ നബി(അ) ഇൻഷാഅല്ലാഹ് എന്നു പറഞ്ഞില്ല. തുടർന്ന് സുലൈമാൻ നബി(അ) ഭാര്യമാരെയെല്ലാം പ്രാപിച്ചു. ഒരു സ്ത്രീ ഒഴികെ മറ്റാരും ഗർഭം ധരിച്ചില്ല. അവൾ പ്രസവിച്ചതോ ഒരു അർദ്ധമനുഷ്യനെയും. മുഹമ്മദിന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനെക്കൊണ്ട് സത്യം, സുലൈമാൻ(അ) ഇൻഷാഅല്ലാഹ് എന്നു പറഞ്ഞിരുന്നുവെങ്കിൽ കുതിരപ്പടയാളികളായി അവരെല്ലാം ദൈവമാർഗ്ഗത്തിൽ യുദ്ധം ചെയ്യുമായിരുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 589, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَالَ سُلَيْمَانُ بْنُ دَاوُدَ نَبِيُّ اللهِ عَلَيْهِمَا السَّلَامُ: لَأَطُوفَنَّ اللَّيْلَةَ عَلَى سَبْعِينَ امْرَأَةً، كُلُّهُنَّ تَأْتِي بِغُلَامٍ يُقَاتِلُ فِي سَبِيلِ اللهِ. فَقَالَ لَهُ صَاحِبُهُ أَوِ الْمَلَكُ: قُلْ: إِنْ شَاءَ اللهُ، فَلَمْ يَقُلْ وَنَسِيَ، فَلَمْ تَأْتِ وَاحِدَةٌ مِنْ نِسَائِهِ إِلَّا وَاحِدَةٌ جَاءَتْ بِشِقِّ غُلَامٍ". فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَلَوْ قَالَ: إِنْ شَاءَ اللهُ، لَمْ يَحْنَثْ، وَكَانَ دَرَكًا لَهُ فِي حَاجَتِهِ". (ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ പ്രവാചകൻ ദാവൂദ്(അ)മിന്റെ മകൻ സുലൈമാൻ(അ) പറഞ്ഞു: ഇന്നു രാത്രി എഴുപത് ഇണകളേയും ഞാൻ പ്രാപിക്കും. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സമരം ചെയ്യുന്ന ഓരോരുത്തരെ അവരെല്ലാം പ്രസവിക്കും. അന്നേരം അദ്ദേഹത്തിന്റെ ഒരു കൂട്ടുകാരനോ, മലകോ പറഞ്ഞു: ഇൻഷാഅല്ലാഹ് എന്നു പറയൂ. അദ്ദേഹം പറഞ്ഞില്ല, മറന്നുപോയി. ഒരു ഭാര്യയല്ലാതെ മറ്റാരും തന്നെ പ്രസവിച്ചില്ല. അതും ഒരു കുഞ്ഞിന്റെ കഷ്ണം മാത്രം." റസൂൽ(സ) പറഞ്ഞു: "സുലൈമാൻ നബി(അ) ഇൻഷാഅല്ലാഹ് എന്നു പറഞ്ഞിരുന്നെങ്കിൽ സത്യലംഘനം ചെയ്ത ആളായിത്തീരുമായിരുന്നില്ല. തന്റെ ആവശ്യം പൂർത്തീകരിക്കുകയും ചെയ്യുമായിരുന്നു." (തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 589, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحْلِفُ أَحَدٌ عِنْدَ مِنْبَرِي هَذَا عَلَى يَمِينٍ آثِمَةٍ، وَلَوْ عَلَى سِوَاكٍ أَخْضَرَ، إِلَّا تَبَوَّأَ مَقْعَدَهُ مِنَ النَّارِ. أَوْ وَجَبَتْ لَهُ النَّارُ". (د,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറയുകയുണ്ടായി: "എന്റെ ഈ മിമ്പറിനടുത്ത്വച്ച്, ഒരു കഷ്ണം പച്ച മിസ്വാക്കിനാണെങ്കിൽ പോലും, ആരെങ്കിലും കുറ്റകരമായ സത്യംചെയ്താൽ നരകത്തിൽ അവൻ സ്വന്തം ഇരിപ്പിടം ഒരുക്കിയിരിക്കുന്നു, അല്ലെങ്കിൽ അവന് നരകം നിർബന്ധമായിരിക്കുന്നു." (ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 590, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَمِينُكَ عَلَى مَا يُصَدِّقُكَ عَلَيْهَا صَاحِبُكَ". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "നീ സത്യം ചെയ്യുന്നത് നിന്റെ ഒപ്പമുള്ളവൻ നിന്നെ വിശ്വസിക്കുന്ന രൂപത്തിലായിരിക്കണം." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 590, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ سُوَيْدِ بْنِ حَنْظَلَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا نُرِيدُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَعَنَا وَائِلُ بْنُ حُجْرٍ، فَأَخَذَهُ عَدُوٌّ لَهُ، فَتَحَرَّجَ الْقَوْمُ أَنْ يَحْلِفُوا، وَحَلَفْتُ أَنَّهُ أَخِي، فَخَلَّى سَبِيلَهُ، فَأَتَيْنَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ أَنَّ الْقَوْمَ تَحَرَّجُوا أَنْ يَحْلِفُوا، وَحَلَفْتُ أَنَّهُ أَخِي؟ قَالَ: "صَدَقْتَ، الْمُسْلِمُ أَخُو الْمُسْلِمِ". (د,جه)', 'സുവൈദുബ്നു ഹൻദലത്(റ): ഒരിക്കൽ നബി(സ)യുടെ സന്നിധി ലക്ഷ്യമാക്കി ഞങ്ങൾ യാത്ര തിരിച്ചു. സഹചാരിയായി വാഇലുബ്നു ഹുജ്ർ(റ)വും ഉണ്ടായിരുന്നു. അങ്ങനെ വഴിമദ്ധ്യേ അദ്ദഹത്തിന്റെ ശത്രു അദ്ദേഹത്തെ പിടികൂടി. അപ്പോൾ ജനങ്ങൾക്ക് (അദ്ദേഹം ആരാണെന്ന്) സത്യംചെയ്ത് പറയാൻ പ്രയാസമനുഭവപ്പെട്ടു. ഒടുവിൽ ഞാൻ ഇദ്ദേഹം എന്റെ സഹോദരനാണ് എന്ന് സത്യം ചെയ്തു. അപ്പോൾ അയാൾ അദ്ദേഹത്തെ മോചിപ്പിച്ചു. ഞങ്ങൾ നബി(സ)യുടെ സന്നിധിയിൽ എത്തി. ഞാൻ തിരുമേനി(സ)യോട് പറഞ്ഞു: ആരും സത്യം ചെയ്തു പറയാൻ തയ്യാറായില്ല. ഒടുവിൽ അദ്ദേഹം എന്റെ സഹോദരനാണെന്ന് ഞാൻ സത്യം ചെയ്തു? തിരുമേനി(സ) പറഞ്ഞു: "നീ പറഞ്ഞത് സത്യമാണ്. ഒരു മുസ്ലിം മറ്റൊരു മുസ്ലിമിന്റെ സഹോദരനാണ്." (ദ,ജ)', 'سُوَيْدِ بْنِ حَنْظَلَةَ', 'സുവൈദുബ്നു ഹൻദലത്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 590, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَا بَكْرٍ رَضِيَ اللهُ عَنْهُ أَقْسَمَ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُقْسِمْ". وَفِي رِوَايَةٍ عَنْهُ قَالَ: كَانَ أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ يُحَدِّثُ: أَنَّ رَجُلًا أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي أَرَى اللَّيْلَةَ، فَذَكَرَ رُؤْيَا، فَعَبَّرَهَا أَبُو بَكْرٍ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَصَبْتَ بَعْضًا وَأَخْطَأْتَ بَعْضًا". فَقَالَ: أَقْسَمْتُ عَلَيْكَ يَا رَسُولَ اللهِ – بِأَبِي أَنْتَ – لَتُحَدِّثَنِّي مَا الَّذِي أَخْطَأْتُ؟ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُقْسِمْ". (ق,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അബൂബക്കർ(റ) ഒരിക്കൽ നബി(സ)യുടെ മേൽ സത്യം ചെയ്തു. അപ്പോൾ അദ്ദേഹത്തോട് നബി(സ) അരുളി: "താങ്കൾ സത്യം ചെയ്യരുത്." മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെ: നിവേദകൻ പറഞ്ഞു: അബൂഹുറൈറ(റ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: ഒരിക്കൽ ഒരാൾ നബി(സ)യുടെ അടുത്തു വന്നു പറഞ്ഞു: രാത്രിയിൽ ഞാനെരു സ്വപ്നം കണ്ടു. തുടർന്ന് സ്വപനമെന്തെന്ന് അയാൾ വിവരിച്ചു. തുടർന്ന് അബൂബകർ(റ) ആ സ്വപ്നത്തിന് വ്യാഖ്യാനം നൽകി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "താങ്കൾ പറഞ്ഞതിൽ ചിലത് ശരിയാണ്. മറ്റുചിലത് തെറ്റുമാണ്." അപ്പോൾ അബൂബകർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയുടെ മേൽ സത്യം ചെയ്തു ഞാൻ ചോദിക്കുന്നു. അങ്ങെനിക്ക് പിതൃതുല്യനാണല്ലോ! ഏതിലാണ് തെറ്റുപറ്റിയതെന്ന് അങ്ങെനിക്ക് വിശദമാക്കിത്തരികതന്നെ വേണം. നബി(സ) പറഞ്ഞു: "താങ്കൾ സത്യം ചെയ്യരുത്." (ബു,മു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 590, 591, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=83), 1, 'وَفِي رِوَايَةٍ عَنْهُ قَالَ: كَانَ أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ يُحَدِّثُ: أَنَّ رَجُلًا أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي أَرَى اللَّيْلَةَ، فَذَكَرَ رُؤْيَا، فَعَبَّرَهَا أَبُو بَكْرٍ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَصَبْتَ بَعْضًا وَأَخْطَأْتَ بَعْضًا". فَقَالَ: أَقْسَمْتُ عَلَيْكَ يَا رَسُولَ اللهِ – بِأَبِي أَنْتَ – لَتُحَدِّثَنِّي مَا الَّذِي أَخْطَأْتُ؟ فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُقْسِمْ". (ق,د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെ: നിവേദകൻ പറഞ്ഞു: അബൂഹുറൈറ(റ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: ഒരിക്കൽ ഒരാൾ നബി(സ)യുടെ അടുത്തു വന്നു പറഞ്ഞു: രാത്രിയിൽ ഞാനെരു സ്വപ്നം കണ്ടു. തുടർന്ന് സ്വപനമെന്തെന്ന് അയാൾ വിവരിച്ചു. തുടർന്ന് അബൂബകർ(റ) ആ സ്വപ്നത്തിന് വ്യാഖ്യാനം നൽകി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "താങ്കൾ പറഞ്ഞതിൽ ചിലത് ശരിയാണ്. മറ്റുചിലത് തെറ്റുമാണ്." അപ്പോൾ അബൂബകർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയുടെ മേൽ സത്യം ചെയ്തു ഞാൻ ചോദിക്കുന്നു. അങ്ങെനിക്ക് പിതൃതുല്യനാണല്ലോ! ഏതിലാണ് തെറ്റുപറ്റിയതെന്ന് അങ്ങെനിക്ക് വിശദമാക്കിത്തരികതന്നെ വേണം. നബി(സ) പറഞ്ഞു: "താങ്കൾ സത്യം ചെയ്യരുത്." (ബു,മു,ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ بِالْأَمَانَةِ فَلَيْسَ مِنَّا". (د)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിശ്വസ്തത കൊണ്ട് സത്യം ചെയ്യുന്നവൻ നമ്മിൽ പെട്ടവനല്ല." (ദ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 591, 591, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "هُوَ كَلَامُ الرَّجُلِ فِي بَيْتِهِ: كَلَّا وَاللهِ، وَبَلَى وَاللهِ". (خ,د)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "വീട്ടിലിരുന്ന് കൊണ്ട് ഒരുത്തൻ ''ഇല്ല, അല്ലാഹുവാണ് സത്യം! അതെ, അല്ലാഹുവാണ് സത്യം!'' എന്നിങ്ങനെ പറയുന്നതാണ് വൃഥാ സത്യം." (ബു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 591, 591, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ ثَابِتِ بْنِ الضَّحَّاكِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَلَفَ بِمِلَّةٍ غَيْرِ مِلَّةِ الْإِسْلَامِ كَاذِبًا فَهُوَ كَمَا قَالَ، وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عُذِّبَ بِهِ يَوْمَ الْقِيَامَةِ، وَلَيْسَ عَلَى رَجُلٍ نَذْرٌ فِيمَا لَا يَمْلِكُهُ". (ق,د,ت,ن,جه)', 'സാബിതുബ്നു ളഹാക്(റ): റസൂൽ(സ) പറഞ്ഞു: "കള്ളമായി, ഇസ്ലാം അല്ലാത്ത മറ്റേതെങ്കിലും മതത്തെ കൊണ്ട് ഒരാൾ സത്യം ചെയ്താൽ ആ പറഞ്ഞതുപോലെത്തന്നെ അവൻ ആയിത്തീരും. ഏതെങ്കിലും വസ്തു ഉപയോഗിച്ച് ആത്മഹത്യ ചെയ്യുന്നവൻ അന്ത്യനാളിൽ അതേ വസ്തുവാൽ ശിക്ഷിക്കപ്പെടുന്നതാണ്. തന്റെ അധീനതയിൽ ഇല്ലാത്ത ഒന്നിൽ ആരും നേർച്ച നേരരുത്." (ബു,മു,ദ,തു,ന,ജ)', 'ثَابِتِ بْنِ الضَّحَّاكِ', 'സാബിതുബ്നു ളഹാക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 591, 591, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ فَقَالَ: إِنِّي بَرِيءٌ مِنَ الْإِسْلَامِ: فَإِنْ كَانَ كَاذِبًا فَهُوَ كَمَا قَالَ، وَإِنْ كَانَ صَادِقًا فَلَنْ يَرْجِعَ إِلَى الْإِسْلَامِ سَالِمًا". (د,ن,جه)', 'ബുറൈദ(റ): റസൂൽ(സ) അരുളി: "സത്യം ചെയ്യുന്ന വേളയിൽ ഞാൻ ഇസ്ലാമിൽനിന്ന് മുക്തനാണ് എന്നാരെങ്കിലും പറഞ്ഞെന്നിരിക്കട്ടെ, അയാൾ പറഞ്ഞത് കള്ളമാണെങ്കിൽ അവൻ പറഞ്ഞതു പോലെ അവൻ ആയിത്തീരും. ഇനി അവൻ പറഞ്ഞത് സത്യമാണെങ്കിലോ അവൻ സുരക്ഷിതനായി ഇസ്ലാമിലേക്ക് മടങ്ങുകയില്ല." (ദ,ന,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 592, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ ثَابِتِ بْنِ الضَّحَّاكِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ بِمِلَّةٍ سِوَى الْإِسْلَامِ كَاذِبًا – وَفِي رِوَايَةٍ: مُتَعَمِّدًا – فَهُوَ كَمَا قَالَ. وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عَذَّبَهُ اللهُ بِهِ فِي نَارِ جَهَنَّمَ. وَفِي رِوَايَةٍ: فِي الْآخِرَةِ". (ن)', 'സാബിതുബ്നു ളഹ്ഹാക്ക്(റ): റസൂൽ(സ) അരുളി: "കള്ളമായി ആരെങ്കിലും ഇസ്ലാമല്ലാത്ത മതത്തെക്കൊണ്ട് സത്യം ചെയ്താൽ - മറ്റൊരുനിവേദനപ്രകാരം: മനപ്പൂർവ്വം സത്യം ചെയ്താൽ - അവൻ അപ്പറഞ്ഞതുപോലെയായി ഭവിക്കും. ആരെങ്കിലും ഏതെങ്കിലും വസ്തു ഉപയോഗിച്ച് ആത്മഹത്യ ചെയ്താൽ അതേവസ്തുകൊണ്ട് തന്നെ അല്ലാഹു അവനെ നരകത്തിൽ വച്ച് ശിക്ഷിക്കും. മറ്റൊരു നിവേദന പ്രകാരം: പരലോകത്ത് ശിക്ഷിക്കും." (ന)', 'ثَابِتِ بْنِ الضَّحَّاكِ', 'സാബിതുബ്നു ളഹ്ഹാക്ക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 592, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=88), 1, 'وَفِي رِوَايَةٍ: مُتَعَمِّدًا – فَهُوَ كَمَا قَالَ. وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عَذَّبَهُ اللهُ بِهِ فِي نَارِ جَهَنَّمَ.', 'മറ്റൊരു നിവേദനപ്രകാരം: മനപ്പൂർവ്വം സത്യം ചെയ്താൽ - അവൻ അപ്പറഞ്ഞതുപോലെയായി ഭവിക്കും. ആരെങ്കിലും ഏതെങ്കിലും വസ്തു ഉപയോഗിച്ച് ആത്മഹത്യ ചെയ്താൽ അതേവസ്തുകൊണ്ട് തന്നെ അല്ലാഹു അവനെ നരകത്തിൽ വച്ച് ശിക്ഷിക്കും.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=88), 2, 'وَفِي رِوَايَةٍ: فِي الْآخِرَةِ". (ن)', 'മറ്റൊരു നിവേദന പ്രകാരം: പരലോകത്ത് ശിക്ഷിക്കും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ يُوسُفَ بْنِ عَبْدِ اللهِ بْنِ سَلَامٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَضَعَ تَمْرَةً عَلَى كِسْرَةٍ، فَقَالَ: "هَذِهِ إِدَامُ هَذِهِ". (د)', 'യൂസുഫുബ്നു അബ്ദുല്ലാഹിബ്നു സലാം(റ): നബി(സ) ഒരു കഷ്ണം റൊട്ടിയിൽ ഒരു കാരയ്ക്ക വെച്ചിരിക്കുന്നത് ഞാൻ കണ്ടു. ശേഷം നബി(സ) പറഞ്ഞു: "ഇത് ഇതിന്റെ കറിയാണ്." (ദ)', 'يُوسُفَ بْنِ عَبْدِ اللهِ بْنِ سَلَامٍ', 'യൂസുഫുബ്നു അബ്ദുല്ലാഹിബ്നു സലാം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 592, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْتَهُ فَإِذَا فِلَقٌ وَخَلٌّ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلْ، فَنِعْمَ الْإِدَامُ الْخَلُّ". (ن)', 'ജാബിർ(റ): നബി(സ)യോടൊപ്പം ഞാൻ തിരുമേനി(സ)യുടെ വീട്ടിൽച്ചെന്നു. അവിടെ റൊട്ടിയും സുർക്കയും ഉണ്ടായിരുന്നു. അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "കഴിക്കൂ, സുർക്ക നല്ല കൂട്ടാനാണ്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 592, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَكْثَرُ مَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَحْلِفُ بِهَذِهِ الْيَمِينِ: "لَا، وَمُقَلِّبِ الْقُلُوبِ". (خ,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): "ഇല്ല, ഹൃദയങ്ങളെ മാറ്റിമറിക്കുന്നവനെ കൊണ്ട് സത്യം" എന്നീ വാക്കുകൾ സത്യം ചെയ്യുമ്പോൾ നബി(സ) അധികമായി ഉപയോഗിച്ചിരുന്നു. (ബു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 592, 592, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اجْتَهَدَ فِي الْيَمِينِ قَالَ: "وَالَّذِي نَفْسُ أَبِي الْقَاسِمِ بِيَدِهِ". (د)', 'അബൂസഇൗദിൽ ഖുദ്രി(റ): സത്യം ചെയ്യേണ്ടിവരുമ്പോൾ തിരുദൂതർ(സ) ഇങ്ങനെ പറഞ്ഞിരുന്നു: "അബുൽ ഖാസിമിന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനാണ് സത്യം." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഇൗദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 593, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ يَمِينُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا حَلَفَ يَقُولُ: "لَا، وَأَسْتَغْفِرُ اللهَ". (د,جه)', 'അബൂഹുറൈറ(റ): സത്യം ചെയ്യുമ്പോൾ സബി(സ) ഇങ്ങനെ പറഞ്ഞിരുന്നു: "ഇല്ല, അല്ലാഹുവിനോട് ഞാൻ പൊറുക്കലിനെ തേടുന്നു." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 593, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ لَقِيطِ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ: خَرَجَ وَافِدًا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ لَقِيطٌ: فَقَدِمْنَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ حَدِيثًا فِيهِ: فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَعَمْرُ إِلَهِكَ". (د)', 'ലഖീതുബ്നു ആമിർ(റ): ഒരിക്കൽ നബി(സ)യുടെ സന്നിധിയിലേക്ക് പ്രതിനിധിയായി അദ്ദേഹം പോവുകയുണ്ടായി. ലഖീത്(റ) പറയുന്നു: ഞങ്ങൾ റസൂൽ(സ)യുടെ സന്നിധിയിൽ എത്തി. തുടർന്ന് ലഖീത്(റ) ഒരു ഹദീസ് പറഞ്ഞു. അതിൽ ഇപ്രകാരമുണ്ട്: അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിന്റെ ഇലാഹിനെക്കൊണ്ട് സത്യം." (ദ)', 'لَقِيطِ بْنِ عَامِرٍ', 'ലഖീതുബ്നു ആമിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 593, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَمِينَ عَلَيْكَ وَلَا نَذْرَ فِي مَعْصِيَةِ الرَّبِّ، وَفِي قَطِيعَةِ الرَّحِمِ، وَفِيمَا لَا تَمْلِكُ". (د,ن)', 'ഉമർ(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിന് എതിരായതിലും കുടുംബബന്ധം വിച്ഛേദിക്കുന്നതിലും നിന്റെ ഉടമസ്ഥതയിൽ ഇല്ലാത്തതിലും സത്യം ചെയ്യലോ നേർച്ച നേരലോ അരുത്." (ദ,ന)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 593, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا نَذْرَ إِلَّا فِيمَا يُبْتَغَى بِهِ وَجْهُ اللهِ، وَلَا يَمِينَ فِي قَطِيعَةِ رَحِمٍ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ തൃപ്തി കാംക്ഷിക്കപ്പെടുന്നതിലല്ലാതെ നേർച്ചയില്ല. കുടുംബബന്ധം വിച്ഛേദിക്കുന്നതിൽ സത്യം ചെയ്യലും ഇല്ല." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 593, 593, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا نَذْرَ وَلَا يَمِينَ فِيمَا لَا يَمْلِكُ ابْنُ آدَمَ، وَلَا فِي مَعْصِيَةِ اللهِ، وَلَا فِي قَطِيعَةِ رَحِمٍ. وَمَنْ حَلَفَ عَلَى يَمِينٍ، فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا، فَلْيَدَعْهَا وَلْيَأْتِ الَّذِي هُوَ خَيْرٌ، فَإِنَّ تَرْكَهَا كَفَّارَتُهَا". قَالَ أَبُو دَاوُدَ: الْأَحَادِيثُ كُلُّهَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "وَلْيُكَفِّرْ عَنْ يَمِينِهِ". إِلَّا فِيمَا لَا يُعْبَأُ بِهِ. (د,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "തന്റെ ഉടമസ്ഥതയിൽ ഇല്ലാത്തതിൽ നേർച്ച നേരാനോ സത്യം ചെയ്യാനോ പാടില്ല. അല്ലാഹുവിനോടുള്ള ധിക്കാരത്തിലും കുടുംബബന്ധം വിഛേദിക്കുന്നതിലും അവ അരുത്. ഒരാൾ ഏതെങ്കിലും കാര്യത്തിൽ സത്യം ചെയ്യുകയും മറ്റൊന്നാണ് അതിനേക്കാൾ ഉത്തമമെന്ന് കാണുകയും ചെയ്താൽ ആദ്യത്തേത് ഉപേക്ഷിക്കുകയും രണ്ടാമത്തേത് നിർവ്വഹിക്കുയും ചെയ്യുക. ആദ്യത്തേതുപേക്ഷിക്കുന്നതാണ് അതിന്റെ പ്രായശ്ചിത്തം."
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا الْأَعْمَالُ بِالنِّيَّةِ، وَإِنَّمَا لِامْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَتَزَوَّجُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ". (ن)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ) പറഞ്ഞു: "എല്ലാ പ്രവർത്തനങ്ങളും നിയ്യത്തിന് അനുസൃതമായാണ്. ഒരാൾക്ക് അവൻ എന്താണോ ഉദ്ദേശിച്ചത് അതേ ലഭിക്കൂ. ഒരു വ്യക്തിയുടെ പലായനം അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും ഉദ്ദേശിച്ചുള്ളതാണെങ്കിൽ അവന്റെ പലായനം അല്ലാഹുവിലേക്കും അവന്റെ റസൂലിലേക്കും തന്നെ. ലൗകിക കാര്യങ്ങൾ ലഭിക്കുന്നതിനോ ഏതെങ്കിലും സ്ത്രീയെ വിവാഹം കഴിക്കുന്നതിനോ ആണ് അവന്റെ പലായനമെങ്കിൽ അവന്റെ യാത്ര അതിലേക്ക് മാത്രം." (ന)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 594, 594, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْيَمِينُ عَلَى نِيَّةِ الْمُسْتَحْلِفِ". (م)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "സത്യം ചെയ്യിക്കുന്നവന്റെ ഉദ്ദേശ്യമനുസരിച്ചാണ് സത്യം വിലയിരുത്തപ്പെടുക." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 594, 594, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ عَلَى يَمِينٍ مَصْبُورَةٍ كَاذِبًا، فَلْيَتَبَوَّأْ بِوَجْهِهِ مَقْعَدَهُ مِنَ النَّارِ". (د)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): നബി(സ) അരുളി: "തനിക്ക് നിർബന്ധമായി വന്ന കാര്യത്തിൽ ആരെങ്കിലും കള്ളസത്യം ചെയ്താൽ അവന്റെ മുഖം കൊണ്ടുതന്നെ അവൻ നരകത്തിൽ ഇരിപ്പിടം ഒരുക്കിക്കൊള്ളട്ടെ." (ദ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 594, 594, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَلَفَ عَلَى يَمِينٍ هُوَ فِيهَا فَاجِرٌ، لِيَقْتَطِعَ بِهَا مَالَ امْرِئٍ مُسْلِمٍ، لَقِيَ اللهَ وَهُوَ عَلَيْهِ غَضْبَانُ". فَقَالَ الْأَشْعَثُ: فِيَّ وَاللهِ كَانَ ذَلِكَ، كَانَ بَيْنِي وَبَيْنَ رَجُلٍ مِنَ الْيَهُودِ أَرْضٌ، فَجَحَدَنِي، فَقَدَّمْتُهُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَكَ بَيِّنَةٌ". قُلْتُ: لَا، قَالَ لِلْيَهُودِيِّ: "احْلِفْ". قُلْتُ: يَا رَسُولَ اللهِ، إِذًا يَحْلِفُ وَيَذْهَبُ بِمَالِي. فَأَنْزَلَ اللهُ تَعَالَى: {إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا} إِلَى آخِرِ الْآيَةِ. (د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിമായൊരു മനുഷ്യന്റെ മുതൽ അപഹരിക്കാൻ വേണ്ടി ഒരാൾ കള്ളസത്യം ചെയ്താൽ, തന്റെ മേൽ ദേഷ്യപ്പെട്ടവനായി അവൻ അല്ലാഹുവിനെ കണ്ടുമുട്ടും." അശ്അസ്(റ) പറഞ്ഞു: എനിക്ക് അത്തരമൊരു അനുഭവം ഉണ്ടായിട്ടുണ്ട്. എനിക്കും ഒരു യഹൂദിക്കുമിടയിൽ ഒരു തർക്കഭൂമിയുണ്ടായിരുന്നു. യഹൂദി എനിക്ക് ആ ഭൂമി നിഷേധിച്ചു. ഞാൻ പ്രശ്നം നബി(സ)യോട് പറഞ്ഞപ്പോൾ അവിടന്ന് എന്നോട് ചോദിച്ചു: "നിനക്ക് വല്ല തെളിവുമുണ്ടോ?" ഞാൻ ഇല്ല എന്നു പറഞ്ഞു: അപ്പോൾ അവിടന്ന് യഹൂദിയോട് പറഞ്ഞു: "നീ സത്യം ചെയ്യുക." ഞാൻ പറഞ്ഞു: റസൂലേ, എങ്കിൽ അവൻ സത്യം ചെയ്യുകയും എന്റെ മുതൽ കൊണ്ട് പോവുകയും ചെയ്യും. അപ്പോൾ: ''അല്ലാഹുവിന്റെ കരാർ കൊണ്ടും തങ്ങളുടെ സത്യം കൊണ്ടും തുഛമായ മുതൽ നേടുന്നവർ.'' എന്ന് തുടങ്ങുന്ന സുക്തം അല്ലാഹു ഇറക്കി. (ദ,തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 595, 595, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنِ الْأَشْعَثِ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلاً مِنْ كِنْدَةَ وَرَجُلاً مِنْ حَضْرَمَوْتَ اخْتَصَمَا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي أَرْضٍ مِنَ الْيَمَنِ، فَقَالَ الْحَضْرَمِيُّ: يَا رَسُولَ اللهِ، إِنَّ أَرْضِي اغْتَصَبَنِيهَا أَبُو هَذَا وَهِيَ فِي يَدِهِ. قَالَ: "هَلْ لَكَ بَيِّنَةٌ". قَالَ: لَا، وَلَكِنْ أُحَلِّفُهُ، وَاللهِ مَا يَعْلَمُ أَنَّهَا أَرْضِي اغْتَصَبَنِيهَا أَبُوهُ. فَتَهَيَّأَ الْكِنْدِيُّ لِلْيَمِينِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَقْتَطِعُ أَحَدٌ مَالًا بِيَمِينٍ إِلَّا لَقِيَ اللهَ وَهُوَ أَجْذَمُ". فَقَالَ الْكِنْدِيُّ: هِيَ أَرْضُهُ. (د)', 'അശ്അസുബ്നു ഖൈസ്(റ): കിൻദയിൽ നിന്നുള്ള ഒരാളും ഹളർമൗതിൽ നിന്നുള്ള ഒരാളും യമനിലെ ഒരു ഭൂമിയുടെ വിഷയത്തിലുള്ള തർക്കം നബി(സ)യോട് പറഞ്ഞു. ഹളർമൗതുകാരൻ പറഞ്ഞു: എന്റെ ഭൂമി ഇദ്ദേഹത്തിന്റെ പിതാവ് അപഹരിച്ചു. അതിപ്പോൾ ഇദ്ദേഹത്തിന്റെ കയ്യിലാണ്. നബി(സ) ചോദിച്ചു: "നിങ്ങൾക്ക് വല്ല തെളിവുമുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. പക്ഷേ, അത് എന്നിൽ നിന്ന് അദ്ദേഹത്തിന്റെ പിതാവ് അപഹരിച്ച മുതലാണെന്ന് അദ്ദേഹത്തിനറിയില്ല എന്ന് ഞാൻ സത്യം ചെയ്യിക്കാം. അപ്പോൾ കിൻദക്കാരൻ സത്യം ചെയ്യാനൊരുങ്ങി. അന്നേരം നബി(സ) പറഞ്ഞു: "സത്യം ചെയ്ത് മുതൽ അപഹരിക്കുന്നവൻ കുഷ്ഠരോഗം ബാധിച്ചവനായിട്ടായിരിക്കും അല്ലാഹുവിനെ കണ്ട്മുട്ടുക." അപ്പോൾ കിൻദക്കാരൻ പറഞ്ഞു: അത് അദ്ദേഹത്തിന്റെ ഭൂമിയാണ്. (ദ)', 'الْأَشْعَثِ بْنِ قَيْسٍ', 'അശ്അസുബ്നു ഖൈസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 595, 595, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي أُمَامَةَ – يَعْنِي الْحَارِثِيَّ – رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللهُ لَهُ النَّارَ، وَحَرَّمَ عَلَيْهِ الْجَنَّةَ". فَقَالَ لَهُ رَجُلٌ: يَا رَسُولَ اللهِ، وَإِنْ كَانَ شَيْئًا يَسِيرًا. قَالَ: "وَإِنْ قَضِيبًا مِنْ أَرَاكٍ". (م)', 'അബൂഉമാമ എന്ന അൽ ഹാരിസി(റ): റസൂൽ(സ) പറഞ്ഞു: "സത്യം ചെയ്യുക വഴി ആരെങ്കിലും ഒരു മുസ്ലിമിന്റെ അവകാശം തട്ടിയെടുത്താൽ അല്ലാഹു അവന് നരകം നിർബന്ധമാക്കുകയും സ്വർഗ്ഗം നിഷിദ്ധമാക്കുകയും ചെയ്യും." ഇതുകേട്ട ഒരാൾ നബി(സ)യോട് ആരാഞ്ഞു: അല്ലയോ റസൂലേ! ആ വസ്തു നിസ്സാരമായ ഒന്നാണെങ്കിലോ? തിരുമേനി(സ) അരുളി: "അറാക് മരത്തിന്റെ ഒരു ചില്ലയാണെങ്കിൽ പോലും." (മു)', 'أَبِي أُمَامَةَ – يَعْنِي الْحَارِثِيَّ –', 'അബൂഉമാമ എന്ന അൽ ഹാരിസി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 595, 595, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ وَائِلِ بْنِ حُجْرٍ الْحَضْرَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ مِنْ حَضْرَمَوْتَ وَرَجُلٌ مِنْ كِنْدَةَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ الْحَضْرَمِيُّ: يَا رَسُولَ اللهِ، إِنَّ هَذَا غَلَبَنِي عَلَى أَرْضٍ كَانَتْ لِأَبِي. فَقَالَ الْكِنْدِيُّ: هِيَ أَرْضِي فِي يَدِي أَزْرَعُهَا، لَيْسَ لَهُ فِيهَا حَقٌّ. قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْحَضْرَمِيِّ: "أَلَكَ بَيِّنَةٌ". قَالَ: لَا، قَالَ: "فَلَكَ يَمِينُهُ". قَالَ: يَا رَسُولَ اللهِ، إِنَّهُ فَاجِرٌ، لَا يُبَالِي مَا حَلَفَ عَلَيْهِ، لَيْسَ يَتَوَرَّعُ مِنْ شَيْءٍ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَ لَكَ مِنْهُ إِلَّا ذَاكَ". فَانْطَلَقَ لِيَحْلِفَ لَهُ، فَلَمَّا أَدْبَرَ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَا لَئِنْ حَلَفَ عَلَى مَالٍ لِيَأْكُلَهُ ظَالِمًا لَيَلْقَيَنَّ اللهَ عَزَّ وَجَلَّ وَهُوَ عَنْهُ مُعْرِضٌ". (م,د,ت,ن)', 'വാഇലുബിനുഹുജ്റുൽ ഹളറമീ(റ): ഹളർമൗതിൽ നിന്നുള്ള ഒരു മനുഷ്യനും കിൻദയിൽ നിന്നുള്ള ഒരാളും നബി(സ)യുടെ അടുത്ത് വന്നു. എന്നിട്ട് ഹളർമൗതുകാരൻ പറഞ്ഞു: റസൂലേ, എന്റെ പിതാവിന്റെ ഉടമസ്ഥതയിലായിരുന്ന ഭൂമി ഇദ്ദേഹം അപഹരിച്ചു. കിൻദക്കാരൻ പറഞ്ഞു: ഞാൻ കൃഷി ചെയ്തുകൊണ്ടിരിക്കുന്ന എന്റെ കൈവശമുള്ള ഭൂമിയാണിത്, അദ്ദേഹത്തിനതിൽ ഒരു അവകാശവുമില്ല. നബി(സ) ഹള്റമിയോട് ചോദിച്ചു: "നിനക്ക് വല്ല തെളിവുമുണ്ടോ?" അദ്ദേഹം ഇല്ല എന്നു പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "എങ്കിൽ നിനക്കവനെ സത്യം ചെയ്യിക്കാം." ഹള്റമി പറഞ്ഞു: റസൂലേ, അവൻ തെമ്മാടിയാണ്, താൻ എന്താണ് സത്യം ചെയ്യുന്നതെന്ന് അവൻ ശ്രദ്ധിക്കില്ല, ഒരു കാര്യത്തിലും അവൻ സൂക്ഷ്മത പുലർത്തുകയില്ല. നബി(സ) പറഞ്ഞു: "നിനക്ക് അവന്റെ സത്യമല്ലാതെ ഒന്നുമില്ല." അങ്ങനെ അയാൾ സത്യം ചെയ്യാൻ പുറപ്പെട്ടു. അയാൾ അതിനുവേണ്ടി തിരിഞ്ഞപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അക്രമപരമായി ഒരു മുതൽ ഭക്ഷിക്കാൻ വേണ്ടി അവൻ സത്യം ചെയ്താൽ, തന്നെ അവഗണിക്കുന്നവനായി അവൻ അല്ലാഹുവിനെ കണ്ടുമുട്ടും." (മു,ദ,തു,ന)', 'وَائِلِ بْنِ حُجْرٍ الْحَضْرَمِيِّ', 'വാഇലുബിനുഹുജ്റുൽ ഹളറമീ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 596, 596, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمْكُثُ عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ فَيَشْرَبُ عِنْدَهَا عَسَلًا، فَتَوَاصَيْتُ أَنَا وَحَفْصَةُ: أَنَّ أَيَّتَنَا دَخَلَ عَلَيْهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلْتَقُلْ: إِنِّي أَجِدُ مِنْكَ رِيحَ مَغَافِيرَ، أَكَلْتَ مَغَافِيرَ. فَدَخَلَ عَلَى إِحْدَاهُمَا فَقَالَتْ ذَلِكَ لَهُ، فَقَالَ: "لَا، بَلْ شَرِبْتُ عَسَلًا عِنْدَ زَيْنَبَ بِنْتِ جَحْشٍ، وَلَنْ أَعُودَ لَهُ". فَنَزَلَتْ: {يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللهُ لَكَ} إِلَى {إِنْ تَتُوبَا إِلَى اللهِ} عَائِشَةُ وَحَفْصَةُ {وَإِذْ أَسَرَّ النَّبِيُّ إِلَى بَعْضِ أَزْوَاجِهِ حَدِيثًا} لِقَوْلِهِ: "بَلْ شَرِبْتُ عَسَلًا". (ن)', 'ആഇശ(റ): നബി(സ) സൈനബ് ബിൻത് ജഹ്ശ്(റ)യുടെ അടുത്ത് താമസിക്കുകയും അവിടെ നിന്ന് തേൻ കുടിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. അങ്ങനെ ഞാനും ഹഫ്സ(റ)യും ഇപ്രകാരം തീരുമാനിച്ചു. ഞങ്ങളിൽ ആരുടെ അടുത്തേക്കെങ്കിലും നബി(സ) വന്നാൽ അവർ ഇപ്രകാരം പറയണം: ഞാൻ അങ്ങിൽ നിന്ന് മആഫീർ (ഉർഫുത് എന്ന മരത്തിൽ നിന്നൊലിക്കുന്ന മധുരമുള്ള പശ)ന്റെ വാസന അനുഭവിക്കുന്നു. അങ്ങ് മആഫീർ കഴിച്ചിട്ടുണ്ട്. അങ്ങനെ നബി(സ) അവരിൽ ഒരാളുടെ അടുത്ത് വരികയും അവർ അപ്രകാരം നബി(സ)യോട് പറയുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇല്ല, ഞാൻ സൈനബ് ബിൻത് ജഹ്ശിന്റെ അടുത്ത് നിന്ന് തേൻ കുടിച്ചിട്ടുണ്ട്, ഇനി ഞാനങ്ങനെ ചെയ്യില്ല." നബി(സ) "ഞാൻ തേനാണ് കുടിച്ചത്" എന്ന് പറഞ്ഞതിന്റെ പേരിൽ ''നബിയേ, അല്ലാഹു അങ്ങേക്ക് അനുവദനീയമാക്കിയത് എന്തിനാണ് അങ്ങ് നിഷിദ്ധമാക്കുന്നത്'' എന്നത് മുതൽ ''നിങ്ങൾ രണ്ടുപേരും അല്ലാഹുവിലേക്ക് പശ്ചാതപിച്ച് മടങ്ങിയാൽ'' അഥവാ ആഇശ(റ)യും ഹഫ്സ(റ)യും ''നബി തന്റെ ഒരു ഭാര്യയോട് ഒരു രഹസ്യം പറഞ്ഞ സമയം'' എന്നത് വരെയുള്ള സൂകതം ഇറങ്ങി. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 596, 596, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ قُتَيْلَةَ بِنْتِ صَيْفِيٍّ الْأَنْصَارِيَّةِ رَضِيَ اللهُ عَنْهَا: أَنَّ يَهُودِيًّا أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّكُمْ تُنَدِّدُونَ وَإِنَّكُمْ تُشْرِكُونَ، تَقُولُونَ: مَا شَاءَ اللهُ وَشِئْتَ، وَتَقُولُونَ: وَالْكَعْبَةِ. فَأَمَرَهُمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادُوا أَنْ يَحْلِفُوا أَنْ يَقُولُوا: "وَرَبِّ الْكَعْبَةِ". وَيَقُولُونَ: "مَا شَاءَ اللهُ ثُمَّ شِئْتَ". (ن)', 'ഖുതൈലാബിൻതു സൈഫിയ്യിൽ അൻസാരിയ്യ(റ): ഒരു ജൂതൻ ഒരിക്കൽ നബി(സ)യെ സമീപിച്ച് പറഞ്ഞു: നിങ്ങൾ പരസഹായം തേടുന്നു, നിങ്ങൾ ശിർക്ക് ചെയ്യുന്നു, നിങ്ങൾ പറയുന്നു: അല്ലാഹു ഉദ്ദേശിച്ചതും നീ ഉദ്ദേശിച്ചതും എന്ന്. നിങ്ങൾ പറയുന്നു: കഅബയെക്കൊണ്ട് സത്യം എന്ന്. തുടർന്ന് സത്യം ചെയ്യാൻ ഉദ്ദേശിച്ചാൽ "കഅബയുടെ നാഥനെക്കൊണ്ട് സത്യം", "അല്ലാഹു ഉദ്ദേശിച്ചതും പിന്നെ നീ ഉദ്ദേശിച്ചതും" എന്നിങ്ങനെ പറയാൻ നബി(സ) മുസ്ലിംകളോട് കൽപിച്ചു. (ന)', 'قُتَيْلَةَ بِنْتِ صَيْفِيٍّ الْأَنْصَارِيَّةِ', 'ഖുതൈലാബിൻതു സൈഫിയ്യിൽ അൻസാരിയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 597, 597, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ عَبْدِاللهِ بْنِ هِشَامٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ آخِذٌ بِيَدِ عُمَرَ بْنِ الْخَطَّابِ، فَقَالَ لَهُ عُمَرُ: يَا رَسُولَ اللهِ، لَأَنْتَ أَحَبُّ إِلَيَّ مِنْ كُلِّ شَيْءٍ إِلَّا مِنْ نَفْسِي، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا، وَالَّذِي نَفْسِي بِيَدِهِ، حَتَّى أَكُونَ أَحَبَّ إِلَيْكَ مِنْ نَفْسِكَ". فَقَالَ لَهُ عُمَرُ: فَإِنَّهُ الْآنَ، وَاللهِ، لَأَنْتَ أَحَبُّ إِلَيَّ مِنْ نَفْسِي، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْآنَ يَا عُمَرُ". (خ)', 'അബ്ദുല്ലാഹിബ്നു ഹിശാം(റ): ഒരിക്കൽ ഞങ്ങൾ നബി(സ)യുടെ കൂടെയുണ്ടായിരുന്നു. അവിടന്ന് ഉമറുബ്നുൽ ഖത്താബ്(റ)വിന്റെ കൈപിടിച്ചിരിക്കുകയായിരുന്നു. ഉമർ(റ) പറഞ്ഞു: അല്ലയോ തിരുദൂതരേ, ഞാനൊഴികെ മറ്റെല്ലാ വസ്തുക്കളെക്കാളും അങ്ങെനിക്ക് പ്രിയങ്കരനാണ്. നബി(സ) പറഞ്ഞു: "ഇല്ല! എന്റെ ആത്മാവ് ആരുടെ നിയന്ത്രണത്തിലാണോ അവൻ തന്നെ സത്യം, നിന്റെ ആത്മാവിനേക്കാൾ ഞാൻ നിനക്ക് പ്രിയപ്പെട്ടവൻ ആകുംവരെ (നീ സത്യ വിശ്വാസിയാവുകയില്ല)." ഉമർ(റ) പറഞ്ഞു: എങ്കിൽ അല്ലാഹുവാണെ സത്യം, ഇപ്പോൾ അങ്ങാണ് എന്റെ ആത്മാവിനേക്കാൾ എനിക്കേറ്റം പ്രിയപ്പെട്ടയാൾ. നബി(സ) പറഞ്ഞു: "ഇപ്പോൾ ശരി, ഉമറേ!" (ബു)', 'عَبْدِاللهِ بْنِ هِشَامٍ', 'അബ്ദുല്ലാഹിബ്നു ഹിശാം(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 597, 597, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، جَارِيَةٌ لِي صَكَكْتُهَا صَكَّةً، فَعَظَّمَ ذَلِكَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: أَفَلَا أُعْتِقُهَا؟ قَالَ: "ائْتِنِي بِهَا". قَالَ: فَجِئْتُ بِهَا. قَالَ: "أَيْنَ اللهُ". قَالَتْ: فِي السَّمَاءِ، قَالَ: "مَنْ أَنَا". قَالَتْ: أَنْتَ رَسُولُ اللهِ، قَالَ: "أَعْتِقْهَا فَإِنَّهَا مُؤْمِنَةٌ". (م,د,ن)', 'മുആവിയതുബ്നു ഹകമുസ്സുലമിയ്യ്(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ അടിമസ്ത്രീയെ ഞാൻ മർദ്ദിച്ചു. അപ്പോൾ റസൂൽ(സ) ആ വിഷയം എന്നോട് വളരെ ഗൗരവത്തോടെ സംസാരിച്ചു. അപ്പോൾ ഞാൻ നബി(സ)യോട് ചോദിച്ചു: അവളെ ഞാൻ മോചിപ്പിക്കട്ടെയോ? നബി(സ) പറഞ്ഞു: "അവളെ ഇവിടെ ഹാജരാക്കുക." അങ്ങനെ ഞാനവളെയും കൂട്ടി വന്നു. നബി(സ) അവളോട് ചോദിച്ചു: "അല്ലാഹു എവിടെയാണ്?" അവൾ പറഞ്ഞു: ആകാശത്തിലാണ്. നബി(സ) ചോദിച്ചു: "ഞാൻ ആരാണ്?" അവൾ പറഞ്ഞു: അങ്ങ് അല്ലാഹുവിന്റെ റസൂലാണ്. അപ്പോൾ നബി(സ) അരുളി: "ഇവൾ സത്യവിശ്വാസിനിയാണ്, ഇവളെ മോചിപ്പിക്കൂ." (മു,ദ,ന)', 'مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ', 'മുആവിയതുബ്നു ഹകമുസ്സുലമിയ്യ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 597, 597, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنِ الشَّرِيدِ رَضِيَ اللهُ عَنْهُ: أَنَّ أُمَّهُ أَوْصَتْهُ أَنْ يَعْتِقَ عَنْهَا رَقَبَةً مُؤْمِنَةً، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، إِنَّ أُمِّي أَوْصَتْ أَنْ أُعْتِقَ عَنْهَا رَقَبَةً مُؤْمِنَةً، وَعِنْدِي جَارِيَةٌ سَوْدَاءُ نُوبِيَّةٌ، فَذَكَرَ نَحْوَهُ. (د,ن)', 'ഷരീദ്(റ): അദ്ദേഹത്തിന്റെ മാതാവ് തനിക്ക്വേണ്ടി വിശ്വാസിനിയായ ഒരടിമസ്ത്രീയെ മോചിപ്പിക്കാൻ അദ്ദേഹത്തോട് വസ്വിയ്യത് ചെയ്തിരുന്നു. അദ്ദേഹം നബി(സ)യെ സമീപിച്ച് പറഞ്ഞു: എന്റെ ഉമ്മ അവർക്കു വേണ്ടി സത്യവിശ്വാസിനിയായ ഒരടിമസ്ത്രീയെ മോചിപ്പിക്കാൻ എന്നോട് വസ്വിയ്യത്ത് ചെയ്തിരുന്നു. എന്റെ പക്കൽ നൂബിയക്കാരിയായ ഒരു കറുത്ത അടിമസ്ത്രീയുണ്ട്. തുടർന്ന് മുകളിലുദ്ധരിക്കപ്പെട്ടതുപോലുള്ള ഒരു ഹദീസ് അവർ പറയുകയുണ്ടായി. (ദ,ന)', 'الشَّرِيدِ', 'ഷരീദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 598, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِجَارِيَةٍ سَوْدَاءَ، فَقَالَ: يَا رَسُولَ اللهِ، إِنَّ عَلَيَّ رَقَبَةً مُؤْمِنَةً. فَقَالَ لَهَا: "أَيْنَ اللهُ". فَأَشَارَتْ إِلَى السَّمَاءِ بِأُصْبُعِهَا، فَقَالَ لَهَا: "فَمَنْ أَنَا". فَأَشَارَتْ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَإِلَى السَّمَاءِ، يَعْنِي أَنْتَ رَسُولُ اللهِ، فَقَالَ: "أَعْتِقْهَا فَإِنَّهَا مُؤْمِنَةٌ". (د)', 'അബൂഹുറൈറ(റ): ഒരു കറുത്ത അടിമസ്ത്രീയുമായി ഒരാൾ നബി(സ)യുടെ സന്നിധിയിൽ എത്തി. അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് ഒരു അടിമസ്ത്രീയെ മോചിപ്പിക്കേണ്ടതുണ്ട്. അപ്പോൾ നബി(സ) അവളോട് ചോദിച്ചു: "അല്ലാഹു എവിടെയാണ്?" അന്നേരം ആകാശത്തിലേക്ക് അവൾ വിരൽ ചൂണ്ടി. നബി(സ) ചോദിച്ചു: "ഞാനാരാണ്?" അപ്പോൾ അവൾ നബിതുരുമേനി(സ)ക്കു നേർക്കും ശേഷം ആകാശത്തേക്കും വിരൽ ചൂണ്ടി. അതായത് താങ്കൾ അല്ലാഹുവിന്റെ റസൂൽ ആണെന്ന്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവളെ മോചിപ്പിക്കൂ, അവൾ സത്യവിശ്വസിനിയാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 598, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "وَاللهِ لَأَغْزُوَنَّ قُرَيْشًا، وَاللهِ لَأَغْزُوَنَّ قُرَيْشًا، وَاللهِ لَأَغْزُوَنَّ قُرَيْشًا". ثُمَّ قَالَ: "إِنْ شَاءَ اللهُ". وَفِي رِوَايَةٍ: ثُمَّ لَمْ يَغْزُهُمْ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവാണ് സത്യം, ഞാൻ ഖുറൈഷികളോട് യുദ്ധം ചെയ്യും. അല്ലാഹുവാണ് സത്യം, ഞാൻ ഖുറൈഷികളോട് യുദ്ധം ചെയ്യും, അല്ലാഹുവാണ് സത്യം, ഞാൻ ഖുറൈശികളോട് യുദ്ധം ചെയ്യും." ശേഷം അവിടുന്ന് "ഇൻഷാഅല്ലാഹ്" എന്നുകൂടി പറഞ്ഞു. മറ്റൊരു റിപ്പോർട്ടിൽ: പിന്നീട് അവിടുന്ന് അവരോട് യുദ്ധം ചെയ്തിട്ടില്ല. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 598, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=111), 1, 'وَفِي رِوَايَةٍ: ثُمَّ لَمْ يَغْزُهُمْ. (د)', 'മറ്റൊരു നിവേദനിൽ: പിന്നീട് അവിടുന്ന് അവരോട് യുദ്ധം ചെയ്തിട്ടില്ല. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ سُوَيْدِ بْنِ مُقَرِّنٍ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: لَقَدْ رَأَيْتُنَا سَبْعَةَ إِخْوَةٍ، مَا لَنَا خَادِمٌ إِلَّا وَاحِدَةٌ، فَلَطَمَهَا أَحَدُنَا، فَأَمَرَنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نُعْتِقَهَا. (م,د,ت)', 'സുവൈദുബ്നു മുഖർരിൻ അൽമുസ്നീ(റ): ഞങ്ങൾ ഏഴു സഹോദരങ്ങളാണ്. ഒരു സ്ത്രീയല്ലാതെ ഞങ്ങൾക്ക് മറ്റു ഭൃത്യന്മാർ ഉണ്ടായിരുന്നില്ല. ഞങ്ങളിൽ ഒരാൾ ആ സ്ത്രീയുടെ മുഖത്തടിച്ചു. അപ്പോൾ അവളെ മോചിപ്പിക്കാൻ നബി(സ) ഞങ്ങളോട് കൽപിച്ചു. (മു,ദ,തു)', 'سُوَيْدِ بْنِ مُقَرِّنٍ الْمُزَنِيِّ', 'സുവൈദുബ്നു മുഖർരിൻ അൽമുസ്നീ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 598, 598, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، إِنَّ أُخْتِي نَذَرَتْ أَنْ تَمْشِيَ إِلَى الْبَيْتِ حَافِيَةً غَيْرَ مُخْتَمِرَةٍ؟ فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ لَا يَصْنَعُ بِشَقَاءِ أُخْتِكَ شَيْئًا، فَلْتَرْكَبْ وَلْتَخْتَمِرْ، وَلْتَصُمْ ثَلَاثَةَ أَيَّامٍ". حَسَنٌ. (ق,د,ت,ن,جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): ഞാൻ നബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, തട്ടമിടാതെ, നഗ്നപാദയായി കഅ്ബയിലേക്ക് നടന്നുപോകാമെന്ന് എന്റെ സഹോദരി സത്യം ചെയ്തിട്ടുണ്ട്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിന്റെ സഹോദരി വിഷമിക്കുന്നതുകൊണ്ട് അല്ലാഹുവിനൊന്നും കിട്ടാനില്ല. അവർ തട്ടമിട്ട് വാഹനത്തിൽ പോവുകയും മൂന്നു ദിവസം നോമ്പനുഷ്ഠിക്കുകയും ചെയ്തുകൊള്ളട്ടെ." (ബു,മു,ദ,തു,ന,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: انْتَهَيْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ فِي ظِلِّ الْكَعْبَةِ: "هُمُ الْأَخْسَرُونَ وَرَبِّ الْكَعْبَةِ، هُمُ الْأَخْسَرُونَ وَرَبِّ الْكَعْبَةِ". قُلْتُ: مَا شَأْنِي أَيُرَى فِيَّ شَيْءٌ، مَا شَأْنِي؟ فَجَلَسْتُ إِلَيْهِ وَهُوَ يَقُولُ، فَمَا اسْتَطَعْتُ أَنْ أَسْكُتَ، وَتَغَشَّانِي مَا شَاءَ اللهُ، فَقُلْتُ: مَنْ هُمْ بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللهِ؟ قَالَ: "الْأَكْثَرُونَ أَمْوَالًا، إِلَّا مَنْ قَالَ: هَكَذَا، وَهَكَذَا، وَهَكَذَا". (خ)', 'അബൂദർറ്(റ): ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്നു. അവിടുന്ന് കഅ്ബയുടെ തണലിൽ ഇരുന്ന്കൊണ്ട് ഇങ്ങനെ പറയുന്നുണ്ടായിരുന്നു: "അവരാണ് നഷ്ടപ്പെട്ടവർ, കഅബയുടെ നാഥനാണ് സത്യം. അവരാണ് നഷ്ടപ്പെട്ടവർ, കഅബയുടെ നാഥനാണ് സത്യം." ഞാൻ മനസ്സിൽ പറഞ്ഞു: എനിക്കെന്താണ് പറ്റിയത്, എന്നിൽ എന്തെങ്കിലും മ്ലേഛത (നബി തിരുമേനി) കാണുന്നുണ്ടോ? ഞാൻ തിരുമേനി(സ)യുടെ സമീപത്തിരുന്നു. അവിടന്ന് അപ്പോഴും അങ്ങനെ പറയുന്നുണ്ടായിരുന്നു. മിണ്ടാതിരിക്കാൻ എനിക്ക് സാധിച്ചില്ല. ഞാൻ ചോദിച്ചു: എന്റെ വാപ്പയും ഉമ്മയും അവിടത്തേക്ക് ദണ്ഡമാണ്, അവർ ആരാണ് റസൂലേ? അവിടന്ന് പറഞ്ഞു: "ധാരാളം സമ്പത്തുള്ളവർ, ഇപ്രകാരവും ഇപ്രകാരവും ഇപ്രകാരവും പറഞ്ഞവരൊഴികെ." (ബു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَمُوتُ لِأَحَدٍ مِنَ الْمُسْلِمِينَ ثَلَاثَةٌ مِنَ الْوَلَدِ لَنْ تَمَسَّهُ النَّارُ إِلَّا تَحِلَّةَ الْقَسَمِ". (خ)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "മൂന്നുമക്കൾ മരണപ്പെട്ടുപോയ ഒരു മുസ്ലിമിനെ നരകം സ്പർശിക്കുകയില്ല. സത്യലംഘനത്തിന്റെ ശിക്ഷയായിട്ടല്ലാതെ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ تَجَاوَزَ لِأُمَّتِي عَمَّا وَسْوَسَتْ أَوْ حَدَّثَتْ بِهِ أَنْفُسَهَا، مَا لَمْ تَعْمَلْ بِهِ أَوْ تَكَلَّمْ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മനസ്സിൽ നിരൂപിക്കുകയോ ആത്മഗതം ചെയ്യുകയോ ചെയ്യുന്ന (തെറ്റായ) കാര്യങ്ങൾ അല്ലാഹു എന്റെ സമുദായത്തിന് പൊറുത്തുകൊടുത്തിരിക്കുന്നു. അവയനുസരിച്ച് പ്രവത്തിക്കുകയോ സംസാരിക്കുകയോ ചെയ്യാത്തിടത്തോളം." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 599, 599, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ قَيْسِ بْنِ أَبِي غَرَزَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نُسَمَّى السَّمَاسِرَةَ، فَأَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَبِيعُ، فَسَمَّانَا بِاسْمٍ هُوَ خَيْرٌ مِنْ اسْمِنَا، فَقَالَ: "يَا مَعْشَرَ التُّجَّارِ، إِنَّ هَذَا الْبَيْعَ يَحْضُرُهُ الْحَلْفُ وَالْكَذِبُ، فَشُوبُوا بَيْعَكُمْ بِالصَّدَقَةِ". وَفِي رِوَايَةٍ قَالَ: كُنَّا نَبِيعُ بِالْبَقِيعِ، فَأَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكُنَّا نُسَمَّى السَّمَاسِرَةَ، فَقَالَ: "يَا مَعْشَرَ التُّجَّارِ". فَسَمَّانَا بِاسْمٍ هُوَ خَيْرٌ مِنِ اسْمِنَا، ثُمَّ قَالَ: "إِنَّ هَذَا الْبَيْعَ يَحْضُرُهُ الْحَلِفُ وَالْكَذِبُ، فَشُوبُوهُ بِالصَّدَقَةِ". (ن)', 'ഖൈസുബ്നു അബീഗറസ(റ): ദല്ലാളുമാർ എന്നാണ് ഞങ്ങൾ അറിയപ്പെട്ടിരുന്നത്. ഞങ്ങൾ കച്ചവടം നടത്തുന്നതിനിടയ്ക്ക് തിരുദൂതർ(സ) ഞങ്ങളുടെ അടുത്തെത്തി. ഞങ്ങളുടെ പേരിനേക്കാൾ മെച്ചപ്പെട്ട മറ്റൊരു പേര് ഉപയോഗിച്ച് അവിടുന്ന് ഞങ്ങളെ സംബോധനം ചെയ്തു. അവിടുന്ന് പറഞ്ഞു: "അല്ലയോ കച്ചവടക്കാരേ, ഈ കച്ചവടത്തിൽ കളവും സത്യംചെയ്യലും കടന്നുവരും. അതിനാൽ നിങ്ങളുടെ കച്ചവടത്തെ ദാനധർമ്മവുമായി കലർത്തുക." മറ്റൊരു റിപ്പോർട്ടിൽ: അദ്ദേഹം പറഞ്ഞു: ബകീഅ് എന്ന സ്ഥലത്ത് ഞങ്ങൾ വ്യാപാരം ചെയ്യുകയായിരുന്നു. അപ്പോൾ തിരുദൂതർ(സ) ഞങ്ങൾക്കരികിലെത്തി. ഞങ്ങൾ ദല്ലാലുകൾ എന്നാണ് വിളിക്കപ്പെട്ടിരുന്നത്. നബി(സ) ഞങ്ങളെ കച്ചവടക്കാരേ എന്നു വിളിച്ചു. ഞങ്ങളുടെ പേരിനെക്കാൾ മെച്ചപ്പെട്ട പേര് കൊണ്ടാണ് അവിടുന്ന് ഞങ്ങളെ സംബോധനം ചെയ്തത്. അവിടുന്ന് പറഞ്ഞു: "ഈ വ്യാപാരത്തിൽ സത്യം ചെയ്യലും കള്ളം പറയലുമെല്ലാം ഉണ്ടാകാറുണ്ട്. അതുകൊണ്ട് നിങ്ങളതിനെ ദാനധർമ്മവുമായി കലർത്തുക." (ന)', 'قَيْسِ بْنِ أَبِي غَرَزَةَ', 'ഖൈസുബ്നു അബീഗറസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 599, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=117), 1, 'وَفِي رِوَايَةٍ قَالَ: كُنَّا نَبِيعُ بِالْبَقِيعِ، فَأَتَانَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكُنَّا نُسَمَّى السَّمَاسِرَةَ، فَقَالَ: "يَا مَعْشَرَ التُّجَّارِ". فَسَمَّانَا بِاسْمٍ هُوَ خَيْرٌ مِنِ اسْمِنَا، ثُمَّ قَالَ: "إِنَّ هَذَا الْبَيْعَ يَحْضُرُهُ الْحَلِفُ وَالْكَذِبُ، فَشُوبُوهُ بِالصَّدَقَةِ". (ن)', 'മറ്റൊരു നിവേദനിൽ: അദ്ദേഹം പറഞ്ഞു: ബകീഅ് എന്ന സ്ഥലത്ത് ഞങ്ങൾ വ്യാപാരം ചെയ്യുകയായിരുന്നു. അപ്പോൾ തിരുദൂതർ(സ) ഞങ്ങൾക്കരികിലെത്തി. ഞങ്ങൾ ദല്ലാലുകൾ എന്നാണ് വിളിക്കപ്പെട്ടിരുന്നത്. നബി(സ) ഞങ്ങളെ കച്ചവടക്കാരേ എന്നു വിളിച്ചു. ഞങ്ങളുടെ പേരിനെക്കാൾ മെച്ചപ്പെട്ട പേര് കൊണ്ടാണ് അവിടുന്ന് ഞങ്ങളെ സംബോധനം ചെയ്തത്. അവിടുന്ന് പറഞ്ഞു: "ഈ വ്യാപാരത്തിൽ സത്യം ചെയ്യലും കള്ളം പറയലുമെല്ലാം ഉണ്ടാകാറുണ്ട്. അതുകൊണ്ട് നിങ്ങളതിനെ ദാനധർമ്മവുമായി കലർത്തുക." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ قَيْسِ بْنِ أَبِي غَرَزَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَانَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ فِي السُّوقِ، فَقَالَ: "إِنَّ هَذِهِ السُّوقَ يُخَالِطُهَا اللَّغْوُ وَالْكَذِبُ، فَشُوبُوهَا بِالصَّدَقَةِ". وَفِي رِوَايَةٍ قَالَ: كُنَّا بِالْمَدِينَةِ نَبِيعُ الْأَوْسَاقَ وَنَبْتَاعُهَا، وَكُنَّا نُسَمِّي أَنْفُسَنَا السَّمَاسِرَةَ وَيُسَمِّينَا النَّاسُ، فَخَرَجَ إِلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ فَسَمَّانَا بِاسْمٍ هُوَ خَيْرٌ مِنَ الَّذِي سَمَّيْنَا أَنْفُسَنَا وَسَمَّانَا النَّاسُ، فَقَالَ: "يَا مَعْشَرَ التُّجَّارِ، إِنَّهُ يَشْهَدُ بَيْعَكُمُ الْحَلِفُ وَالْكَذِبُ، فَشُوبُوهُ بِالصَّدَقَةِ". (ن)', 'ഖൈസുബ്നു അബീഗറസ(റ): ഞങ്ങൾ അങ്ങാടിയിൽ ആയിരിക്കെ നബി(സ) ഞങ്ങളുടെ അടുത്ത് വന്നു. അവിടുന്ന് പറഞ്ഞു: "ഈ അങ്ങാടിയോട് അനാവശ്യ സംസാരങ്ങളും കള്ളവുമെല്ലാം കൂടിക്കലരും. അതിനാൽ ദാനധർമ്മം നിങ്ങൾ അതുമായി (കച്ചവടവുമായി) കലർത്തുക." മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: മദീനയിൽ ഞങ്ങൾ വസ്ഖുകൾ ക്രയവിക്രയം ചെയ്യുകയായിരുന്നു. ദല്ലാളുകൾ എന്നാണ് ജനങ്ങളും ഞങ്ങളും ഞങ്ങളെ വിളിച്ചിരുന്നത്. ഒരു ദിവസം നബി(സ) ഞങ്ങൾക്കരികെ വന്ന് ഞങ്ങളും ജനങ്ങളും ഞങ്ങളെ വിളിച്ചിരുന്ന പേരിനേക്കാൾ മെച്ചപ്പെട്ട മറ്റൊരു പേരിൽ ഞങ്ങളെ വിളിച്ചു. അവിടുന്ന് പറഞ്ഞു: "അല്ലയോ വ്യാപാരി സമൂഹമേ, നിങ്ങളുടെ കച്ചവടത്തിൽ കള്ളം പറച്ചിലും സത്യംചെയ്യലും ഒക്കെ ഉണ്ടാകാറുണ്ട്. അതിനാൽ നിങ്ങൾ ദാനധർമ്മവുമായി അതിനെ ചേർക്കുക." (ന)', 'قَيْسِ بْنِ أَبِي غَرَزَةَ', 'ഖൈസുബ്നു അബീഗറസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 600, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=8 and h.hadith_no=118), 1, 'وَفِي رِوَايَةٍ قَالَ: كُنَّا بِالْمَدِينَةِ نَبِيعُ الْأَوْسَاقَ وَنَبْتَاعُهَا، وَكُنَّا نُسَمِّي أَنْفُسَنَا السَّمَاسِرَةَ وَيُسَمِّينَا النَّاسُ، فَخَرَجَ إِلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ فَسَمَّانَا بِاسْمٍ هُوَ خَيْرٌ مِنَ الَّذِي سَمَّيْنَا أَنْفُسَنَا وَسَمَّانَا النَّاسُ، فَقَالَ: "يَا مَعْشَرَ التُّجَّارِ، إِنَّهُ يَشْهَدُ بَيْعَكُمُ الْحَلِفُ وَالْكَذِبُ، فَشُوبُوهُ بِالصَّدَقَةِ". (ن)', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: മദീനയിൽ ഞങ്ങൾ വസ്ഖുകൾ ക്രയവിക്രയം ചെയ്യുകയായിരുന്നു. ദല്ലാളുകൾ എന്നാണ് ജനങ്ങളും ഞങ്ങളും ഞങ്ങളെ വിളിച്ചിരുന്നത്. ഒരു ദിവസം നബി(സ) ഞങ്ങൾക്കരികെ വന്ന് ഞങ്ങളും ജനങ്ങളും ഞങ്ങളെ വിളിച്ചിരുന്ന പേരിനേക്കാൾ മെച്ചപ്പെട്ട മറ്റൊരു പേരിൽ ഞങ്ങളെ വിളിച്ചു. അവിടുന്ന് പറഞ്ഞു: "അല്ലയോ വ്യാപാരി സമൂഹമേ, നിങ്ങളുടെ കച്ചവടത്തിൽ കള്ളം പറച്ചിലും സത്യംചെയ്യലും ഒക്കെ ഉണ്ടാകാറുണ്ട്. അതിനാൽ നിങ്ങൾ ദാനധർമ്മവുമായി അതിനെ ചേർക്കുക." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ: أَمَرَنَا بِاتِّبَاعِ الْجَنَائِزِ، وَعِيَادَةِ الْمَرِيضِ، وَتَشْمِيتِ الْعَاطِسِ، وَإِجَابَةِ الدَّاعِي، وَنَصْرِ الْمَظْلُومِ، وَإِبْرَارِ الْقَسَمِ، وَرَدِّ السَّلَامِ. (ن)', 'ബറാഉബ്നു ആസിബ്(റ): തിരുദൂതർ(സ) ഞങ്ങളോട് ഏഴുകാര്യങ്ങൾ കൽപ്പിച്ചു: ജനാസയെ പിന്തുടരുക, രോഗിയെ സന്ദർശിക്കുക, തുമ്മുന്ന ആൾക്ക് തശ്മീത് ചൊല്ലുക (യർഹമുകല്ലാഹു എന്ന് പറയുക), ക്ഷണിക്കുന്നവന്റെ ക്ഷണം സ്വീകരിക്കുക, മർദ്ദിതനെ സഹായിക്കുക, സത്യം ചെയ്താൽ പാലിക്കുക, സലാം മടക്കുക എന്നിവയാണവ. (ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 600, 600, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الطَّالِبَ الْبَيِّنَةَ، فَلَمْ تَكُنْ لَهُ بَيِّنَةٌ، فَاسْتَحْلَفَ الْمَطْلُوبَ فَحَلَفَ بِاللهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَلَى قَدْ فَعَلْتَ، وَلَكِنْ قَدْ غُفِرَ لَكَ بِإِخْلَاصِ قَوْلِ: لَا إِلَهَ إِلَّا اللهُ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): രണ്ടുപേർ നബി(സ)യുടെ സന്നിധിയിൽ വന്ന് പ്രശ്നമുന്നയിച്ചു. വാദിയോട് നബി(സ) തെളിവാവശ്യപ്പെട്ടു. അയാൾക്ക് തെളിവുണ്ടായിരുന്നില്ല. അപ്പോൾ ആരോപണ വിധേയനായ വ്യക്തിയോട് സത്യം ചെയ്യാൻ തിരുമേനി(സ) ആവശ്യപ്പെട്ടു. ഒരേയൊരാരാധ്യനായ അല്ലാഹുവിനെക്കൊണ്ട് സത്യം എന്ന് അയാൾ സത്യം ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അതെ, താങ്കളത് ചെയ്തിട്ടുണ്ട്. പക്ഷെ, ലാഇലാഹഇല്ലല്ലാഹ് എന്ന വചനത്തിന്റെ ആത്മാർത്ഥത കാരണം അല്ലാഹു നിങ്ങൾക്ക് പൊറുത്തുതന്നിരിക്കുന്നു." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 601, 601, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَزَلَ بِنَا أَضْيَافٌ لَنَا، قَالَ: وَكَانَ أَبُو بَكْرٍ يَتَحَدَّثُ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ، فَقَالَ: لَا أَرْجِعَنَّ إِلَيْكَ حَتَّى تَفْرُغَ مِنْ ضِيَافَةِ هَؤُلَاءِ وَمِنْ قِرَاهُمْ. فَأَتَاهُمْ بِقِرَاهُمْ، فَقَالُوا: لَا نَطْعَمُهُ حَتَّى يَأْتِيَ أَبُو بَكْرٍ، فَجَاءَ فَقَالَ: مَا فَعَلَ أَضْيَافُكُمْ؟ أَفَرَغْتُمْ مِنْ قِرَاهُمْ؟ قَالُوا: لَا، قُلْتُ: قَدْ أَتَيْتُهُمْ بِقِرَاهُمْ فَأَبَوْا، وَقَالُوا: وَاللهِ لَا نَطْعَمُهُ حَتَّى يَجِيءَ فَقَالُوا: صَدَقَ، قَدْ أَتَانَا بِهِ فَأَبَيْنَا حَتَّى تَجِيءَ. قَالَ: فَمَا مَنَعَكُمْ؟ قَالُوا: مَكَانَكَ، قَالَ: وَاللهِ لَا أَطْعَمُهُ اللَّيْلَةَ، قَالَ: فَقَالُوا: وَنَحْنُ وَاللهِ لَا نَطْعَمُهُ حَتَّى تَطْعَمَهُ، قَالَ: مَا رَأَيْتُ فِي الشَّرِّ كَاللَّيْلَةِ قَطُّ، قَالَ: قَرِّبُوا طَعَامَكُمْ، فَقَالَ: بِسْمِ اللهِ، فَطَعِمَ وَطَعِمُوا، فَأُخْبِرْتُ أَنَّهُ أَصْبَحَ فَغَدَا عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِالَّذِي صَنَعَ وَصَنَعُوا، قَالَ: "بَلْ أَنْتَ أَبَرُّهُمْ وَأَصْدَقُهُمْ". (ق,د)', 'അബ്ദുറഹ്മാനുബ്നു അബീബകർ(റ): കുറച്ചാളുകൾ ഞങ്ങൾക്ക് അതിഥികളായെത്തി. ആ രാത്രിയിൽ അബൂബക്കർ(റ) നബി(സ)യുടെ സവിധത്തിൽ വർത്തമാനം പറഞ്ഞു കൊണ്ടിരിക്കുകയായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: അതിഥി സൽക്കാരം കഴിഞ്ഞ ശേഷമല്ലാതെ ഞാൻ നിന്റെ അടുത്തേക്ക് മടങ്ങിവരികയില്ല തീർച്ച. അങ്ങനെ അബ്ദുർറഹ്മാൻ(റ) സൽക്കാരവിഭവങ്ങളുമായി അതിഥികൾക്കു മുമ്പിലെത്തി. അവർ പറഞ്ഞു: അബൂബക്കർ(റ) വരുന്നതുവരെ ഞങ്ങളിത് കഴിക്കുകയില്ല. ഒടുവിൽ അബൂബക്കർ(റ) എത്തി. അദ്ദേഹം ചോദിച്ചു: എന്താണ് അതിഥികളുടെ വിശേഷം? അവരെ സൽക്കരിച്ചു കഴിഞ്ഞോ? അവർ പറഞ്ഞു: ഇല്ല. അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാനവർക്ക് ഭക്ഷണവിഭവങ്ങൾ നൽകി. പക്ഷേ അവരത് കഴിക്കാൻ കൂട്ടാക്കിയല്ല. അല്ലാഹുവാണ് സത്യം! അദ്ദേഹം വരുവോളം ഞങ്ങൾ ഭക്ഷണം കഴിക്കുകയില്ല എന്ന് അവർ പറയുകയും ചെയ്തു. അവർ പറഞ്ഞു: അതെ, അദ്ദേഹം ആഹാരം കൊണ്ടു വന്നു. താങ്കൾ വരുന്നത് വരെ അത് കഴിക്കുകയില്ലെന്ന് ഞങ്ങൾ പറഞ്ഞു. അബൂബക്കർ(റ) ചോദിച്ചു: ഭക്ഷണം കഴിക്കാൻ എന്തായിരുന്നു നിങ്ങളുടെ തടസ്സം? അവർ പറഞ്ഞു: താങ്കളുടെ പദവി. അബൂബക്കർ(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഈ രാത്രി ഞാനത് ആഹരിക്കുകയില്ല. അപ്പോൾ അതിഥികൾ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, താങ്കൾ ഭക്ഷണം കഴിക്കുംവരെ ഞങ്ങളും അത് കഴിക്കുകയില്ല. അബൂബക്കർ(റ) പറഞ്ഞു: ഇതുപോലൊരു വിഷമം നിറഞ്ഞ രാത്രി ഞാൻ കണ്ടിട്ടേയില്ല! ഒടുവിൽ അബൂബക്കർ(റ) പറഞ്ഞു: ശരി, ഭക്ഷണം കൊണ്ടുവരൂ! ശേഷം ബിസ്മില്ലാഹി എന്ന് പറഞ്ഞ് അദ്ദേഹം ഭക്ഷണം കഴിച്ചു. അവരും കഴിച്ചു. നേരം വെളുത്തപ്പോൾ അദ്ദേഹം വിവരങ്ങളെല്ലാം നബി(സ)യെ അറിയിച്ചു കഴിഞ്ഞുവെന്ന് ഞാനറിഞ്ഞു. അപ്പോൾ നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "താങ്കളാണ് അവരിൽ ഏറ്റവും കൂടുതൽ സത്യം പാലിച്ചവനും സത്യസന്ധനും." (ബു,മു,ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ', 'അബ്ദുറഹ്മാനുബ്നു അബീബകർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 601, 601, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتْ يَمِينٌ يَحْلِفُ عَلَيْهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا وَمُقَلِّبِ الْقُلُوبِ". (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) സത്യം ചെയ്യുവാൻ ഉപയോഗിക്കാറുണ്ടായിരുന്ന ഒരു വചനം "ഇല്ല, ഹൃദയങ്ങളെ മാറ്റിമറിക്കുന്നവനെക്കൊണ്ട് സത്യം" എന്നതായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتْ يَمِينُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الَّتِي يَحْلِفُ بِهَا: "لَا وَمُصَرِّفِ الْقُلُوبِ". (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) സത്യംചെയ്യാറുണ്ടായിരുന്ന വചനം "ലാ വ മുസ്വർരിഫുൽ ഖൂലൂബ് (ഇല്ല, ഹൃദയങ്ങളെ തിരിക്കുന്നവൻ തന്നെയാണ് സത്യം)" എന്നതായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ الصَّاعُ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُدًّا وَثُلُثًا بِمُدِّكُمُ الْيَوْمَ. (خ)', 'സാഇബുബ്നു യസീദ്(റ): നബി(സ)യുടെ കാലത്തെ ഒരു സ്വാഅ് എന്നത് ഇന്നത്തെ നിങ്ങളുടെ ഒരു മുദ്ദും കൂടെ മൂന്നിലൊന്ന് മുദ്ദും ആണ്. (ബു)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اللَّهُمَّ بَارِكْ لَهُمْ فِي مِكْيَالِهِمْ، وَصَاعِهِمْ، وَمُدِّهِمْ". (خ)', 'അനസ്ബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, അവരുടെ അളവിൽ നീ അനുഗ്രഹം ചൊരിയണമേ, അവരുടെ സ്വാഇലും മുദ്ദിലും." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "نَحْنُ الْآخِرُونَ السَّابِقُونَ يَوْمَ الْقِيَامَةِ". وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَاللهِ، لَأَنْ يَلِجَّ أَحَدُكُمْ بِيَمِينِهِ فِي أَهْلِهِ آثَمُ لَهُ عِنْدَ اللهِ مِنْ أَنْ يُعْطِيَ كَفَّارَتَهُ الَّتِي افْتَرَضَ اللهُ عَلَيْهِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നാം ഒടുവിലത്തെ ജനവിഭാഗമാണെങ്കിലും അന്ത്യനാളിൽ നാമായിരിക്കും ആദ്യം മുന്നോട്ടുഗമിക്കുന്നവർ." റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവാണ് സത്യം, തന്റെ ഭാര്യയെപ്പറ്റി ചെയ്ത സത്യത്തിൽ ഒരാൾ ഉറച്ചുനിൽക്കുന്നത്, അല്ലാഹു നിശ്ചയിച്ച പ്രായശ്ചിത്തം ചെയ്താലും അല്ലാഹുവിങ്കൽ കുറ്റകരമാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 602, 602, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
