അബൂദാവൂദ്(റ) പറഞ്ഞു: സത്യം ചെയ്യലിനെപ്പറ്റി നബിതിരുമേനി(സ)യിൽ നിന്നുദ്ധരിക്കപ്പെട്ട എല്ലാ ഹദീസുകളും സത്യലംഘനത്തിന് പ്രായശ്ചിത്തം ചെയ്യണമെന്ന് വ്യക്തമാക്കുന്നവയാണ്, പരിഗണനാർഹമല്ലാത്ത ചിലതൊഴികെ. (ദ,ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 593, 594, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
